+ (NSString *) returnNewBaseDate
{
    NSInteger currentDateYear=[[MyClass convertToNSStringWithNSDate:[NSDate date] DateFormat:@"yyyy"] integerValue];
    return [NSString stringWithFormat:@"01-Jan-%ld",(long)(currentDateYear-10)];
}


