//open the db
+(sqlite3 *) openDB{

    sqlite3 *isdb;
    NSArray *paths = NSSearchPathForDirectoriesInDomains(NSDocumentDirectory, NSUserDomainMask, YES);
    if (sqlite3_open([[[paths objectAtIndex:0] stringByAppendingPathComponent:@"isdb.sql"] UTF8String], &isdb)!=SQLITE_OK){
        sqlite3_close(isdb);
        NSAssert(0,@"Database failed to open");
        return nil;
    }else{
        NSLog(@"Database opened");
        return isdb;
    }
}

+ (NSString *) findnumberofclasstomonthend:(NSString *)classdate noofmonth:(NSString *)noofmonth schedulekey:(NSString *)schedulekey schedulerecord:(ScheduleRecord *)schedulerecord roundingcheck:(BOOL)roundingcheck
{
    
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    NSDateFormatter *df =[[NSDateFormatter alloc]init];
    df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    NSDateComponents *dateComponents = [[NSDateComponents alloc] init];
    long noofclass=0;
    NSString *startdatestring;
    NSDate *xdate;
    NSString *startdatetimestring;
    ScheduleDetailsRecord *scheduledetailsobject;
    
    if ([classdate length]>=11) {
        if ([schedulekey intValue]<0) {
            
            [df setDateFormat:@"dd-MMM-yyyy"];
            NSDate *startdate = [df dateFromString:[classdate substringToIndex:11]];
            [df setDateFormat:@"EEE"];
            NSString *dayofweek=[df stringFromDate:startdate];
            //[df setDateFormat:@"yyyy-MM-dd"];
            
            if (globalvariables.centerrecord.renewmonthlyroundup && roundingcheck) {
                if (![self firstclassinthemonthwithclassdate:startdate schedulekey:schedulekey dayofweek:dayofweek schedulerecord:schedulerecord]) {
                    noofmonth=[NSString stringWithFormat:@"%d",[noofmonth intValue]+1];
                }
            }
            
            
            [dateComponents setMonth:[noofmonth intValue]];
            
            
            NSCalendar *calendar = [NSCalendar currentCalendar];
            NSDate *enddate = [calendar dateByAddingComponents:dateComponents toDate:startdate options:0];
            [df setDateFormat:@"dd-MMM-yyyy"];
            NSString *enddatestring=[df stringFromDate:enddate];
            enddatestring=[NSString stringWithFormat:@"%@%@ %@",@"01",[[enddatestring substringFromIndex:2] substringToIndex:9],@"23:59"];
            [df setDateFormat:@"dd-MMM-yyyy HH:mm"];
            enddate=[[df dateFromString:enddatestring] dateByAddingTimeInterval:-24*60*60];
            
            long startingindex=[MyClass returnDateOffsetWithDate:startdate];
            
            
            for (long i=startingindex; i<startingindex+3650; i+=7) {
                [df setDateFormat:@"dd-MMM-yyyy"];
                xdate=[df dateFromString:[MyClass returnDateFromBaseDateWithOffset:i]];
                if ([MyClass isWorkingDate:xdate includereserveddate:NO]){
                    if ([xdate compare:enddate]!=NSOrderedDescending) {
                        noofclass+=1;
                    }else{
                        return [NSString stringWithFormat:@"%ld",noofclass];
                    }
                }
            }
            
        }else{
            if ([classdate length]!=17 || [[classdate substringFromIndex:[classdate length]-5] isEqualToString:@"Multi"]) {
                classdate=[NSString stringWithFormat:@"%@ %@",[classdate substringToIndex:11],@"00:00"];
            }
        
            [df setDateFormat:@"dd-MMM-yyyy HH:mm"];
            NSDate *startdate=[df dateFromString:classdate];
            
            //find month enddate
            
            
            if (globalvariables.centerrecord.renewmonthlyroundup && roundingcheck) {
                if (![self firstclassinthemonthwithclassdate:startdate schedulekey:schedulekey dayofweek:nil schedulerecord:schedulerecord]) {
                    noofmonth=[NSString stringWithFormat:@"%d",[noofmonth intValue]+1];
                }
            }
            
            [dateComponents setMonth:[noofmonth intValue]];
            
            
            NSCalendar *calendar = [NSCalendar currentCalendar];
            NSDate *enddate = [calendar dateByAddingComponents:dateComponents toDate:startdate options:0];
            
            NSString *enddatestring=[df stringFromDate:enddate];
            enddatestring=[NSString stringWithFormat:@"%@%@ %@",@"01",[[enddatestring substringFromIndex:2] substringToIndex:9],@"23:59"];
            enddate=[[df dateFromString:enddatestring] dateByAddingTimeInterval:-24*60*60];
            
            
            NSArray *allweekarray=[MyClass returnschedulearraywithschedulerecord:schedulerecord];
            
            [df setDateFormat:@"dd-MMM-yyyy HH:mm"];
            
            long startingindex=[MyClass returnDateOffsetWithDate:startdate];
            
            //NSDate *scheduleenddate;
            //if(![schedulerecord.enddate isEqualToString:@""]){
            NSDate *scheduleenddate=[MyClass convertToNSDateWithDate:[NSString stringWithFormat:@"%@ 23:59",schedulerecord.enddate] DateFormat:@"dd-MMM-yyyy HH:mm"];
            //}
            
            for (long i=startingindex; i<startingindex+3650; i++) {
                startdatestring=[MyClass returnDateFromBaseDateWithOffset:i];
                startdate=[MyClass convertToNSDateWithDate:startdatestring DateFormat:@"dd-MMM-yyyy"];
                long weeknumber=[MyClass returndayofweeknumber:[MyClass returndayofweek:startdatestring]]-1;
                
                if ([MyClass isWorkingDate:startdate includereserveddate:NO]) {
                    for (int j=0; j<((NSMutableArray *)[allweekarray objectAtIndex:weeknumber]).count; j++) {
                        scheduledetailsobject=[((NSMutableArray *)[allweekarray objectAtIndex:weeknumber]) objectAtIndex:j];
                        
                        startdatetimestring=[NSString stringWithFormat:@"%@ %@",startdatestring,scheduledetailsobject.classtime];
                        xdate=[df dateFromString:startdatetimestring];
                        //if ([xdate compare:startdate]!=NSOrderedAscending){
                        if ([xdate compare:enddate]!=NSOrderedDescending && (!scheduleenddate || [xdate compare:scheduleenddate]!=NSOrderedDescending)) {
                            noofclass+=1;
                        }else{
                            return [NSString stringWithFormat:@"%ld",noofclass];
                        }
                        //}
                    }
                }
            }
        }
    }
    
    return @"";
}

+(BOOL) firstclassinthemonthwithclassdate:(NSDate *)classdate schedulekey:(NSString *)schedulekey dayofweek:(NSString *)dayofweek schedulerecord:(ScheduleRecord *)schedulerecord
{

    
    NSDateFormatter *df =[[NSDateFormatter alloc]init];
    df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    NSString *startdatestring;
    NSDate *startdate;
    NSString *startdatetimestring;
    ScheduleDetailsRecord *scheduledetailsobject;
    
    if ([schedulekey intValue]<0) {
        [df setDateFormat:@"dd-MMM-yyyy"];

        //find first class in the month
        NSString *firstdayofthemonth=[NSString stringWithFormat:@"01%@",[[df stringFromDate:classdate] substringFromIndex:2]];
        long startingindex=[MyClass returnDateOffsetWithDate:[df dateFromString:firstdayofthemonth]];
        
        for (long i=startingindex; i<startingindex+3650; i++) {
            startdatestring=[MyClass returnDateFromBaseDateWithOffset:i];
            if ([MyClass isWorkingDate:[MyClass convertToNSDateWithDate:startdatestring DateFormat:@"dd-MMM-yyyy"] includereserveddate:NO]) {
                if ([[MyClass returndayofweek:startdatestring] isEqualToString:dayofweek]) {
                    if ([[df stringFromDate:classdate] isEqualToString:startdatestring]) {
                        return YES;
                    }else{
                        return NO;
                    }
                }
            }
        }

    }else{
        
        NSArray *allweekarray=[MyClass returnschedulearraywithschedulerecord:schedulerecord];
        [df setDateFormat:@"dd-MMM-yyyy HH:mm"];
        
        NSString *firstdayofthemonth=[NSString stringWithFormat:@"01%@",[[df stringFromDate:classdate] substringFromIndex:2]];
        long startingindex=[MyClass returnDateOffsetWithDate:[df dateFromString:firstdayofthemonth]];
        
        
        for (long i=startingindex; i<startingindex+3650; i++) {
            startdatestring=[MyClass returnDateFromBaseDateWithOffset:i];
            startdate=[MyClass convertToNSDateWithDate:startdatestring DateFormat:@"dd-MMM-yyyy"];
            long weeknumber=[MyClass returndayofweeknumber:[MyClass returndayofweek:startdatestring]]-1;
            
            if ([MyClass isWorkingDate:startdate includereserveddate:NO]) {
                if (((NSMutableArray *)[allweekarray objectAtIndex:weeknumber]).count>0) {
                    scheduledetailsobject=[((NSMutableArray *)[allweekarray objectAtIndex:weeknumber]) firstObject];
                    
                    startdatetimestring=[NSString stringWithFormat:@"%@ %@",startdatestring,scheduledetailsobject.classtime];
                    
                    if ([[df stringFromDate:classdate] isEqualToString:startdatetimestring]) {
                        return YES;
                    }else{
                        return NO;
                    }
                }
            }
        }

    }
    

    return FALSE;
}

+(void) showconnectionlostdialogbox
{
    if ([[UIApplication sharedApplication] applicationState]==UIApplicationStateActive) {
        GlobalVariables *globalvariables;
        globalvariables=[GlobalVariables singleObj];
        [MyClass loadingindicatorwithoption:@"stop" color:nil];
        
        if (globalvariables.languagetitledictionary.count>0) {
            UIAlertController *erroralert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Connection Error"] message:[MyClass returntitlewithtitle:@"Server connection is not available. Please check your internet connection and try again"] preferredStyle:UIAlertControllerStyleAlert];
            
            UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                [erroralert dismissViewControllerAnimated:YES completion:nil];
            }];
            
            [erroralert addAction:OKAction];
            [[self topMostController] presentViewController:erroralert animated:YES completion:nil];
        }else{
            if ([globalvariables.language isEqualToString:@"English"]) {
                UIAlertController *erroralert = [UIAlertController alertControllerWithTitle:@"Connection Error" message:@"Server connection is not available. Please check your internet connection and try again" preferredStyle:UIAlertControllerStyleAlert];
                
                UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                    [erroralert dismissViewControllerAnimated:YES completion:nil];
                }];
                
                [erroralert addAction:OKAction];
                [[self topMostController] presentViewController:erroralert animated:YES completion:nil];

            }else{
                UIAlertController *erroralert = [UIAlertController alertControllerWithTitle:@"連接錯誤" message:@"無法連接服務器。請檢查您的網絡連接，然後再試一次" preferredStyle:UIAlertControllerStyleAlert];
                
                UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                    [erroralert dismissViewControllerAnimated:YES completion:nil];
                }];
                
                [erroralert addAction:OKAction];
                [[self topMostController] presentViewController:erroralert animated:YES completion:nil];
            }
        }
    }
}





