+ (NSMutableArray *) retrieveClassroomListwithstatus:(NSString *)status withTBD:(BOOL)withTBD flushcachedata:(BOOL)flushcachedata
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    
    if (flushcachedata) {
        [MyClass getLatestDataSetv2withParameters:@"classroom" Centerkeys:globalvariables.centerrecord.centerkey completionBlock:nil];
    }
    
    NSMutableArray *tmpclassroomlistarray=[[NSMutableArray alloc]initWithArray:[globalvariables.classroomlistarray allValues]];

    NSPredicate *predicate = [NSPredicate predicateWithFormat:@"self.centerkey=%@",globalvariables.centerrecord.centerkey];
    if (![status isEqualToString:@"All"]) {
        NSPredicate *newpredicate = [NSPredicate predicateWithFormat:@"self.status=%@",status];
        predicate=[NSCompoundPredicate andPredicateWithSubpredicates:@[predicate,newpredicate]];
        
    }
    
    
    
    tmpclassroomlistarray=[[NSMutableArray alloc]initWithArray:[tmpclassroomlistarray filteredArrayUsingPredicate:predicate]];
    
    //sort
    NSSortDescriptor *sortByClassroom = [NSSortDescriptor sortDescriptorWithKey:@"classroom" ascending:YES selector:@selector(localizedStandardCompare:)];
    NSArray *sortDescriptors = @[sortByClassroom];
    tmpclassroomlistarray = [NSMutableArray arrayWithArray:[tmpclassroomlistarray sortedArrayUsingDescriptors:sortDescriptors]];
    
    if (withTBD) {
        [tmpclassroomlistarray addObject:[[ClassroomRecord alloc]initClassroomRecordWithcenterkey:@"" classroomkey:@"" classroom:@"TBD" status:@"In Service" remarks:@"" capacity:@"" colorcode:0]];
    }

    return tmpclassroomlistarray;
    
}

+ (NSMutableArray *) retrieveArcodeListwithflushcachedata:(BOOL)flushcachedata
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    
    if (flushcachedata) {
        [MyClass getLatestDataSetv2withParameters:@"arcode" Centerkeys:globalvariables.centerrecord.centerkey completionBlock:nil];
    }
    
    NSMutableArray *tmparcodelistarray=[[NSMutableArray alloc]initWithArray:[globalvariables.arcodelistarray allValues]];
    
