+(NSMutableArray *) retrieveStaffListwithvalid:(NSString *)valid role:(NSString *)role flushcachedata:(BOOL)flushcachedata
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    
    
    if ([role isEqualToString:@"Teaching"]) {
        role=@"Instructor";
    }
    
    if (flushcachedata) {
        [MyClass getLatestDataSetv2withParameters:@"staff,userroleandprivilege" Centerkeys:globalvariables.centerrecord.centerkey completionBlock:nil];
    }
    
    
    NSMutableArray *tmpstafflistarray=[[NSMutableArray alloc]initWithArray:[globalvariables.stafflistarray allValues]];
    
    NSPredicate *predicate = [NSPredicate predicateWithFormat:@"self.centerkey=%@",globalvariables.centerrecord.centerkey];
    if (![role isEqualToString:@"All"]) {
        if ([role isEqualToString:@"Instructor"]) {
            NSPredicate *newpredicate = [NSPredicate predicateWithFormat:@"self.role=%@",@"Instructor"];
            predicate=[NSCompoundPredicate andPredicateWithSubpredicates:@[predicate,newpredicate]];
        }else{
            NSPredicate *newpredicate = [NSPredicate predicateWithFormat:@"self.role!=%@",@"Instructor"];
            predicate=[NSCompoundPredicate andPredicateWithSubpredicates:@[predicate,newpredicate]];
        }
    }
    
    if (![valid isEqualToString:@"All"]) {
        NSPredicate *newpredicate = [NSPredicate predicateWithFormat:@"self.status=%@",valid];
        predicate=[NSCompoundPredicate andPredicateWithSubpredicates:@[predicate,newpredicate]];
    }
    
    NSPredicate *newpredicate = [NSPredicate predicateWithFormat:@"self.role!=%@",@"System"];
    predicate=[NSCompoundPredicate andPredicateWithSubpredicates:@[predicate,newpredicate]];
    
    tmpstafflistarray=[[NSMutableArray alloc]initWithArray:[tmpstafflistarray filteredArrayUsingPredicate:predicate]];
    
    
    return tmpstafflistarray;
}


