+(NSString *) returnproductnamewithproductcode:(NSString *)productcode centerkey:(NSString *)centerkey
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    if ([productcode isEqualToString:@"FPAY"]) {
        if ([globalvariables.language isEqualToString:@"English"]) {
            return [MyClass returntitlewithtitle:@"Forfeited Payment" language:@"English"];
        }else{
            return [MyClass returntitlewithtitle:@"Forfeited Payment" language:@"Chinese"];
        }
    }else{
        ProductRecord *productobject=[self returnProductInformationWithCode:productcode centerkey:centerkey];
        if (productobject) {
            if ([globalvariables.language isEqualToString:@"English"]) {
                return productobject.englishname;
            }else{
                return productobject.chinesename;
            }
        }
    }
    return productcode;
}



+(NSString *) returnschedulenamewithsubject_shortname:(NSString *)subject_shortname schedulekey:(NSString *)schedulekey centerkey:(NSString *)centerkey
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    if ([schedulekey isEqualToString:@"999999999"]) {
        return globalvariables.addhocschedulerecord.name;
    }else{
        SubjectRecord *subjectobject=[MyClass returnsubjectinformationwithsubject_shortname:subject_shortname centerkey:centerkey];
        for (int i=0; i<subjectobject.scheduleArray.count; i++) {
            if ([((ScheduleRecord *)[subjectobject.scheduleArray objectAtIndex:i]).schedulekey isEqualToString:schedulekey]) {
                if ([schedulekey intValue]<0) {
                    return [MyClass returntitlewithtitle:((ScheduleRecord *)[subjectobject.scheduleArray objectAtIndex:i]).name];
                }else{
                    return ((ScheduleRecord *)[subjectobject.scheduleArray objectAtIndex:i]).name;
                }
            }
        }
        return [MyClass returntitlewithtitle:@"Unknown"];
    }
}

