        SubjectRecord *subjectobject=[MyClass returnsubjectinformationwithsubject_shortname:subject_shortname centerkey:centerkey];
        
        for (int i=0; i<subjectobject.scheduleArray.count; i++) {
            schedulerecord=[subjectobject.scheduleArray objectAtIndex:i];
            if ([schedulerecord.schedulekey isEqualToString:schedulekey]) {
                return schedulerecord;
            }
        }
        return nil;
    }
}

