+(int) returnInstructorIndexWithInstructorArray:(NSMutableArray *)instructorarray username:(NSString *)username activeinstructor:(BOOL)activeinstructor defaultzeroifnotfound:(BOOL)defaultzero
{
    Instructor *instructorobject=[[Instructor alloc]init];
    
    for (int i=0; i<instructorarray.count; i++) {
        instructorobject=[instructorarray objectAtIndex:i];
        if (activeinstructor) {
            if ([instructorobject.username isEqualToString:username] && [instructorobject.valid isEqualToString:@"Yes"]) {
                return i;
            }
        }else{
            if ([instructorobject.username isEqualToString:username]) {
                return i;
            }
        }
        

    }
    if (defaultzero) {
        return 0;
    }else{
        return -1;
    }
}

