{
    NSMutableArray *resultarray=[[NSMutableArray alloc]init];
    
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    TuitionRecord *tuitionobject=[[TuitionRecord alloc]init];
    
    if (tuitionarray.count==0) {
        return tuitionarray;
    }else{
        if([((TuitionRecord *)[tuitionarray objectAtIndex:0]).method isEqualToString:@"Level"]){
            return tuitionarray;
        }else{
            NSArray *gradearray=[[NSArray alloc]initWithArray:[((CenterSettings *)[MyClass returnCenterSettingswithCenterkey:globalvariables.centerrecord.centerkey]).grade componentsSeparatedByString:@","]];
            for (int i=0; i<gradearray.count; i++) {
                
                for (int j=0; j<tuitionarray.count; j++) {
                    tuitionobject=[tuitionarray objectAtIndex:j];
                    if ([tuitionobject.scale isEqualToString:[gradearray objectAtIndex:i]]) {
                        [resultarray addObject:tuitionobject];
                        break;
                    }
                }
            }
            return resultarray;
        }
    }
}

