+(NSString *)enurlstring:(NSString *)string
{
    NSString *result;
    result = [string stringByReplacingOccurrencesOfString:@"&" withString:@"specialampersand"];
    result = [result stringByReplacingOccurrencesOfString:@" " withString:@"specialspace"];
    result = [result stringByReplacingOccurrencesOfString:@"'" withString:@"specialapostrophe"];
    return [result stringByReplacingOccurrencesOfString:@"+" withString:@"specialplus"];
}

+(NSString *) dcurlstring:(NSString *)string
{
    NSString *result;
    result = [string stringByReplacingOccurrencesOfString:@"specialampersand" withString:@"%26"];
    result = [result stringByReplacingOccurrencesOfString:@"specialspace" withString:@"%20"];
    result = [result stringByReplacingOccurrencesOfString:@"specialapostrophe" withString:@"%27"];
    return [result stringByReplacingOccurrencesOfString:@"specialplus" withString:@"%2B"];
}

+(NSString *) removeDevFromUsername:(NSString *)username
{
    NSRange range=[username rangeOfString:@":"];
    return range.location==NSNotFound ? username: [username substringToIndex:range.location];
}

+(BOOL) stringcontainscharacterwithstring:(NSString *)string character:(NSString *)character
{
    BOOL found;
    NSRange range=[string rangeOfString:character];
    found= range.location!=NSNotFound;
    return found;
}

+(NSString *) findweekfirstday:(NSString *)ddMMMYYYYdate
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    
    NSDateFormatter *df=[[NSDateFormatter alloc]init]; df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    NSDate *now;
    if ([ddMMMYYYYdate isEqualToString:@""]) {
        //find past monday
        now = [NSDate date];
    }else{
        [df setDateFormat:@"dd-MMM-yyyy"];
        now = [df dateFromString:ddMMMYYYYdate];
    }
    
    NSCalendar *calendar = [[NSCalendar alloc] initWithCalendarIdentifier:NSCalendarIdentifierGregorian];
    NSDateComponents *components = [calendar components:NSCalendarUnitYear | NSCalendarUnitMonth | NSCalendarUnitWeekday | NSCalendarUnitDay fromDate:now];
    
    NSUInteger weekdayToday = [components weekday];
    NSInteger daysToMonday=weekdayToday-[MyClass returndayofweeknumber:[globalvariables.centerdayofweekarray objectAtIndex:0]];
    NSDate *pastMon = [now dateByAddingTimeInterval:60*60*24*(-daysToMonday)];
    
    [df setDateFormat:@"dd-MMM-YYYY"];
    return [df stringFromDate:pastMon];
}

+(int) returndayofweeknumber:(NSString *)dayofweek
{
    if ([dayofweek isEqualToString:@"Sun"]) {
        return 1;
    }else if ([dayofweek isEqualToString:@"Mon"]) {
        return 2;
    }else if ([dayofweek isEqualToString:@"Tue"]) {
        return 3;
    }else if ([dayofweek isEqualToString:@"Wed"]) {
        return 4;
    }else if ([dayofweek isEqualToString:@"Thu"]) {
        return 5;
    }else if ([dayofweek isEqualToString:@"Fri"]) {
        return 6;
    }else{
        return 7;
    }
    
}

+(NSString *) returndayofweekname:(long)dayofweeknumber
{
    switch (dayofweeknumber) {
        case 1:
            return @"Sun";
            break;
        case 2:
            return @"Mon";
            break;
        case 3:
            return @"Tue";
            break;
        case 4:
            return @"Wed";
            break;
        case 5:
            return @"Thu";
            break;
        case 6:
            return @"Fri";
            break;
        case 7:
            return @"Sat";
            break;
        default:
            return @"";
            break;
    }
}

