+(NSMutableArray *) sortCouponRecords:(NSMutableArray *)couponrecords
{
    NSSortDescriptor *sortbypromotionkey = [NSSortDescriptor sortDescriptorWithKey:@"self.usedsequence" ascending:YES selector:@selector(localizedStandardCompare:)];
    NSArray *sortDescriptors = @[sortbypromotionkey];
    return [NSMutableArray arrayWithArray:[couponrecords sortedArrayUsingDescriptors:sortDescriptors]];
}

+(NSMutableArray *) sortDocumentPaymentRecords:(NSMutableArray *)paymentrecords
{
    NSSortDescriptor *sortbypaiddate = [NSSortDescriptor sortDescriptorWithKey:@"self.paiddate" ascending:NO selector:@selector(localizedStandardCompare:)];
    NSSortDescriptor *sortbypaymentkey = [NSSortDescriptor sortDescriptorWithKey:@"self.paymentkey" ascending:NO selector:@selector(localizedStandardCompare:)];
    NSArray *sortDescriptors = @[sortbypaiddate,sortbypaymentkey];
    NSMutableArray *result = [NSMutableArray arrayWithArray:[paymentrecords sortedArrayUsingDescriptors:sortDescriptors]];
    
    for (int i=0; i<result.count; i++) {
        PaymentRecord *obj=[result objectAtIndex:i];
        obj.paiddate=[self convertDateFormatWithDate:obj.paiddate FromDateFormat:@"yyyy-MM-dd" ToDateFormat:@"dd-MMM-yyyy" Translate:NO];
    }
    return result;
}

+(void) sortDocumentPromotionDiscountRecords:(NSMutableArray *)cpromotiondiscountrecords
{
    NSSortDescriptor *sortbypromotionkey = [NSSortDescriptor sortDescriptorWithKey:@"self.promotionkey" ascending:YES selector:@selector(localizedStandardCompare:)];
    NSArray *sortDescriptors = @[sortbypromotionkey];
    cpromotiondiscountrecords = [NSMutableArray arrayWithArray:[cpromotiondiscountrecords sortedArrayUsingDescriptors:sortDescriptors]];
}


+(BOOL) hasExtendedClassWithDictionary:(NSDictionary *)dictionary Classkey:(NSString *)classkey ExtendedType:(NSString *)extendedtype
{
    if ([classkey isEqualToString:@"Any"]) {
        return ((NSArray *)[dictionary objectForKey:extendedtype]).count>0?YES:NO;
    }else{
        NSArray *classarray=[dictionary objectForKey:extendedtype];
        for (int i=0; i<classarray.count; i++) {
            if ([((ClassExtendRecord *)[classarray objectAtIndex:i]).classkey isEqualToString:classkey]) {
                return YES;
            }
        }
        return NO;
    }
}

+(BOOL) classhasextendedclasswithclasskey:(NSString *)classkey
{
    NSDictionary *ExtendedClasskeyDictionary=[MyClass getextendedclasskeyswithenrollmentkey:nil classkey:classkey];
    return [MyClass hasExtendedClassWithDictionary:ExtendedClasskeyDictionary Classkey:classkey ExtendedType:@"fromclasskey"];
    
}


