        /*if (A5print) {
            UIGraphicsBeginPDFContextToData(pdfData, CGRectMake(0, 0, 612, 792),nil);
        }else{
            UIGraphicsBeginPDFContextToData(pdfData, CGRectZero,nil);
        }
        
        CGContextRef pdfContext=UIGraphicsGetCurrentContext();*/
        
        float maxcontentviewheight=contentview.frame.size.height;
        float begin=0;
        float cutoff=maxcontentviewheight;
        NSMutableArray *cutoffarray=[[NSMutableArray alloc]init];
        BOOL tncadded=FALSE;
        
        //determine number of pages
        for (int k=0;!tncadded;k++){
            for (UILabel *label in printView.subviews) {
                if (label.frame.origin.y+label.frame.size.height > cutoff) {
                    if (label.frame.origin.y<cutoff) {
                        cutoff=label.frame.origin.y;
                    }
                }
            }
            [cutoffarray addObject:[NSString stringWithFormat:@"%f",cutoff]];
            
            //end content and print tnc
            if (cutoff>=printView.frame.size.height) {
                if (printView.frame.size.height-begin+tncview.frame.size.height<maxcontentviewheight) {
                    tncadded=TRUE;
                }
            }
            
            begin=cutoff;
            cutoff=cutoff+maxcontentviewheight;
        }
        
        for (int k=0;k<cutoffarray.count;k++){
            // repeat the code between the lines for each pdf page you want to output
            // ======================================================================
            
            contentview.frame=CGRectMake(15, contentview.frame.origin.y, contentview.frame.size.width, [[cutoffarray objectAtIndex:k] floatValue]-(k==0?0:[[cutoffarray objectAtIndex:k-1] floatValue]));
            printView.frame=CGRectMake(0, -1*(k==0?0:[[cutoffarray objectAtIndex:k-1] floatValue]), contentview.frame.size.width, printView.frame.size.height);
            
            //end content and print tnc
            if (k==cutoffarray.count-1) {
                tncview.hidden=NO;
            }else{
                tncview.hidden=YES;
            }
            
            //add page number
            pagenumberlabel.text=[NSString stringWithFormat:@"%@ %@ %d/%lu",[MyClass returntitlewithtitle:@"invoice_Page" language:@"Chinese"],[MyClass returntitlewithtitle:@"invoice_Page" language:@"English"],k+1,(unsigned long)cutoffarray.count];
            
            UIGraphicsBeginPDFPage();
            CGContextSaveGState(pdfContext);
            
            if (A5print) {
                if (duplicatedcopyforA5printing) {
                    //upper copy
                    float margin=15;
                    
                    UIView *duplicatedview=[[UIView alloc]initWithFrame:CGRectMake(0, 0, printmasterview.frame.size.width*2+margin, printmasterview.frame.size.height)];
                    UIView *upperview=[[UIView alloc]initWithFrame:CGRectMake(0, 0, printmasterview.frame.size.width, printmasterview.frame.size.height)];
                    UIView *lowerview=[[UIView alloc]initWithFrame:CGRectMake(printmasterview.frame.size.width+margin, 0, printmasterview.frame.size.width, printmasterview.frame.size.height)];
                    [duplicatedview addSubview:upperview];
                    [duplicatedview addSubview:lowerview];
                    
                    [upperview addSubview:printmasterview];
                    NSData *archivedData = [NSKeyedArchiver archivedDataWithRootObject: printmasterview];
                    UIView * newView = [NSKeyedUnarchiver unarchiveObjectWithData: archivedData];
                    [lowerview addSubview:newView];
                    
                    duplicatedview.transform=CGAffineTransformMakeScale(.55/sqrt(2)*1.06, .55/sqrt(2)*1.06);
                    duplicatedview.transform=CGAffineTransformRotate(duplicatedview.transform, -90* M_PI/180);
                    duplicatedview.transform=CGAffineTransformTranslate(duplicatedview.transform, -duplicatedview.frame.size.height/(.55/sqrt(2))+15, 0);
                    CGContextConcatCTM(pdfContext, [[duplicatedview layer] affineTransform]);
                    CGContextTranslateCTM(pdfContext, 70, 10);
                    [duplicatedview.layer renderInContext:pdfContext];
                    
                    
                }else{
                    printmasterview.transform=CGAffineTransformMakeScale(.55/sqrt(2)*1.06, .55/sqrt(2)*1.06);
                    printmasterview.transform=CGAffineTransformRotate(printmasterview.transform, -90* M_PI/180);
                    printmasterview.transform=CGAffineTransformTranslate(printmasterview.transform, -printmasterview.frame.size.height/(.55/sqrt(2))+15, 0);
                    CGContextConcatCTM(pdfContext, [[printmasterview layer] affineTransform]);
                    CGContextTranslateCTM(pdfContext, -10, 10);
                    [printmasterview.layer renderInContext:pdfContext];
                }
            }else{
                CGContextConcatCTM(pdfContext,CGAffineTransformMakeScale(.60, .60));
                CGContextTranslateCTM(pdfContext, -18, 30);
                [printmasterview.layer renderInContext:pdfContext];
            }
            

            
            // end repeat code
            // ======================================================================
        }

        
    }
    
    
    
    
    // finally end the PDF context.
    UIGraphicsEndPDFContext();
    
    // and return the PDF data.
    return pdfData;
}

+ (UIImage *) convertToGreyscale:(UIImage *)i {
    
    int kRed = 1;
    int kGreen = 2;
    int kBlue = 4;
    
    int colors = kGreen | kBlue | kRed;
    int m_width = i.size.width;
    int m_height = i.size.height;
    
    uint32_t *rgbImage = (uint32_t *) malloc(m_width * m_height * sizeof(uint32_t));
    CGColorSpaceRef colorSpace = CGColorSpaceCreateDeviceRGB();
    CGContextRef context = CGBitmapContextCreate(rgbImage, m_width, m_height, 8, m_width * 4, colorSpace, kCGBitmapByteOrder32Little | kCGImageAlphaNoneSkipLast);
    CGContextSetInterpolationQuality(context, kCGInterpolationHigh);
    CGContextSetShouldAntialias(context, NO);
    CGContextDrawImage(context, CGRectMake(0, 0, m_width, m_height), [i CGImage]);
    CGContextRelease(context);
    CGColorSpaceRelease(colorSpace);
    
    // now convert to grayscale
    uint8_t *m_imageData = (uint8_t *) malloc(m_width * m_height);
    for(int y = 0; y < m_height; y++) {
        for(int x = 0; x < m_width; x++) {
            uint32_t rgbPixel=rgbImage[y*m_width+x];
            uint32_t sum=0,count=0;
            if (colors & kRed) {sum += (rgbPixel>>24)&255; count++;}
            if (colors & kGreen) {sum += (rgbPixel>>16)&255; count++;}
            if (colors & kBlue) {sum += (rgbPixel>>8)&255; count++;}
            m_imageData[y*m_width+x]=sum/count;
        }
    }
    free(rgbImage);
    
    // convert from a gray scale image back into a UIImage
    uint8_t *result = (uint8_t *) calloc(m_width * m_height *sizeof(uint32_t), 1);
    
    // process the image back to rgb
    for(int i = 0; i < m_height * m_width; i++) {
        result[i*4]=0;
        int val=m_imageData[i];
        result[i*4+1]=val;
        result[i*4+2]=val;
        result[i*4+3]=val;
    }
    
    // create a UIImage
    colorSpace = CGColorSpaceCreateDeviceRGB();
    context = CGBitmapContextCreate(result, m_width, m_height, 8, m_width * sizeof(uint32_t), colorSpace, kCGBitmapByteOrder32Little | kCGImageAlphaNoneSkipLast);
    CGImageRef image = CGBitmapContextCreateImage(context);
    CGContextRelease(context);
    CGColorSpaceRelease(colorSpace);
    UIImage *resultUIImage = [UIImage imageWithCGImage:image];
    CGImageRelease(image);
    
    free(m_imageData);
    
    // make sure the data will be released by giving it to an autoreleased NSData
    [NSData dataWithBytesNoCopy:result length:m_width * m_height];
    
    return resultUIImage;
}

+ (NSData *) generateAssessmentReportWithAssessmentReportDict:(NSMutableDictionary *)assessmentreportdict sendAssessmentReport:(BOOL)sendassessmentreport
{
    
    AssessmentReportView *printView=[[AssessmentReportView alloc]initWithFrame:CGRectZero assessmentReportDict:assessmentreportdict sendAssessmentReport:sendassessmentreport];
    
    
//    NSInteger pageHeight = 792; // Standard page height - adjust as needed
//    NSInteger pageWidth = 612;  // Standard page width - adjust as needed
    
    NSInteger pageHeight = 842; // Standard page height - adjust as needed
    NSInteger pageWidth = 595;  // Standard page width - adjust as needed
    
    NSMutableData *pdfData = [NSMutableData data];
    UIGraphicsBeginPDFContextToData(pdfData, CGRectMake(0,0,pageWidth,pageHeight), nil);
    CGContextRef pdfContext = UIGraphicsGetCurrentContext();
    for (int page=0; printView.frame.size.width*pageHeight/pageWidth * page < printView.frame.size.height; page++)
    {
        UIGraphicsBeginPDFPage();
        CGContextTranslateCTM(pdfContext, 14, 20);
        CGContextConcatCTM(pdfContext,CGAffineTransformMakeScale(.69, .69));
        UIView *printview2=[[UIView alloc]initWithFrame:CGRectMake(0, 0, printView.frame.size.width, printView.frame.size.width*pageHeight/pageWidth)];
        printview2.layer.masksToBounds=TRUE;
        printView.frame=CGRectMake(0, -(printView.frame.size.width*pageHeight/pageWidth-10) * page, printView.frame.size.width, printView.frame.size.height);
        [printview2 addSubview:printView];
        [printview2.layer renderInContext:pdfContext];
    }

    UIGraphicsEndPDFContext();
    
    return pdfData;
}

+ (NSData *) generateReceiptWithClassReceiptArray:(NSMutableArray *)origclassreceiptarray SalesReceiptArray:(NSMutableArray *)origsalesreceiptarray papersizeoverride:(BOOL)papersizeoverride combinedocument:(BOOL)combinedocument centerkey:(NSString *)centerkey
{
    
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    CenterRecord *printcenterrecord;
    if (globalvariables.documentfolderdict&& [MyClass isApplicationNotActive]) {
        printcenterrecord=globalvariables.documentfolderdict[@"documentcenterrecord"];
    }else{
        globalvariables.documentfolderdict=nil;
        printcenterrecord=[MyClass returncenterrecordwithcenterkey:centerkey];
    }
    
    
    BOOL A5print=NO;
    BOOL duplicatedcopyforA5printing=NO;
    
    NSString *a5printing=[@(((Staff *)[MyClass returnstaffrecordwithusername:globalvariables.username]).a4trayfora5printing_receipt) stringValue];
    BOOL showlevel=printcenterrecord.showlevelinreceipt;
    BOOL showstaff=printcenterrecord.showstaffnameinreceipt;
    BOOL showclassdates=printcenterrecord.showclassdatesinreceipt>0;
    
    if (papersizeoverride) {
        A5print=NO;
        duplicatedcopyforA5printing=NO;
    }else{
        if ([a5printing isEqualToString:@"0"]) {
            A5print=NO;
            duplicatedcopyforA5printing=NO;
        }else if ([a5printing isEqualToString:@"1"]) {
            A5print=YES;
            duplicatedcopyforA5printing=NO;
        }else if ([a5printing isEqualToString:@"2"]) {
            A5print=YES;
            duplicatedcopyforA5printing=YES;
        }
    }
    
    float tncfontsize=printcenterrecord.tncfontsize_receipt;//[[MyClass getlocaldbwithparameter:@"tncfontsize"] floatValue];
    float receiptinvoicefontsize=printcenterrecord.receiptfontsize*2+16;
    
