                [classenrollmentarray addObject:obj.enrollmentkey];
                
                totalprice+=[obj.tuitionfee floatValue];
                totalenrollmentfee+=[obj.enrollmentfee floatValue];
                totaldiscount+=[obj.discount floatValue];
                totallatefee+=[obj.latefee floatValue];
                totalfee+=[obj.totalfee floatValue];
                totalpaid+=[obj.paid floatValue];
                
                if (!lastpaymentdate || [[MyClass convertToNSDateWithDate:obj.paiddate DateFormat:@"dd-MMM-yyyy"] compare:lastpaymentdate]==NSOrderedDescending){
                    lastpaymentdate=[MyClass convertToNSDateWithDate:obj.paiddate DateFormat:@"dd-MMM-yyyy"];
                }
            }

            for (long y=0; y<(printcenterrecord.showlastpaymentonlyinreceipt?[MyClass returnMinimumValueWithAValue:1 BValue:obj.enrollmentrecord.paymentrecords.count]:obj.enrollmentrecord.paymentrecords.count); y++) {
                PaymentRecord *payobj=[obj.enrollmentrecord.paymentrecords objectAtIndex:y];
                paidamount+=[payobj.paidamount floatValue];
                
                if (!lastpaymentdate || [[MyClass convertToNSDateWithDate:payobj.paiddate DateFormat:@"dd-MMM-yyyy"] compare:lastpaymentdate]==NSOrderedDescending){
                    lastpaymentdate=[MyClass convertToNSDateWithDate:payobj.paiddate DateFormat:@"dd-MMM-yyyy"];
                }
                
                
            }
        }
        
