                totalprice+=[obj.price floatValue]*[obj.quantity intValue];
                totaldiscount+=[obj.discount floatValue];
                totalfee+=[obj.totalfee floatValue];
                totalpaid+=[obj.paid floatValue];
                
                
            }

            for (long y=0; y<(printcenterrecord.showlastpaymentonlyinreceipt?[MyClass returnMinimumValueWithAValue:1 BValue:obj.salesrecord.paymentrecords.count]:obj.salesrecord.paymentrecords.count); y++) {
