+(BOOL) isIntegerNumber:(NSString *)input
{
    if (input) {
        NSCharacterSet *_NumericOnly = [NSCharacterSet decimalDigitCharacterSet];
        NSCharacterSet *myStringSet = [NSCharacterSet characterSetWithCharactersInString:input];
        
        if ([_NumericOnly isSupersetOfSet: myStringSet] || [input isEqualToString:@""])
        {
            //Matches
            return TRUE;
        }else{
            return FALSE;
        }
    }else{
        return TRUE;
    }
}

+(BOOL) checkvalidfeeinput:(NSString *)input
{
    NSString *decimalRegex = @"^(?:|-)(?:|0|[1-9]\\d*)(?:\\.\\d*)?$";
    NSPredicate *regexPredicate = [NSPredicate predicateWithFormat:@"SELF MATCHES %@", decimalRegex];
    
    if ([regexPredicate evaluateWithObject: input]){
        //Matches
        return TRUE;
    }else{
        return FALSE;
    }
}

+(BOOL) checkValidInput:(NSString *)input Type:(NSString *)type
{
    if (input) {
        if ([type isEqualToString:@"Integer"]) {
            NSCharacterSet *_NumericOnly = [NSCharacterSet decimalDigitCharacterSet];
            NSCharacterSet *myStringSet = [NSCharacterSet characterSetWithCharactersInString:input];
            
            if (([_NumericOnly isSupersetOfSet: myStringSet] && [input intValue]>0))
            {
                return TRUE;
            }
        }else if ([type isEqualToString:@"Float"]){
            NSString *decimalRegex = @"^(?:|-)(?:|0|[1-9]\\d*)(?:\\.\\d*)?$";
            NSPredicate *regexPredicate = [NSPredicate predicateWithFormat:@"SELF MATCHES %@", decimalRegex];
            
            if ([regexPredicate evaluateWithObject: input]){
                //Matches
                return TRUE;
            }
        }else if ([type isEqualToString:@"EmptyInteger"]) {
            NSCharacterSet *_NumericOnly = [NSCharacterSet decimalDigitCharacterSet];
            NSCharacterSet *myStringSet = [NSCharacterSet characterSetWithCharactersInString:input];
            
            if (([_NumericOnly isSupersetOfSet: myStringSet] || [input isEqualToString:@""]))
            {
                return TRUE;
            }
        }else if ([type isEqualToString:@"Integers"]){
            NSString *decimalRegex = @"^([+-]?)(?:|0|[1-9]\\d*)?$";
            NSPredicate *regexPredicate = [NSPredicate predicateWithFormat:@"SELF MATCHES %@", decimalRegex];
            
            if ([regexPredicate evaluateWithObject: input]){
                //Matches
                return TRUE;
            }
        }else if ([type isEqualToString:@"ZeroInteger"]) {
            NSCharacterSet *_NumericOnly = [NSCharacterSet decimalDigitCharacterSet];
            NSCharacterSet *myStringSet = [NSCharacterSet characterSetWithCharactersInString:input];
            
            if (([_NumericOnly isSupersetOfSet: myStringSet] && [input intValue]>=0))
            {
                return TRUE;
            }
        }
        return FALSE;
    }else{
        return TRUE;
    }
}

+(NSMutableArray *) returnEarlyBirdPromotionWithEnrollmentDate:(NSString *)enrollmentdate Subject:(NSString *)subject
{
    NSMutableArray *earlyBirdPromotions=[[NSMutableArray alloc]init];
    NSMutableArray *availablepromotionarray=[[MyClass retrieveMarketingRecordWithStatus:@"Valid" enrollmentdate:enrollmentdate flushcachedata:NO subjectkey:[MyClass returnsubjectkeywithsubject_shortname:subject] productkey:nil] objectAtIndex:2];
    
    NSDate *earliestpromotiondate;
    MarketingRecord *obj;
    for (int i=0; i<availablepromotionarray.count; i++) {
        obj=[availablepromotionarray objectAtIndex:i];
        if (![obj.earlybirdlastdate isEqualToString:@""]) {
            if ([[MyClass convertToNSDateWithDate:[NSString stringWithFormat:@"%@ 23:59:59",obj.earlybirdlastdate] DateFormat:@"yyyy-MM-dd HH:mm:ss"] compare:[NSDate date]]!=NSOrderedAscending  ) {
                if (!earliestpromotiondate){
                    earliestpromotiondate=[MyClass convertToNSDateWithDate:[NSString stringWithFormat:@"%@ 23:59:59",obj.earlybirdlastdate] DateFormat:@"yyyy-MM-dd HH:mm:ss"];
                    [earlyBirdPromotions addObject:obj];
                }else if ([earliestpromotiondate compare:[MyClass convertToNSDateWithDate:[NSString stringWithFormat:@"%@ 23:59:59",obj.earlybirdlastdate] DateFormat:@"yyyy-MM-dd HH:mm:ss"]]==NSOrderedSame){
                    [earlyBirdPromotions addObject:obj];
                }else if ([earliestpromotiondate compare:[MyClass convertToNSDateWithDate:[NSString stringWithFormat:@"%@ 23:59:59",obj.earlybirdlastdate] DateFormat:@"yyyy-MM-dd HH:mm:ss"]]==NSOrderedDescending){
                    earliestpromotiondate=[MyClass convertToNSDateWithDate:[NSString stringWithFormat:@"%@ 23:59:59",obj.earlybirdlastdate] DateFormat:@"yyyy-MM-dd HH:mm:ss"];
                    [earlyBirdPromotions removeAllObjects];
                    [earlyBirdPromotions addObject:obj];
                }
            }
        }
    }
    return earlyBirdPromotions;
}

