+(NSMutableArray *) retrieveMarketingRecordWithStatus:(NSString *)status enrollmentdate:(NSString *)enrollmentdate flushcachedata:(BOOL)flushcachedata subjectkey:(NSString *)subjectkey productkey:(NSString *)productkey
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    NSDateFormatter *df=[[NSDateFormatter alloc]init]; df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    [df setDateFormat:@"dd-MMM-yyyy HH:mm:ss"];
    
    if (flushcachedata) {
        [MyClass getLatestDataSetv2withParameters:@"marketing" Centerkeys:globalvariables.centerrecord.centerkey completionBlock:nil];
    }
    
    NSMutableArray *resultmediaarray=[[NSMutableArray alloc]init];
    NSMutableArray *resultsourcearray=[[NSMutableArray alloc]init];
    NSMutableArray *resultpromotionarray=[[NSMutableArray alloc]init];
    NSMutableArray *resultcouponarray=[[NSMutableArray alloc]init];
    
    NSPredicate *predicate;
    NSMutableArray *nsPredicatearray=[[NSMutableArray alloc]init];
    
    //media
    NSMutableArray *allmarketingarray=[[NSMutableArray alloc]initWithArray:[globalvariables.marketinglistarray allValues]];
    predicate = [NSPredicate predicateWithFormat:@"SELF.centerkey = %@ and self.category =%@",globalvariables.centerrecord.centerkey,@"media"];
    NSMutableArray *tmpMarketingMediaArray=[[NSMutableArray alloc]initWithArray:[allmarketingarray filteredArrayUsingPredicate:predicate]];
    
    //source
    predicate = [NSPredicate predicateWithFormat:@"SELF.centerkey = %@ and self.category =%@",globalvariables.centerrecord.centerkey,@"source"];
    NSMutableArray *tmpMarketingSourceArray=[[NSMutableArray alloc]initWithArray:[allmarketingarray filteredArrayUsingPredicate:predicate]];
    
    //promotion
    predicate = [NSPredicate predicateWithFormat:@"SELF.centerkey = %@ and self.category =%@",globalvariables.centerrecord.centerkey,@"promotion"];
    [nsPredicatearray addObject:predicate];
    if([subjectkey isEqualToString:@"allonly"]){
        predicate = [NSPredicate predicateWithFormat:@"self.subjectarray.@count=0 and self.productarray.@count=0"];
        [nsPredicatearray addObject:predicate];
    }else if(subjectkey){
        predicate = [NSPredicate predicateWithFormat:@"any subjectarray contains[c] %@ or self.subjectarray.@count=0", subjectkey];
        [nsPredicatearray addObject:predicate];
    }else if(productkey){
        predicate = [NSPredicate predicateWithFormat:@"any productarray contains[c] %@ or self.productarray.@count=0", productkey];
        [nsPredicatearray addObject:predicate];
    }
    predicate = [NSCompoundPredicate andPredicateWithSubpredicates:[NSArray arrayWithArray:nsPredicatearray]];
    NSMutableArray *tmpMarketingPromotionArray=[[NSMutableArray alloc]initWithArray:[allmarketingarray filteredArrayUsingPredicate:predicate]];
    
    //coupon
    [nsPredicatearray removeAllObjects];
    predicate = [NSPredicate predicateWithFormat:@"SELF.centerkey = %@ and self.category =%@",globalvariables.centerrecord.centerkey,@"coupon"];
    [nsPredicatearray addObject:predicate];
    if(subjectkey){
        predicate = [NSPredicate predicateWithFormat:@"any subjectarray contains[c] %@ or self.subjectarray.@count=0", subjectkey];
        [nsPredicatearray addObject:predicate];
    }else if(productkey){
        predicate = [NSPredicate predicateWithFormat:@"any productarray contains[c] %@ or self.productarray.@count=0", productkey];
        [nsPredicatearray addObject:predicate];
    }
    predicate = [NSCompoundPredicate andPredicateWithSubpredicates:[NSArray arrayWithArray:nsPredicatearray]];
    NSMutableArray *tmpMarketingCouponArray=[[NSMutableArray alloc]initWithArray:[allmarketingarray filteredArrayUsingPredicate:predicate]];
    
    
    
    MarketingRecord *marketingobject=[[MarketingRecord alloc]init];
    
    for (int i=0; i<tmpMarketingMediaArray.count; i++) {
        marketingobject=[tmpMarketingMediaArray objectAtIndex:i];
        if ([[globalvariables.centerrecord.centerkey componentsSeparatedByString:@","] containsObject:marketingobject.centerkey]) {
            if ([status isEqualToString:@"All"]){
                [resultmediaarray addObject:marketingobject];
            }else if ([status isEqualToString:@"Valid"]){
                if ([[MyClass convertToNSDateWithDate:enrollmentdate DateFormat:@"dd-MMM-yyyy"] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 23:59:59",marketingobject.enddate]]] !=NSOrderedDescending && [[NSDate date] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 00:00:00",marketingobject.startdate]]] !=NSOrderedAscending) {
                    [resultmediaarray addObject:marketingobject];
                }
            }else{
                if ([[MyClass convertToNSDateWithDate:enrollmentdate DateFormat:@"dd-MMM-yyyy"] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 23:59:59",marketingobject.enddate]]] ==NSOrderedDescending) {
                    [resultmediaarray addObject:marketingobject];
                }
            }
        }
    }
    
    for (int i=0; i<tmpMarketingSourceArray.count; i++) {
        marketingobject=[tmpMarketingSourceArray objectAtIndex:i];
        if ([[globalvariables.centerrecord.centerkey componentsSeparatedByString:@","] containsObject:marketingobject.centerkey]) {
            
            if ([status isEqualToString:@"All"]){
                [resultsourcearray addObject:marketingobject];
            }else if ([status isEqualToString:@"Valid"]){
                if ([[MyClass convertToNSDateWithDate:enrollmentdate DateFormat:@"dd-MMM-yyyy"] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 23:59:59",marketingobject.enddate]]] !=NSOrderedDescending && [[NSDate date] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 00:00:00",marketingobject.startdate]]] !=NSOrderedAscending) {
                    [resultsourcearray addObject:marketingobject];
                }
            }else{
                if ([[MyClass convertToNSDateWithDate:enrollmentdate DateFormat:@"dd-MMM-yyyy"] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 23:59:59",marketingobject.enddate]]] ==NSOrderedDescending) {
                    [resultsourcearray addObject:marketingobject];
                }
            }
        }
        
    }
    
    for (int i=0; i<tmpMarketingPromotionArray.count; i++) {
        marketingobject=[tmpMarketingPromotionArray objectAtIndex:i];
        if ([[globalvariables.centerrecord.centerkey componentsSeparatedByString:@","] containsObject:marketingobject.centerkey]) {
            if ([status isEqualToString:@"All"]){
                [resultpromotionarray addObject:marketingobject];
            }else if ([status isEqualToString:@"Valid"]){
                if ([[MyClass convertToNSDateWithDate:enrollmentdate DateFormat:@"dd-MMM-yyyy"] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 23:59:59",marketingobject.enddate]]] !=NSOrderedDescending && [[NSDate date] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 23:59:59",marketingobject.enddate]]] !=NSOrderedDescending && [[NSDate date] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 00:00:00",marketingobject.startdate]]] !=NSOrderedAscending) {
                    if ([marketingobject.promotionquota isEqualToString:@""] || ([marketingobject.promotionquota intValue] > [marketingobject.usedcount intValue])) {
                        [resultpromotionarray addObject:marketingobject];
                    }
                }
            }else{
                if ([[MyClass convertToNSDateWithDate:enrollmentdate DateFormat:@"dd-MMM-yyyy"] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 23:59:59",marketingobject.enddate]]] ==NSOrderedDescending || (![marketingobject.promotionquota isEqualToString:@""] && ([marketingobject.promotionquota intValue] <= [marketingobject.usedcount intValue])) ) {
                    [resultpromotionarray addObject:marketingobject];
                }
            }
        }
        
    }
    
    for (int i=0; i<tmpMarketingCouponArray.count; i++) {
        marketingobject=[tmpMarketingCouponArray objectAtIndex:i];
        if ([[globalvariables.centerrecord.centerkey componentsSeparatedByString:@","] containsObject:marketingobject.centerkey]) {
            if ([status isEqualToString:@"All"]){
                [resultcouponarray addObject:marketingobject];
            }else if ([status isEqualToString:@"Valid"]){
                if ([[MyClass convertToNSDateWithDate:enrollmentdate DateFormat:@"dd-MMM-yyyy"] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 23:59:59",marketingobject.enddate]]] !=NSOrderedDescending && [[NSDate date] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 23:59:59",marketingobject.enddate]]] !=NSOrderedDescending && [[NSDate date] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 00:00:00",marketingobject.startdate]]] !=NSOrderedAscending) {
                    if ([marketingobject.promotionquota isEqualToString:@""] || ([marketingobject.promotionquota intValue] > [marketingobject.usedcount intValue])) {
                        [resultcouponarray addObject:marketingobject];
                    }
                }
            }else{
                if ([[MyClass convertToNSDateWithDate:enrollmentdate DateFormat:@"dd-MMM-yyyy"] compare:[df dateFromString:[NSString stringWithFormat:@"%@ 23:59:59",marketingobject.enddate]]] ==NSOrderedDescending || (![marketingobject.promotionquota isEqualToString:@""] && ([marketingobject.promotionquota intValue] <= [marketingobject.usedcount intValue])) ) {
                    [resultcouponarray addObject:marketingobject];
                }
            }
        }
        
    }
    
    return [[NSMutableArray alloc]initWithObjects:resultmediaarray,resultsourcearray,resultpromotionarray,resultcouponarray,nil];
}



