+(NSString *) returninvoicenumberwithclassinvoicearray:(NSMutableArray *)classinvoicearray salesinvoicearray:(NSMutableArray *)salesinvoicearray updateinvoicelog:(BOOL)updateinvoicelog
{
    NSInteger invoicenumber=0;
    NSInteger invoicenumberlength=0;
    NSMutableArray *prefixarray=[[NSMutableArray alloc]init];
    ClassInvoiceRecord *classinvoiceobj;
    SalesInvoiceRecord *salesinvoiceobj;
    
    for (int i=0; i<classinvoicearray.count; i++) {
        classinvoiceobj=[classinvoicearray objectAtIndex:i];
        if ([classinvoiceobj.enrollmentrecord.invoicenumber integerValue]>invoicenumber) {
            invoicenumber=[classinvoiceobj.enrollmentrecord.invoicenumber integerValue];
        }
//        invoicenumber+=[classinvoiceobj.enrollmentrecord.invoicenumber integerValue];
        [prefixarray addObject:classinvoiceobj.enrollmentrecord.invoiceprefix];
        invoicenumberlength=[classinvoiceobj.enrollmentrecord.invoicenumber length];
    }
    
    for (int i=0; i<salesinvoicearray.count; i++) {
        salesinvoiceobj=[salesinvoicearray objectAtIndex:i];
        if ([salesinvoiceobj.salesrecord.invoicenumber integerValue]>invoicenumber) {
            invoicenumber=[salesinvoiceobj.salesrecord.invoicenumber integerValue];
        }
//        invoicenumber+=[salesinvoiceobj.salesrecord.invoicenumber integerValue];
        [prefixarray addObject:salesinvoiceobj.salesrecord.invoiceprefix];
        invoicenumberlength=[salesinvoiceobj.salesrecord.invoicenumber length];
    }
    
//    NSString *invoicenumbertext=[NSString stringWithFormat:@"%0ld",(long)(invoicenumber/(classinvoicearray.count+salesinvoicearray.count))];
    NSString *invoicenumbertext=[NSString stringWithFormat:@"%0ld",(long)invoicenumber];
    while ([invoicenumbertext length]<invoicenumberlength) {
        invoicenumbertext=[NSString stringWithFormat:@"%@%@",@"0",invoicenumbertext];
    }
    invoicenumbertext=[NSString stringWithFormat:@"%@%@",[prefixarray firstObject],invoicenumbertext];
    
    if(updateinvoicelog){
        //write to invoice log
        [self updateInvoiceLogWithClassInvoiceArray:classinvoicearray SalesInvoiceArray:salesinvoicearray invoiceNumber:invoicenumbertext];
    }
    return invoicenumbertext;
}

+(NSString *) returnreceiptnumberwithclassreceiptarray:(NSMutableArray *)classreceiptarray salesreceiptarray:(NSMutableArray *)salesreceiptarray
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSInteger receiptnumber=0;
    NSInteger largestpaymentkey=0;
    NSInteger receiptnumberlength=0;
    NSMutableArray *prefixarray=[[NSMutableArray alloc]init];
    ClassInvoiceRecord *classreceiptobj;
    SalesInvoiceRecord *salesreceiptobj;
    int paymentcount=0;
    
    for (int i=0; i<classreceiptarray.count; i++) {
        classreceiptobj=[classreceiptarray objectAtIndex:i];
        for (long j=0; j<(globalvariables.centerrecord.showlastpaymentonlyinreceipt?[MyClass returnMinimumValueWithAValue:1 BValue:classreceiptobj.enrollmentrecord.paymentrecords.count]:classreceiptobj.enrollmentrecord.paymentrecords.count); j++) {
            PaymentRecord *paymentobj=[classreceiptobj.enrollmentrecord.paymentrecords objectAtIndex:j];
            if ([paymentobj.paymentkey integerValue]>largestpaymentkey) {
                largestpaymentkey=[paymentobj.paymentkey integerValue];
                receiptnumber=[paymentobj.receiptnumber integerValue];
            }
//            receiptnumber+=[paymentobj.receiptnumber integerValue];
            [prefixarray addObject:paymentobj.receiptprefix];
            receiptnumberlength=[paymentobj.receiptnumber length];
            paymentcount++;
        }
    }
    
    
    for (int i=0; i<salesreceiptarray.count; i++) {
        salesreceiptobj=[salesreceiptarray objectAtIndex:i];
        for (long j=0; j<(globalvariables.centerrecord.showlastpaymentonlyinreceipt?[MyClass returnMinimumValueWithAValue:1 BValue:salesreceiptobj.salesrecord.paymentrecords.count]:salesreceiptobj.salesrecord.paymentrecords.count); j++) {
            PaymentRecord *paymentobj=[salesreceiptobj.salesrecord.paymentrecords objectAtIndex:j];
            if ([paymentobj.paymentkey integerValue]>largestpaymentkey) {
                largestpaymentkey=[paymentobj.paymentkey integerValue];
                receiptnumber=[paymentobj.receiptnumber integerValue];
            }
//            receiptnumber+=[paymentobj.receiptnumber integerValue];
            [prefixarray addObject:paymentobj.receiptprefix];
            receiptnumberlength=[paymentobj.receiptnumber length];
            paymentcount++;
        }
    }
    
//    NSString *receiptnumbertext=[NSString stringWithFormat:@"%0ld",(long)(receiptnumber/paymentcount)];
    NSString *receiptnumbertext=[NSString stringWithFormat:@"%0ld",(long)receiptnumber];
    while ([receiptnumbertext length]<receiptnumberlength) {
        receiptnumbertext=[NSString stringWithFormat:@"%@%@",@"0",receiptnumbertext];
    }
    receiptnumbertext=[NSString stringWithFormat:@"%@%@",[prefixarray firstObject],receiptnumbertext];

    return receiptnumbertext;
}

