+(NSString *) returntitlewithtitle2:(NSString *)title
{
    
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    
    LanguageTitleRecord *result=[globalvariables.languagepackdictionary objectForKey:[NSString stringWithFormat:@"%@#%@",/*globalvariables.centerrecord.centerkey*/@"",title]];
    
    if (result) {
        return [result valueForKey:[globalvariables.language lowercaseString]];
    }else{
        LanguageTitleRecord *result=[globalvariables.languagepackdictionary objectForKey:[NSString stringWithFormat:@"%@#%@",@"",title]];
        if (result) {
            return [result valueForKey:[globalvariables.language lowercaseString]];
        }
        return title;
    }
}

+(NSString *) returntitlewithtitle:(NSString *)title
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    
    if (globalvariables.documentfolderdict&& [MyClass isApplicationNotActive]) {
        NSMutableDictionary *documentlanguagetitledict=globalvariables.documentfolderdict[@"documentlanguagetitledict"];
        LanguageTitleRecord *result=[documentlanguagetitledict objectForKey:[NSString stringWithFormat:@"%@",title]];
        
        if (result) {
            NSString *foundtitle=[result valueForKey:[globalvariables.documentfolderdict[@"documentlanguage"] lowercaseString]];
            if(foundtitle){
                return foundtitle;
            }else{
                return title;
            }
        }else{
            return title;
        }
    }else{
        globalvariables.documentfolderdict=nil;
        LanguageTitleRecord *result=[globalvariables.languagetitledictionary objectForKey:[NSString stringWithFormat:@"%@#%@",globalvariables.centerrecord.centerkey,title]];
        
        if (result) {
            return [result valueForKey:[globalvariables.language lowercaseString]];
        }else{
            return title;
        }
    }
}

+(NSString *) returntitlewithtitle:(NSString *)title language:(NSString *)language
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    if (globalvariables.documentfolderdict&& [MyClass isApplicationNotActive]) {
        
        NSMutableDictionary *documentlanguagetitledict=globalvariables.documentfolderdict[@"documentlanguagetitledict"];
        LanguageTitleRecord *result=[documentlanguagetitledict objectForKey:[NSString stringWithFormat:@"%@",title]];
        
        if (result) {
            if ([language isEqualToString:@"English"]) {
                return result.english;
            }else if ([language isEqualToString:@"Chinese"]){
                return result.chinese;
            }else{
                return result.schinese;
            }
        }else{
            return title;
        }
        
        
    }else{

        
        LanguageTitleRecord *result=[globalvariables.languagetitledictionary objectForKey:[NSString stringWithFormat:@"%@#%@",globalvariables.centerrecord.centerkey,title]];
        
        if (result) {
            if ([language isEqualToString:@"English"]) {
                return result.english;
            }else if ([language isEqualToString:@"Chinese"]){
                return result.chinese;
            }else{
                return result.schinese;
            }
        }else{
            return title;
        }
    }

}



+(NSString *) returndateformatwithdate:(NSString *)DDMMMYYYYdate
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    
    if ([globalvariables.language isEqualToString:@"English"]) {
        return DDMMMYYYYdate;
    }else{
        df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];[df setDateFormat:@"dd-MMM-yyyy"];
        NSDate *date=[df dateFromString:DDMMMYYYYdate];
        
        if (date) {
            df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];[df setDateFormat:@"yyyy年M月d日"];
            return [df stringFromDate:date];
        }else{
            return [MyClass returntitlewithtitle:DDMMMYYYYdate];
        }
    }
}

