+(NSString *) returndateformatDDMMMYYYYHHMMwithdate:(NSString *)DDMMMYYYYHHMMdate
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    
    if ([globalvariables.language isEqualToString:@"English"]) {
        return DDMMMYYYYHHMMdate;
    }else{
        if ([DDMMMYYYYHHMMdate length]>12){
            if ([[DDMMMYYYYHHMMdate substringFromIndex:12] isEqualToString:@"TBD"]) {
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];[df setDateFormat:@"dd-MMM-yyyy"];
                NSDate *date=[df dateFromString:[DDMMMYYYYHHMMdate substringToIndex:11]];
                
                if (date) {
                    df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];[df setDateFormat:@"yyyy年M月d日"];
                    return [NSString stringWithFormat:@"%@ %@",[df stringFromDate:date],[MyClass returntitlewithtitle:@"TBD"]];
                }else{
                    return [MyClass returntitlewithtitle:DDMMMYYYYHHMMdate];
                }
            }else{
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];[df setDateFormat:@"dd-MMM-yyyy HH:mm"];
                NSDate *date=[df dateFromString:DDMMMYYYYHHMMdate];
                
                if (date) {
                    df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];[df setDateFormat:@"yyyy年M月d日 HH:mm"];
                    return [df stringFromDate:date];
                }else{
                    return [MyClass returntitlewithtitle:DDMMMYYYYHHMMdate];
                }
            }
        }else{
            return DDMMMYYYYHHMMdate;
        }

    }
}

