+(NSString *) returndateformatYYYYMMDDHHMMSSwithdate:(NSString *)yyyymmddhhmmss
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    
    if ([globalvariables.language isEqualToString:@"English"]) {
        return [MyClass convertYYYYMMDDHHMMSStoDDMMMYYYYHHMMSSwithdatetime:yyyymmddhhmmss];
    }else{
        if ([yyyymmddhhmmss length]==19){
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];[df setDateFormat:@"yyyy-MM-dd HH:mm:ss"];
                NSDate *date=[df dateFromString:yyyymmddhhmmss];
                
                if (date) {
                    df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];[df setDateFormat:@"yyyy年M月d日 HH:mm:ss"];
                    return [df stringFromDate:date];
                }
        }
    }
    return yyyymmddhhmmss;
}

+(NSString *) returndateformatEEEDDMMMYYYYwithdateDDMMMYYYY:(NSString *)ddmmmyyyy
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    
    df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];[df setDateFormat:@"dd-MMM-yyyy"];
    NSDate *date=[df dateFromString:ddmmmyyyy];
    
    if ([globalvariables.language isEqualToString:@"English"]) {
        if ([self isDateFallsThisYear:date]) {
            [df setDateFormat:@"EEE dd MMM"];
        }else{
            [df setDateFormat:@"EEE dd MMM yyyy"];
        }
        return [df stringFromDate:date];
    }else{
        df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];
        if ([self isDateFallsThisYear:date]) {
            [df setDateFormat:@"EE M月d日"];
        }else{
            [df setDateFormat:@"EE yyyy年M月d日"];
        }
        return [df stringFromDate:date];
    }
}

