+(NSString *) returnrecipientwithrecipient:(NSString *)recipient
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    NSString *result;
    
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];[df setDateFormat:@"dd-MMM-yyyy"];
    
    if ([globalvariables.language isEqualToString:@"English"]) {
        return recipient;
    }else{
        if ([recipient length]>=11) {
            if ([df dateFromString:[recipient substringToIndex:11]]) {
                return [NSString stringWithFormat:@"%@ %@",[MyClass returndateformatwithdate:[recipient substringToIndex:11]],[MyClass returntitlewithtitle:@"Students"]];
            }else{
                //duplicated section
                result=[MyClass returntitlewithtitle:recipient];
                if ([result isEqualToString:recipient]) {
                    if ([recipient rangeOfString:@"Students and Leads"].location !=NSNotFound){
                        if ([recipient isEqualToString:@"All Students and Leads"]) {
                            return [MyClass returntitlewithtitle:@"All Students and Leads"];
                        }else{
                            return [recipient stringByReplacingOccurrencesOfString:@"Students and Leads" withString:[MyClass returntitlewithtitle:@"Students and Leads"]];
                        }
                    }else if ([recipient rangeOfString:@"Students"].location !=NSNotFound) {
                        if ([recipient isEqualToString:@"All Students"]) {
                            return [MyClass returntitlewithtitle:@"All Students"];
                        }else{
                            return [recipient stringByReplacingOccurrencesOfString:@"Students" withString:[MyClass returntitlewithtitle:@"Students"]];
                        }
                    }else if ([recipient rangeOfString:@"Leads"].location !=NSNotFound){
                        return [MyClass returntitlewithtitle:recipient];
                        /*
                        if ([recipient isEqualToString:@"All Leads"]) {
                            return [MyClass returntitlewithtitle:@"All Leads"];
                        }else{
                            return [recipient stringByReplacingOccurrencesOfString:@"Leads" withString:[MyClass returntitlewithtitle:@"Leads"]];
                        }*/
                    }else{
                        return recipient;
                    }
                }else{
                    return result;
                }
            }
        }else{
            //duplicated section
            result=[MyClass returntitlewithtitle:recipient];
            if ([result isEqualToString:recipient]) {
                if ([recipient rangeOfString:@"Students and Leads"].location !=NSNotFound){
                    if ([recipient isEqualToString:@"All Students and Leads"]) {
                        return [MyClass returntitlewithtitle:@"All Students and Leads"];
                    }else{
                        return [recipient stringByReplacingOccurrencesOfString:@"Students and Leads" withString:[MyClass returntitlewithtitle:@"Students and Leads"]];
                    }
                }else if ([recipient rangeOfString:@"Students"].location !=NSNotFound) {
                    if ([recipient isEqualToString:@"All Students"]) {
                        return [MyClass returntitlewithtitle:@"All Students"];
                    }else{
                        return [recipient stringByReplacingOccurrencesOfString:@"Students" withString:[MyClass returntitlewithtitle:@"Students"]];
                    }
                }else if ([recipient rangeOfString:@"Leads"].location !=NSNotFound){
                    return [MyClass returntitlewithtitle:recipient];
                    /*
                     if ([recipient isEqualToString:@"All Leads"]) {
                     return [MyClass returntitlewithtitle:@"All Leads"];
                     }else{
                     return [recipient stringByReplacingOccurrencesOfString:@"Leads" withString:[MyClass returntitlewithtitle:@"Leads"]];
                     }*/
                }else{
                    return recipient;
                }
            }else{
                return result;
            }
        }
    }
}


