+(NSMutableAttributedString *) returngrouparraylabel:(NSMutableArray *)groupkeyarray grouparray:(NSMutableArray *)grouparray option:(NSString *)option
{
    NSMutableArray *result=[[NSMutableArray alloc]init];
    NSMutableArray *groupleadername=[[NSMutableArray alloc]init];
    for (int i=0; i<groupkeyarray.count; i++) {
        NSString *groupkey;
        NSString *groupmemberkey=@"";
        
        if ([option isEqualToString:@"groupkey"]) {
            groupkey=[groupkeyarray objectAtIndex:i];
        }else{
            GroupMemberRecord *member=[groupkeyarray objectAtIndex:i];
            groupkey=member.groupkey;
            if(member.leader){
                groupmemberkey=groupkey;
            }
        }
        
        for (int j=0; j<grouparray.count; j++) {
            if ([((GroupRecord *)[grouparray objectAtIndex:j]).groupkey isEqualToString:groupkey]) {
                [result addObject:((GroupRecord *)[grouparray objectAtIndex:j]).groupname];
                if(![groupmemberkey isEqualToString:@""]){
                    [groupleadername addObject:((GroupRecord *)[grouparray objectAtIndex:j]).groupname];
                }
                break;
            }
        }
    }
    
    //sort
    NSSortDescriptor* sortOrder = [NSSortDescriptor sortDescriptorWithKey: @"self" ascending:YES selector:@selector(localizedStandardCompare:)];
    result=[NSMutableArray arrayWithArray:[result sortedArrayUsingDescriptors: [NSArray arrayWithObject: sortOrder]]];
    if(result.count==0){
        return [[NSMutableAttributedString alloc] initWithString:@""];
    }else{
        NSString *string=[result componentsJoinedByString:@" / "];
        NSMutableAttributedString *attstring = [[NSMutableAttributedString alloc] initWithString:string];
        if (groupleadername.count>0) {
            for (int i=0; i<groupleadername.count; i++) {
                NSRange range = [string rangeOfString:groupleadername[i]];
                [attstring addAttribute:NSForegroundColorAttributeName value:[UIColor blueColor] range:range];
            }
        }
        return attstring;
    }
}


+(GroupRecord *) returngrouprecordwithgrouparray:(NSMutableArray *)grouparray groupkey:(NSString *)groupkey
{
    for (int i=0; i<grouparray.count; i++) {
        GroupRecord *object=[grouparray objectAtIndex:i];
        if ([object.groupkey isEqualToString:groupkey]) {
            return object;
        }
    }
    return nil;
}

+(NSString *) returnschoolmonthtitlewithschoolmonth:(NSString *)schoolmonth
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    NSDate *date;
    NSString *tmpresult;
    if ([globalvariables.language isEqualToString:@"English"]) {
        return schoolmonth;
    }else{
        if ([schoolmonth isEqualToString:@"TBD"] || [schoolmonth isEqualToString:@""]) {
            return [MyClass returntitlewithtitle:schoolmonth];
        }else{
            if ([schoolmonth length]==8) {
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];[df setDateFormat:@"MMM yyyy"];
                date=[df dateFromString:schoolmonth];
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];[df setDateFormat:@"yyyy年M月"];
                return [df stringFromDate:date];
            }else if ([schoolmonth length]==14){
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];[df setDateFormat:@"MMM yyyy"];
                date=[df dateFromString:[NSString stringWithFormat:@"%@ %@",[schoolmonth substringToIndex:3],[schoolmonth substringFromIndex:10]]];
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];[df setDateFormat:@"yyyy年M-"];
                tmpresult=[df stringFromDate:date];
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];[df setDateFormat:@"MMM"];
                date=[df dateFromString:[schoolmonth substringWithRange:NSMakeRange(6,3)]];
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];[df setDateFormat:@"M月"];
                return [NSString stringWithFormat:@"%@%@",tmpresult,[df stringFromDate:date]];
            }else{
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];[df setDateFormat:@"MMM yyyy"];
                date=[df dateFromString:[schoolmonth substringToIndex:8]];
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];[df setDateFormat:@"yyyy年M月-"];
                tmpresult=[df stringFromDate:date];
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];[df setDateFormat:@"MMM yyyy"];
                date=[df dateFromString:[schoolmonth substringFromIndex:11]];
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];[df setDateFormat:@"yyyy年M月"];
                return [NSString stringWithFormat:@"%@%@",tmpresult,[df stringFromDate:date]];
            }
        }
    }
}


+(NSString *) findSchoolMonthWithStartDateTime:(NSString *)startdatetime EndDate:(NSString *)enddate
{
    //GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    if ([startdatetime isEqualToString:@""] || !startdatetime) {
        return @"";
    }else if ([startdatetime isEqualToString:@"TBD"]){
        return @"TBD";
    }else{
        
        NSString *startschoolmonth;
        NSString *endschoolmonth;
        
        NSDateFormatter *df =[[NSDateFormatter alloc]init]; df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
        
        [df setDateFormat:@"dd-MMM-yyyy"];
        NSDate *date=[df dateFromString:[startdatetime substringToIndex:11]];
        
        [df setDateFormat:@"MMM yyyy"];
        startschoolmonth=[df stringFromDate:date];

        
        if ([enddate isEqualToString:@""] || [enddate isEqualToString:@"TBD"] || [enddate isEqualToString:@"TBF"]) {
            return startschoolmonth;
        }else{
            [df setDateFormat:@"dd-MMM-yyyy"];
            date=[df dateFromString:enddate];
            
            [df setDateFormat:@"MMM yyyy"];
            endschoolmonth=[df stringFromDate:date];
            
            if ([startschoolmonth isEqualToString:endschoolmonth]) {
                return startschoolmonth;
            }else{
                if ([[startschoolmonth substringFromIndex:[startschoolmonth length]-2]  isEqualToString:[endschoolmonth substringFromIndex:[endschoolmonth length]-2]]) {
                    return [NSString stringWithFormat:@"%@ - %@",[startschoolmonth substringToIndex:3],endschoolmonth];
                }else{
                    return [NSString stringWithFormat:@"%@ - %@",startschoolmonth,endschoolmonth];
                }
            }
        }
    }
}

