+(NSString *) returnreplacedtitlewithtitle:(NSString *)title replacementarray:(NSArray *)replacementarray
{
    
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    NSString *replacedchar=@"%@";
    
    LanguageTitleRecord *titlerecord=[globalvariables.languagetitledictionary objectForKey:[NSString stringWithFormat:@"%@#%@",globalvariables.centerrecord.centerkey,title]];
    if (titlerecord) {
        NSString *titleresult=[titlerecord valueForKey:[globalvariables.language lowercaseString]];
        for (int i=0; i<replacementarray.count; i++) {
            NSString *replacedstring=[NSString stringWithFormat:@"%@%d",replacedchar,i+1];
            titleresult=[titleresult stringByReplacingOccurrencesOfString:replacedstring withString:[replacementarray objectAtIndex:i]];
        }
        return titleresult;
    }else{
        NSString *titleresult=title;
        for (int i=0; i<replacementarray.count; i++) {
            NSString *replacedstring=[NSString stringWithFormat:@"%@%d",replacedchar,i+1];
            titleresult=[titleresult stringByReplacingOccurrencesOfString:replacedstring withString:[replacementarray objectAtIndex:i]];
        }
        return titleresult;
    }
}



