    return classdaystring;
}


+(NSString *) returndayofweek:(NSString *)datestring
{
    if ([datestring isEqualToString:@""] || !datestring) {
        return @"";
    }else{
        NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
        
        if ([datestring isEqualToString:@"TBD"]) {
            return @"TBD";
        }else{
            [df setDateFormat:@"dd-MMM-yyyy"];
            if ([datestring length]<11) {
                return @"";
            }else{
                NSDate *date=[df dateFromString:[datestring substringToIndex:11]];
                [df setDateFormat:@"EEE"];
                return [df stringFromDate:date];
            }
        }
    }
}

