+(ClassroomRecord *) returnclassroominformationwithclassroom:(NSString *)classroom centerkey:(NSString *)centerkey
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    NSMutableArray *tmpclassroomlistarray=[[NSMutableArray alloc]initWithArray:[globalvariables.classroomlistarray allValues]];
    
    NSPredicate *predicate = [NSPredicate predicateWithFormat:@"self.centerkey=%@",globalvariables.centerrecord.centerkey];
    NSPredicate *newpredicate = [NSPredicate predicateWithFormat:@"self.classroom=%@",classroom];
    predicate=[NSCompoundPredicate andPredicateWithSubpredicates:@[predicate,newpredicate]];
    
    
    tmpclassroomlistarray=[[NSMutableArray alloc]initWithArray:[tmpclassroomlistarray filteredArrayUsingPredicate:predicate]];
    
    return tmpclassroomlistarray.count>0?[tmpclassroomlistarray firstObject]:nil;
    
}

+ (NSString *) calculateTuitionFeeWithClass:(NSString *)class Levelmain:(NSString *)levelmain noOfClass:(NSString *)noOfClass startdatetime:(NSString *)startdatetime schedulekey:(NSString *)tmpSchedulekey schedulerecord:(ScheduleRecord *)schedulerecord Grade:(NSString *)grade EnrollmentTableMode:(NSString *)EnrollmentTableMode freescheduleclassarray:(NSMutableArray *)freescheduleclassarray
{
    
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    
    int noofclassinfreescheduleclassarray=[self returnnoofclasswithfreescheduleclassarray:freescheduleclassarray];
    
    
    if (!freescheduleclassarray || noofclassinfreescheduleclassarray==0 || ([startdatetime isEqualToString:@""] && ![tmpSchedulekey isEqualToString:@"-2"] && ![tmpSchedulekey isEqualToString:@"-1"])) {
        return @"0";
    }else{
        float tuitionfee=0;
        NSMutableArray *tuitionArray=((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:class centerkey:globalvariables.centerrecord.centerkey]).tuitionArray;
        TuitionRecord *tuitionobject=[[TuitionRecord alloc]init];
        NSString *tuitionmode=((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:class centerkey:globalvariables.centerrecord.centerkey]).tuition_mode;
        
        if (![class isEqualToString:@""] && noofclassinfreescheduleclassarray>0) {
            for (int j=0; j<tuitionArray.count; j++) {
                tuitionobject=[tuitionArray objectAtIndex:j];
                if ([tuitionobject.method isEqualToString:@"Level"]) {
                    if ([tuitionobject.scale isEqualToString:levelmain]) {
                        if ([tuitionmode isEqualToString:@"Class"]) {
                            tuitionfee=[tuitionobject.tuitionfee floatValue]*noofclassinfreescheduleclassarray;
                        }else{
                            tuitionfee=[tuitionobject.tuitionfee floatValue]*[self findnumberofmonthwithschedulerecord:schedulerecord freescheduleclassarray:freescheduleclassarray];
                        }
                        break;
                    }
                }else if ([tuitionobject.method isEqualToString:@"Grade"]){
                    if ([grade isEqualToString:@""]) {
                        UIAlertController *erroralert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Tuition Fee cannot be calculated"] message:[MyClass returntitlewithtitle:@"Grade information is missing for this student. Please input in the student profile."] preferredStyle:UIAlertControllerStyleAlert];
                        
                        UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                            [erroralert dismissViewControllerAnimated:YES completion:nil];
                        }];
                        
                        [erroralert addAction:OKAction];
                        [[self topMostController] presentViewController:erroralert animated:YES completion:nil];
                        break;
                    }else{
                        if ([tuitionobject.scale isEqualToString:grade]) {
                            if ([tuitionmode isEqualToString:@"Class"]) {
                                tuitionfee=[tuitionobject.tuitionfee floatValue]*noofclassinfreescheduleclassarray;
                            }else{
                                tuitionfee=[tuitionobject.tuitionfee floatValue]*[self findnumberofmonthwithschedulerecord:schedulerecord freescheduleclassarray:freescheduleclassarray];
                            }
                            break;
                        }
                    }
                }
            }
        }
        
        
        if (tuitionfee==0) {
            return @"0";
        }else if (tuitionfee==(int)tuitionfee) {
            return [NSString stringWithFormat:@"%g",tuitionfee];
        }else{
            if (globalvariables.centerrecord.noofroundoffdigit==1) {
                if ([[NSString stringWithFormat:@"%.1f",tuitionfee] hasSuffix:@".0"]) {
                    return [[NSString stringWithFormat:@"%.1f",tuitionfee] substringToIndex:[[NSString stringWithFormat:@"%.1f",tuitionfee] length]-2];
                }else{
                    return [NSString stringWithFormat:@"%.1f",tuitionfee];
                }
            }else{
                return [NSString stringWithFormat:@"%ld",lroundf(tuitionfee)];
            }
        }
    }
}

+(float) findnumberofmonthwithschedulerecord:(ScheduleRecord *)schedulerecord freescheduleclassarray:(NSMutableArray *)freescheduleclassarray
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    
    NSString *startdatetime;
    NSDate *monthstartdate;
    NSDate *monthenddate;
    NSDate *monthfirstdate;
    NSString *monthfirstdatestring;
    NSDate *xdate;
    float totalnumberoflesson;
    NSDateComponents *dateComponents = [[NSDateComponents alloc] init];
    NSCalendar *calendar = [NSCalendar currentCalendar];
    NSDate *startdate;
    NSString *startdatestring;
    NSString *startdatetimestring;
    NSDateComponents *components = [[NSDateComponents alloc] init];;
    NSUInteger weekdayToday;
    NSInteger daysToFirstMatchingDayofWeek;
    float numberofmonth=0;
    ScheduleDetailsRecord *scheduledetailsobject;
    
    
    FreeScheduleClass *freescheduleobject;
    NSMutableDictionary *dict=[[NSMutableDictionary alloc]init];
    NoOfMonthLesson *noofmonthlessonobject;
    
    if (freescheduleclassarray.count>0) {
        if ([schedulerecord.schedulekey intValue]<0) {
            startdatetime=((FreeScheduleClass *)[freescheduleclassarray firstObject]).classdate;
            for (int i=0; i<freescheduleclassarray.count; i++) {
                totalnumberoflesson=0;
                freescheduleobject=[freescheduleclassarray objectAtIndex:i];
                monthfirstdatestring=[NSString stringWithFormat:@"01%@",[freescheduleobject.classdate substringFromIndex:2]];
                monthfirstdate=[self convertToNSDateWithDate:monthfirstdatestring DateFormat:@"dd-MMM-yyyy"];
                if (![freescheduleobject.action isEqualToString:@"Delete"] && monthfirstdate) {
                    
                    noofmonthlessonobject=[dict objectForKey:monthfirstdatestring];
                    if (noofmonthlessonobject) {
                        noofmonthlessonobject.nooflesson+=1;
                        [dict removeObjectForKey:monthfirstdatestring];
                        [dict setValue:noofmonthlessonobject forKey:monthfirstdatestring];
                    }else{
                        //find first matching day of week
                        components = [calendar components:NSCalendarUnitYear | NSCalendarUnitMonth | NSCalendarUnitWeekday | NSCalendarUnitDay fromDate:monthfirstdate];
                        
                        weekdayToday = [components weekday];
                        daysToFirstMatchingDayofWeek=[MyClass returndayofweeknumber:[MyClass returndayofweek:startdatetime]]-weekdayToday;
                        if (daysToFirstMatchingDayofWeek<0) {
                            daysToFirstMatchingDayofWeek+=7;
                        }
                        monthstartdate = [monthfirstdate dateByAddingTimeInterval:60*60*24*daysToFirstMatchingDayofWeek];
                        
                        //find month enddate
                        [dateComponents setMonth:1];
                        monthenddate = [calendar dateByAddingComponents:dateComponents toDate:monthfirstdate options:0];
                        monthenddate=[monthenddate dateByAddingTimeInterval:-24*60*60];
                        
                        
                        long startingindex=[MyClass returnDateOffsetWithDate:monthstartdate];
                        
                        for (long i=startingindex; i<startingindex+3650; i+=7) {
                            xdate=[MyClass convertToNSDateWithDate:[MyClass returnDateFromBaseDateWithOffset:i] DateFormat:@"dd-MMM-yyyy"];
                            if ([MyClass isWorkingDate:xdate includereserveddate:NO]) {
                                if ([monthenddate compare:xdate]!=NSOrderedAscending){
                                    totalnumberoflesson+=1;
                                }else{
                                    break;
                                }
                            }
                        }
                        
                        [dict setValue:[[NoOfMonthLesson alloc]initNoOfMonthLessonwithtotallesson:totalnumberoflesson nooflesson:1] forKey:monthfirstdatestring];
                        
                    }
                }
            }
            
            for (NSString* key in dict) {
                noofmonthlessonobject = [dict objectForKey:key];
                if (globalvariables.centerrecord.monthlymodeweeklyscheduletuitiondenominator >0) {
                    if (noofmonthlessonobject.totallesson!=noofmonthlessonobject.nooflesson) {
                        totalnumberoflesson=globalvariables.centerrecord.monthlymodeweeklyscheduletuitiondenominator;
                        numberofmonth+=noofmonthlessonobject.nooflesson/globalvariables.centerrecord.monthlymodeweeklyscheduletuitiondenominator;
                    }else{
                        numberofmonth+=noofmonthlessonobject.nooflesson/noofmonthlessonobject.totallesson;
                    }
                }else{
                    numberofmonth+=noofmonthlessonobject.nooflesson/noofmonthlessonobject.totallesson;
                }
            }
            
        }else{
            if ([schedulerecord.type isEqualToString:@"Fixed"]) {
                
                NSString *startdate=@"";
                NSString *enddate=@"";
                for (int i=0; i<freescheduleclassarray.count; i++) {
                    FreeScheduleClass *obj=[freescheduleclassarray objectAtIndex:i];
                    
                    if (![obj.action isEqualToString:@"Delete"]) {
                        if ([startdate isEqualToString:@""] || [[MyClass convertToNSDateWithDate:startdate DateFormat:@"dd-MMM-yyyy"] compare:[MyClass convertToNSDateWithDate:obj.classdate DateFormat:@"dd-MMM-yyyy"]]==NSOrderedDescending) {
                            startdate=obj.classdate;
                        }

                        if ([enddate isEqualToString:@""] || [[MyClass convertToNSDateWithDate:enddate DateFormat:@"dd-MMM-yyyy"] compare:[MyClass convertToNSDateWithDate:obj.classdate DateFormat:@"dd-MMM-yyyy"]]==NSOrderedAscending) {
                            enddate=obj.classdate;
                        }
                    }
                }
                
                numberofmonth= [self monthsSince:[MyClass convertToNSDateWithDate:[NSString stringWithFormat:@"%@ 23:59",startdate] DateFormat:@"dd-MMM-yyyy HH:mm"] to:[MyClass convertToNSDateWithDate:[NSString stringWithFormat:@"%@ 23:59",enddate] DateFormat:@"dd-MMM-yyyy HH:mm"]];
            }else{
                [df setDateFormat:@"dd-MMM-yyyy HH:mm"];
                startdatetime=((FreeScheduleClass *)[freescheduleclassarray firstObject]).classdate;
                for (int i=0; i<freescheduleclassarray.count; i++) {
                    totalnumberoflesson=0;
                    freescheduleobject=[freescheduleclassarray objectAtIndex:i];
                    if (![freescheduleobject.action isEqualToString:@"Delete"]) {
                        monthfirstdatestring=[NSString stringWithFormat:@"01%@",[freescheduleobject.classdate substringFromIndex:2]];
                        monthfirstdate=[self convertToNSDateWithDate:monthfirstdatestring DateFormat:@"dd-MMM-yyyy"];
                        noofmonthlessonobject=[dict objectForKey:monthfirstdatestring];
                        if (noofmonthlessonobject) {
                            noofmonthlessonobject.nooflesson+=1;
                            [dict removeObjectForKey:monthfirstdatestring];
                            [dict setValue:noofmonthlessonobject forKey:monthfirstdatestring];
                        }else{
                            //find month enddate
                            [dateComponents setMonth:1];
                            monthenddate = [calendar dateByAddingComponents:dateComponents toDate:monthfirstdate options:0];
                            monthenddate = [[MyClass convertToNSDateWithDate:[NSString stringWithFormat:@"01%@ 23:59",[[MyClass convertToNSStringWithNSDate:monthenddate DateFormat:@"dd-MMM-yyyy"] substringFromIndex:2]] DateFormat:@"dd-MMM-yyyy HH:mm"] dateByAddingTimeInterval:-24*60*60];
                            NSArray *allweekarray=[MyClass returnschedulearraywithschedulerecord:schedulerecord];
                            
                            long startingindex=[MyClass returnDateOffsetWithDate:monthfirstdate];
                            
                            
                            for (long i=startingindex; i<startingindex+3650; i++) {
                                startdatestring=[MyClass returnDateFromBaseDateWithOffset:i];
                                startdate=[MyClass convertToNSDateWithDate:startdatestring DateFormat:@"dd-MMM-yyyy"];
                                long weeknumber=[MyClass returndayofweeknumber:[MyClass returndayofweek:startdatestring]]-1;
                                
                                if ([MyClass isWorkingDate:startdate includereserveddate:NO]) {
                                    for (int j=0; j<((NSMutableArray *)[allweekarray objectAtIndex:weeknumber]).count; j++) {
                                        scheduledetailsobject=[((NSMutableArray *)[allweekarray objectAtIndex:weeknumber]) objectAtIndex:j];
                                        startdatetimestring=[NSString stringWithFormat:@"%@ %@",startdatestring,scheduledetailsobject.classtime];
                                        xdate=[df dateFromString:startdatetimestring];
                                        
                                        if ([monthenddate compare:xdate]!=NSOrderedAscending){
                                            totalnumberoflesson+=1;
                                        }else{
                                            i=startingindex+3650;
                                            break;
                                        }
                                    }
                                }
                            }

                            [dict setValue:[[NoOfMonthLesson alloc]initNoOfMonthLessonwithtotallesson:totalnumberoflesson nooflesson:1] forKey:monthfirstdatestring];
                        }
                    }
                }
                
                for (NSString* key in dict) {
                    noofmonthlessonobject = [dict objectForKey:key];
                    numberofmonth+=noofmonthlessonobject.nooflesson/noofmonthlessonobject.totallesson;
                }
            }
            
        }
    }
    return numberofmonth;
}

+ (NSInteger)monthsSince:(NSDate *)from to:(NSDate *)to {
    NSCalendar *calendar = [[NSCalendar alloc] initWithCalendarIdentifier:NSCalendarIdentifierGregorian];
    NSDateComponents *fromComponents = [calendar components:NSCalendarUnitMonth | NSCalendarUnitYear fromDate:from];
    NSDateComponents *toComponents = [calendar components:NSCalendarUnitMonth | NSCalendarUnitYear fromDate:to];

    return ((toComponents.year - fromComponents.year) * 12) + (toComponents.month - fromComponents.month)+1;
}
