+(NSDate *) removedaycomponents:(NSDate *)date
{
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    
    
    [df setDateFormat:@"MMM-yyyy"];
    NSString *datestring=[df stringFromDate:date];
    return [df dateFromString:datestring];
    
}

+(NSString *)leadingtrailingspacestrimmed:(NSString *)string
{
    NSString *result=  [string stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
    return result;
}

+(NSString *)allspacestrimmed:(NSString *)string
{
    NSString *result=  [string stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
    result = [result stringByReplacingOccurrencesOfString:@" " withString:@""];
    return result;
}

+(UIView *) drawAssessmentSpiderChart:(AssessmentFormSectionObject *)assessmentformsectionobject inview:(UIView *)view size:(NSString *)size
{
    NSInteger elementcount=assessmentformsectionobject.questionarray.count;
    float sectorangle=360/elementcount*M_PI/180;
    float sectorlength=view.frame.size.width/2;
    
    UIView *spiderChartView=[[UIView alloc]initWithFrame:CGRectMake(0, 0, view.frame.size.width, view.frame.size.height)];
    
    //draw spider lines
    CAShapeLayer *drawobject = [CAShapeLayer layer];
    CGMutablePathRef path;
    
    CGFloat x;
    CGFloat y;
    drawobject = [CAShapeLayer layer];
    path = CGPathCreateMutable();
    
    for (int i=0; i<5; i++) {
        CGFloat ringsectorlength = (i+1)*sectorlength/5;
        CGPathMoveToPoint(path, NULL, sectorlength, sectorlength-ringsectorlength);
        
        for (int j=1; j<elementcount; j++) {
            x=ringsectorlength*sinf(sectorangle*j)+sectorlength;
            y=sectorlength-ringsectorlength*cosf(sectorangle*j);
            CGPathAddLineToPoint(path, NULL, x, y);
            
            if(i==4){
                CGPathAddLineToPoint(path, NULL, sectorlength, sectorlength);
                CGPathMoveToPoint(path, NULL, x,y);
            }
        }
        CGPathAddLineToPoint(path, NULL, sectorlength, sectorlength-ringsectorlength);
        if(i==4){
            CGPathAddLineToPoint(path, NULL, sectorlength, sectorlength);
        }
    }
    
    [drawobject setPath:path];
    [drawobject setStrokeColor:[[UIColor lightGrayColor] CGColor]];
    [drawobject setFillColor:[[UIColor clearColor] CGColor]];
    [[spiderChartView layer] addSublayer:drawobject];
    CGPathRelease(path);
    
    //add result
    drawobject = [CAShapeLayer layer];
    path = CGPathCreateMutable();
    
    CGFloat interval = sectorlength/10;
    AssessmentFormRowObject *obj = [assessmentformsectionobject.questionarray objectAtIndex:0];
    if([obj.responsearray[0] isEqualToString:@"NA"]){
        CGPathMoveToPoint(path, NULL, sectorlength, sectorlength);
    }else{
        CGPathMoveToPoint(path, NULL, sectorlength, sectorlength-[obj.responsearray[0] floatValue]*interval);
    }
    
    for (int i=1; i<elementcount; i++) {
        AssessmentFormRowObject *obj = [assessmentformsectionobject.questionarray objectAtIndex:i];
        if([obj.responsearray[0] isEqualToString:@"NA"]){
            CGPathAddLineToPoint(path, NULL, sectorlength, sectorlength);
        }else{
            x=[obj.responsearray[0] floatValue]*interval*sinf(sectorangle*i)+sectorlength;
            y=sectorlength-[obj.responsearray[0] floatValue]*interval*cosf(sectorangle*i);
            CGPathAddLineToPoint(path, NULL, x, y);
        }
    }
    
    if([obj.responsearray[0] isEqualToString:@"NA"]){
        CGPathAddLineToPoint(path, NULL, sectorlength, sectorlength);
    }else{
        CGPathAddLineToPoint(path, NULL, sectorlength, sectorlength-[obj.responsearray[0] floatValue]*interval);
    }
    
    [drawobject setPath:path];
    [drawobject setStrokeColor:[[UIColor blueColor] CGColor]];
    [drawobject setFillColor:[[UIColor colorWithRed:0.0/255.0 green:122.0/255.0 blue:255.0/255.0 alpha:0.4] CGColor]];
    [[spiderChartView layer] addSublayer:drawobject];
    CGPathRelease(path);
    
    return spiderChartView;
    
}

+(UIView *) drawattendanceringwithbutton:(UIButton *)button basebutton:(NSString *)basebutton highlightbutton:(NSString *)highlightbutton attendancebuttonarray:(NSMutableArray *)buttonarray inview:(UIView *)view size:(NSString *)size
{
    float outercircleradius;
    float innercircleradius;
    
    if ([size isEqualToString:@"large"]) {
        outercircleradius=attendanceringouterradius_large;
        innercircleradius=attendanceringinnerradius_large;
    }else{
        outercircleradius=attendanceringouterradius_small;
        innercircleradius=attendanceringinnerradius_small;
    }
    
    long baseindex=0;
    long highlightindex=-1;
    for (int i=0; i<buttonarray.count; i++) {
        if ([((AttendanceButtonObject *)[buttonarray objectAtIndex:i]).buttonname isEqualToString:basebutton]) {
            baseindex=i;
        }
        
        if([((AttendanceButtonObject *)[buttonarray objectAtIndex:i]).buttonname isEqualToString:highlightbutton]) {
            if (i-baseindex>=0) {
                highlightindex=i-baseindex;
            }else{
                highlightindex=i-baseindex+buttonarray.count;
            }
        }
    }
    
    //re-arrange button order
    for (int i=0; i<baseindex; i++) {
        [buttonarray addObject:[buttonarray firstObject]];
        [buttonarray removeObjectAtIndex:0];
    }
    
    CGRect buttonabsoluteframe = [button convertRect:button.bounds toView:view];
    UIView *attendanceringview=[[UIView alloc]initWithFrame:CGRectMake(buttonabsoluteframe.origin.x+buttonabsoluteframe.size.width/2-outercircleradius,buttonabsoluteframe.origin.y+buttonabsoluteframe.size.height/2-(outercircleradius+(outercircleradius+innercircleradius)/2), outercircleradius*2, outercircleradius*2)];
    
    CAShapeLayer *drawobject = [CAShapeLayer layer];
    UIButton *subattendancebutton=[[UIButton alloc]init];
    
    float sectorangle=360/buttonarray.count;
    float startingangle=(90-sectorangle/2);
    CGMutablePathRef path;
    
    for (int i=0; i<buttonarray.count; i++) {
        drawobject = [CAShapeLayer layer];
        path = CGPathCreateMutable();
        CGPathAddArc(path, NULL, outercircleradius, outercircleradius, outercircleradius, (startingangle+sectorangle*i)*M_PI/180,(startingangle+sectorangle*(i+1))*M_PI/180, 0);
        CGPathAddLineToPoint(path, NULL, outercircleradius+innercircleradius*cosf((startingangle+sectorangle*(i+1))*M_PI/180), outercircleradius+innercircleradius*sinf((startingangle+sectorangle*(i+1))*M_PI/180));
        CGPathAddArc(path, NULL, outercircleradius, outercircleradius, innercircleradius, (startingangle+sectorangle*(i+1))*M_PI/180, (startingangle+sectorangle*i)*M_PI/180, 1);
        CGPathAddLineToPoint(path, NULL, outercircleradius+outercircleradius*cosf((startingangle+sectorangle*i)*M_PI/180), outercircleradius+outercircleradius*sinf((startingangle+sectorangle*i)*M_PI/180));
        [drawobject setPath:path];
        [drawobject setStrokeColor:[[UIColor grayColor] CGColor]];
        [drawobject setFillColor:[((AttendanceButtonObject *)[buttonarray objectAtIndex:i]).sectorcolor CGColor]];
        
        if (i==highlightindex) {
            [drawobject setOpacity:1.0f];
            [drawobject setFillColor:[[UIColor systemGroupedBackgroundColor] CGColor]];
        }else{
            [drawobject setOpacity:0.9f];
            [drawobject setFillColor:[((AttendanceButtonObject *)[buttonarray objectAtIndex:i]).sectorcolor CGColor]];
        }
        
        [[attendanceringview layer] addSublayer:drawobject];
        CGPathRelease(path);
        
        if ([size isEqualToString:@"large"]) {
            subattendancebutton=[[UIButton alloc]initWithFrame:CGRectMake(outercircleradius+(innercircleradius+outercircleradius)/2*cosf((startingangle+sectorangle*i+sectorangle/2)*M_PI/180)-16, outercircleradius+(innercircleradius+outercircleradius)/2*sinf((startingangle+sectorangle*i+sectorangle/2)*M_PI/180)-16, 32, 32)];
        }else{
            subattendancebutton=[[UIButton alloc]initWithFrame:CGRectMake(outercircleradius+(innercircleradius+outercircleradius)/2*cosf((startingangle+sectorangle*i+sectorangle/2)*M_PI/180)-12, outercircleradius+(innercircleradius+outercircleradius)/2*sinf((startingangle+sectorangle*i+sectorangle/2)*M_PI/180)-12, 24, 24)];
        }
        
        
        [subattendancebutton setImage:[UIImage imageNamed:((AttendanceButtonObject *)[buttonarray objectAtIndex:i]).imagename] forState:UIControlStateNormal];
        [subattendancebutton setOpaque:1.0f];
        subattendancebutton.userInteractionEnabled=FALSE;
        [attendanceringview addSubview:subattendancebutton];
        
    }
    

    
    drawobject = [CAShapeLayer layer];
    path = CGPathCreateMutable();
    CGPathAddArc(path, NULL, outercircleradius, outercircleradius, innercircleradius, 0*M_PI/180, 360*M_PI/180, 1);
    [drawobject setPath:path];
    [drawobject setStrokeColor:[[UIColor grayColor] CGColor]];
    [drawobject setFillColor:[[UIColor systemGroupedBackgroundColor] CGColor]];
    [drawobject setOpacity:1.0f];
    [[attendanceringview layer] addSublayer:drawobject];
    CGPathRelease(path);
    
    if ([size isEqualToString:@"large"]) {
        UILabel *captionlabel=[[UILabel alloc]initWithFrame:CGRectMake(outercircleradius-innercircleradius+5, outercircleradius-innercircleradius+5, innercircleradius*2-10, innercircleradius*2-10)];
        if ([highlightbutton isEqualToString:@""]) {
            captionlabel.text=[MyClass returntitlewithtitle:@"attendance_Unknown"];
        }else{
            captionlabel.text=[MyClass returntitlewithtitle:[NSString stringWithFormat:@"attendance_%@",highlightbutton]];
        }
        captionlabel.font=[UIFont systemFontOfSize:13];
        captionlabel.textColor=[UIColor darkGrayColor];
        captionlabel.textAlignment=NSTextAlignmentCenter;
        captionlabel.numberOfLines=0;
        captionlabel.adjustsFontSizeToFitWidth = true;
        captionlabel.minimumScaleFactor=0.5;
        [attendanceringview addSubview:captionlabel];
    }
    
    return attendanceringview;
    
}

+(UIImage *) drawattendanceringiconwithbuttonarray:(NSMutableArray *)buttonarray
{
    float outercircleradius=20;
    
    UIView *attendanceringview=[[UIView alloc]initWithFrame:CGRectMake(0,0, outercircleradius*2, outercircleradius*2)];
    
    CAShapeLayer *drawobject = [CAShapeLayer layer];
    
    float sectorangle=360/buttonarray.count;
    float startingangle=(90-sectorangle/2);
    CGMutablePathRef path;
    
    for (int i=0; i<buttonarray.count; i++) {
        drawobject = [CAShapeLayer layer];
        path = CGPathCreateMutable();
        CGPathAddArc(path, NULL, outercircleradius, outercircleradius, outercircleradius, (startingangle+sectorangle*i)*M_PI/180,(startingangle+sectorangle*(i+1))*M_PI/180, 0);
        CGPathAddLineToPoint(path, NULL, outercircleradius, outercircleradius);
        CGPathAddArc(path, NULL, outercircleradius, outercircleradius, 0, (startingangle+sectorangle*(i+1))*M_PI/180, (startingangle+sectorangle*i)*M_PI/180, 1);
        CGPathAddLineToPoint(path, NULL, outercircleradius+outercircleradius*cosf((startingangle+sectorangle*i)*M_PI/180), outercircleradius+outercircleradius*sinf((startingangle+sectorangle*i)*M_PI/180));
        [drawobject setPath:path];
        [drawobject setStrokeColor:[[UIColor whiteColor] CGColor]];
        [drawobject setFillColor:[((AttendanceButtonObject *)[buttonarray objectAtIndex:i]).sectorcolor CGColor]];
        
        [drawobject setOpacity:1.0f];
        [drawobject setFillColor:[((AttendanceButtonObject *)[buttonarray objectAtIndex:i]).sectorcolor CGColor]];
        
        [[attendanceringview layer] addSublayer:drawobject];
        CGPathRelease(path);
    }
    
    drawobject = [CAShapeLayer layer];
    path = CGPathCreateMutable();
    CGPathAddArc(path, NULL, outercircleradius, outercircleradius, 0, 0*M_PI/180, 360*M_PI/180, 1);
    [drawobject setPath:path];
    [drawobject setStrokeColor:[[UIColor whiteColor] CGColor]];
    [drawobject setFillColor:[[UIColor whiteColor] CGColor]];
    [drawobject setOpacity:1.0f];
    [[attendanceringview layer] addSublayer:drawobject];
    CGPathRelease(path);
    

    UIGraphicsBeginImageContext(attendanceringview.bounds.size);
    [attendanceringview.layer renderInContext:UIGraphicsGetCurrentContext()];
    
    UIImage * img = UIGraphicsGetImageFromCurrentImageContext();
    
    UIGraphicsEndImageContext();
    
    return img;
    
}

+(long) updateattendanceringwithtouchpoint:(CGPoint)touchpoint attendanceringview:(UIView *)attendanceringview attendancebuttonarray:(NSMutableArray *)buttonarray lasttouchedsector:(long)lasttouchedsector size:(NSString *)size
{
    float outercircleradius;
    float innercircleradius;
    
    if ([size isEqualToString:@"large"]) {
        outercircleradius=attendanceringouterradius_large;
        innercircleradius=attendanceringinnerradius_large;
    }else{
        outercircleradius=attendanceringouterradius_small;
        innercircleradius=attendanceringinnerradius_small;
    }

    float sectorangle=360/buttonarray.count;
    float startingangle=(90-sectorangle/2);
    long highlightindex=-1;
    
    float touchangle=atan((touchpoint.y-outercircleradius)/(touchpoint.x-outercircleradius))*180/M_PI;
    if ((touchpoint.x-outercircleradius)<0) {
        touchangle+=180;
    }else if((touchpoint.x-outercircleradius)>0 && (touchpoint.y-outercircleradius)<0){
        touchangle+=360;
    }
    
    //NSLog(@"X:%f Y:%f A:%f",touchpoint.x,touchpoint.y,touchangle);
    highlightindex=((touchangle-startingangle)<0?(touchangle-startingangle+360):(touchangle-startingangle))/sectorangle;
    float distance = sqrtf(powf((touchpoint.x-outercircleradius),2)+powf((touchpoint.y-outercircleradius),2));
    
    
    if (distance<innercircleradius || distance>outercircleradius) {
        highlightindex=-1;
    }
    
    if (highlightindex != lasttouchedsector) {
        lasttouchedsector=highlightindex;
        
        for (UIButton *aButton in [attendanceringview subviews]) {
            [aButton removeFromSuperview];
        }
        
        for (UILabel *aLabel in [attendanceringview subviews]) {
            [aLabel removeFromSuperview];
        }
        
        attendanceringview.layer.sublayers=nil;
        
        CAShapeLayer *drawobject = [CAShapeLayer layer];
        UIButton *subattendancebutton=[[UIButton alloc]init];
        
        
        CGMutablePathRef path;
        
        for (int i=0; i<buttonarray.count; i++) {
            drawobject = [CAShapeLayer layer];
            path = CGPathCreateMutable();
            CGPathAddArc(path, NULL, outercircleradius, outercircleradius, outercircleradius, (startingangle+sectorangle*i)*M_PI/180,(startingangle+sectorangle*(i+1))*M_PI/180, 0);
            CGPathAddLineToPoint(path, NULL, outercircleradius+innercircleradius*cosf((startingangle+sectorangle*(i+1))*M_PI/180), outercircleradius+innercircleradius*sinf((startingangle+sectorangle*(i+1))*M_PI/180));
            CGPathAddArc(path, NULL, outercircleradius, outercircleradius, innercircleradius, (startingangle+sectorangle*(i+1))*M_PI/180, (startingangle+sectorangle*i)*M_PI/180, 1);
            CGPathAddLineToPoint(path, NULL, outercircleradius+outercircleradius*cosf((startingangle+sectorangle*i)*M_PI/180), outercircleradius+outercircleradius*sinf((startingangle+sectorangle*i)*M_PI/180));
            [drawobject setPath:path];
            [drawobject setStrokeColor:[[UIColor grayColor] CGColor]];
            
            
            if (i==highlightindex) {
                [drawobject setOpacity:1.0f];
                [drawobject setFillColor:[[UIColor systemGroupedBackgroundColor] CGColor]];
            }else{
                [drawobject setOpacity:0.9f];
                [drawobject setFillColor:[((AttendanceButtonObject *)[buttonarray objectAtIndex:i]).sectorcolor CGColor]];
            }
            
            [[attendanceringview layer] addSublayer:drawobject];
            CGPathRelease(path);
            //subattendancebutton=[[UIButton alloc]initWithFrame:CGRectMake(outercircleradius+(innercircleradius+outercircleradius)/2*cosf((startingangle+sectorangle*i+sectorangle/2)*M_PI/180)-16, outercircleradius+(innercircleradius+outercircleradius)/2*sinf((startingangle+sectorangle*i+sectorangle/2)*M_PI/180)-16, 32, 32)];
            
            if ([size isEqualToString:@"large"]) {
                subattendancebutton=[[UIButton alloc]initWithFrame:CGRectMake(outercircleradius+(innercircleradius+outercircleradius)/2*cosf((startingangle+sectorangle*i+sectorangle/2)*M_PI/180)-16, outercircleradius+(innercircleradius+outercircleradius)/2*sinf((startingangle+sectorangle*i+sectorangle/2)*M_PI/180)-16, 32, 32)];
            }else{
                subattendancebutton=[[UIButton alloc]initWithFrame:CGRectMake(outercircleradius+(innercircleradius+outercircleradius)/2*cosf((startingangle+sectorangle*i+sectorangle/2)*M_PI/180)-12, outercircleradius+(innercircleradius+outercircleradius)/2*sinf((startingangle+sectorangle*i+sectorangle/2)*M_PI/180)-12, 24, 24)];
            }
            
            
            [subattendancebutton setImage:[UIImage imageNamed:((AttendanceButtonObject *)[buttonarray objectAtIndex:i]).imagename] forState:UIControlStateNormal];
            [subattendancebutton setOpaque:1.0f];
            subattendancebutton.userInteractionEnabled=FALSE;
            [attendanceringview addSubview:subattendancebutton];
            
        }
        
        
         drawobject = [CAShapeLayer layer];
         path = CGPathCreateMutable();
         CGPathAddArc(path, NULL, outercircleradius, outercircleradius, innercircleradius, 0*M_PI/180, 360*M_PI/180, 1);
         [drawobject setPath:path];
         [drawobject setStrokeColor:[[UIColor grayColor] CGColor]];
         [drawobject setFillColor:[[UIColor systemGroupedBackgroundColor] CGColor]];
         [drawobject setOpacity:1.0f];
         [[attendanceringview layer] addSublayer:drawobject];
         CGPathRelease(path);
        
        
        if ([size isEqualToString:@"large"]) {
            UILabel *captionlabel=[[UILabel alloc]initWithFrame:CGRectMake(outercircleradius-innercircleradius+5, outercircleradius-innercircleradius+5, innercircleradius*2-10, innercircleradius*2-10)];
            if (highlightindex<0) {
                captionlabel.text=@"";
            }else{
                if ([((AttendanceButtonObject *)[buttonarray objectAtIndex:highlightindex]).buttonname isEqualToString:@""]) {
                    captionlabel.text=[MyClass returntitlewithtitle:@"attendance_Unknown"];
                }else{
                    captionlabel.text=[MyClass returntitlewithtitle:[NSString stringWithFormat:@"attendance_%@",((AttendanceButtonObject *)[buttonarray objectAtIndex:highlightindex]).buttonname]];
                }
            }
            captionlabel.font=[UIFont systemFontOfSize:13];
            captionlabel.textColor=[UIColor darkGrayColor];
            captionlabel.textAlignment=NSTextAlignmentCenter;
            captionlabel.adjustsFontSizeToFitWidth = true;
            captionlabel.minimumScaleFactor=0.5;
            captionlabel.numberOfLines=0;
            [attendanceringview addSubview:captionlabel];
        }
        

    }
    
    return highlightindex;
}

+(BOOL) returntouchpointwithinattendanceringwithtouchpoint:(CGPoint)touchpoint size:(NSString *)size
{
    float outercircleradius;
    float innercircleradius;
    
    if ([size isEqualToString:@"large"]) {
        outercircleradius=attendanceringouterradius_large;
        innercircleradius=attendanceringinnerradius_large;
    }else{
        outercircleradius=attendanceringouterradius_small;
        innercircleradius=attendanceringinnerradius_small;
    }
    
    float distance =sqrtf(powf((touchpoint.x-outercircleradius),2)+powf((touchpoint.y-outercircleradius),2));
        if (distance>innercircleradius && distance<outercircleradius) {
            return TRUE;
        }else{
            return FALSE;
        }
}

