+(NSString *) getlowestnumbercenterkey
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSMutableArray *tmparray=[[NSMutableArray alloc]initWithArray:[globalvariables.centerrecord.centerkey componentsSeparatedByString:@","]];
    NSSortDescriptor* sortOrder = [NSSortDescriptor sortDescriptorWithKey: @"self" ascending:YES selector:@selector(localizedStandardCompare:)];
    tmparray=[NSMutableArray arrayWithArray:[tmparray sortedArrayUsingDescriptors: [NSArray arrayWithObject: sortOrder]]];
    
    return [tmparray firstObject];
}
+(NSString *) getlocaldbwithparameter:(NSString *)parameter
{
    NSString *sql;
    sqlite3_stmt *statement;
    char *field1;
    NSString *result;
    
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    
    sql =[NSString stringWithFormat:@"SELECT parametervalue FROM settings where parametername='%@'",parameter];
    if(sqlite3_prepare_v2(globalvariables.isdb, [sql UTF8String], -1, &statement, nil)==SQLITE_OK){
        while (sqlite3_step(statement)==SQLITE_ROW) {
            field1 =(char *)sqlite3_column_text(statement, 0);
            result=[[NSString alloc]initWithUTF8String:field1];
        }
    }
    return result;
}

+(void) updatelocaldbwithparameter:(NSString *)parameter value:(NSString *)value
{
    NSString *sql;
    //sqlite3 *isdb;
    char *err;
    
    GlobalVariables *globalvariables=[GlobalVariables singleObj];

    sql=[NSString stringWithFormat:@"UPDATE settings SET parametervalue='%@' where parametername='%@'",value,parameter];
    sqlite3_exec(globalvariables.isdb,[sql UTF8String],NULL,NULL,&err);
}

