+(NSString *) returnprivilegedcenterkeywithcenterkey:(NSString *)centerkey type:(NSString *)type
{
    
    NSMutableArray *tmporigcenterkey=[[NSMutableArray alloc]initWithArray:[centerkey componentsSeparatedByString:@","]];
    NSMutableArray *tmpresultcenterkey=[[NSMutableArray alloc]init];
    
    
    if ([type isEqualToString:@"showallothertaskinnotification"]) {
        for (int i=0; i<tmporigcenterkey.count; i++) {
            if (((PrivilegeRecord *)[MyClass returnprivilegerecordwithcenterkey:[tmporigcenterkey objectAtIndex:i]]).showallothertaskinnotificationview) {
                [tmpresultcenterkey addObject:[tmporigcenterkey objectAtIndex:i]];
            }
        }
    }else if ([type isEqualToString:@"viewtaskassignment"]) {
        for (int i=0; i<tmporigcenterkey.count; i++) {
            if (((PrivilegeRecord *)[MyClass returnprivilegerecordwithcenterkey:[tmporigcenterkey objectAtIndex:i]]).viewtaskassignment) {
                [tmpresultcenterkey addObject:[tmporigcenterkey objectAtIndex:i]];
            }
        }
    }else if ([type isEqualToString:@"showallothertaskintaskassignmentview"]) {
        for (int i=0; i<tmporigcenterkey.count; i++) {
            if (((PrivilegeRecord *)[MyClass returnprivilegerecordwithcenterkey:[tmporigcenterkey objectAtIndex:i]]).showallothertaskintaskassignmentview) {
                [tmpresultcenterkey addObject:[tmporigcenterkey objectAtIndex:i]];
            }
        }
