+ (NSString *)retrievedevicelastupdaterecordwithparameter:(NSString *)parameter centerkey:(NSString *)centerkey {
    GlobalVariables *globalvariables = [GlobalVariables singleObj];
    LastUpdateRecord *record = [globalvariables.lastupdatedict valueForKey:centerkey];
    
    if (record && parameter.length > 0) {
        // Check if the record responds to the property selector to ensure the parameter exists
        SEL selector = NSSelectorFromString(parameter);
        if ([record respondsToSelector:selector]) {
            id value = [record valueForKey:parameter];
            
            if ([value isKindOfClass:[NSString class]]) {
                return (NSString *)value;
            }
        }
    }
    return @"";
}

