+(NSURL *) returnAvatarURLwithType:(NSString *)type avatar:(NSString *)avatar
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSURL *url;
    NSString *strURL;
    if ([type isEqualToString:@"student"]) {
        strURL=[NSString stringWithFormat:@"%@studentimages/%@/%@",globalvariables.serverpath,globalvariables.centerrecord.centerdb,avatar];
        if([avatar isEqualToString:@""]){
            return nil;
        }
    }else if ([type isEqualToString:@"lead"]){
        strURL=[NSString stringWithFormat:@"%@leadimages/%@/%@",globalvariables.serverpath,globalvariables.centerrecord.centerdb,avatar];
        if([avatar isEqualToString:@""]){
            return nil;
        }
    }else if ([type isEqualToString:@"staff"]){
        strURL=[NSString stringWithFormat:@"%@staffimages/%@/%@",globalvariables.serverpath,globalvariables.centerrecord.centerdb, avatar];
        if([avatar isEqualToString:@""]){
            return nil;
        }
    }
    
    url = [NSURL URLWithString:[strURL stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLQueryAllowedCharacterSet]]];
    
    return url;
        
    
}

+(void) downloadAvatarWithImageview:(UIImageView *)imageview gender:(NSString *)gender type:(NSString *)type avatar:(NSString *)avatar async:(BOOL)async
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    imageview.image=nil;
    
    UIImage *placeholderimage;
    if ([type isEqualToString:@"student"]) {
//        Student *obj=[self returnstudentwithstudentkey:typekey];
        if (gender) {
            if ([gender isEqualToString:@"Male"]) {
                placeholderimage=globalvariables.boyimage;
            }else if ([gender isEqualToString:@"Female"]){
                placeholderimage=globalvariables.girlimage;
            }else{
                placeholderimage=globalvariables.girlimage;
            }
        }
    }else if ([type isEqualToString:@"lead"]) {
//        Lead *obj=[self returnleadwithleadkey:typekey];
        if (gender) {
            if ([gender isEqualToString:@"Male"]) {
                placeholderimage=globalvariables.boyimage;
            }else if ([gender isEqualToString:@"Female"]){
                placeholderimage=globalvariables.girlimage;
            }else{
                placeholderimage=globalvariables.girlimage;
            }
        }
    }else if ([type isEqualToString:@"staff"]){
        placeholderimage=[UIImage imageNamed:@"staff_default_gray.png"];
    }
    //[imageview setImage:placeholderimage];
    
    if (![avatar isEqualToString:@""] ) {
        NSURL *url=[self returnAvatarURLwithType:type avatar:avatar];
        
        if(url){
            UIImage *receivedimage=[[SDImageCache sharedImageCache] imageFromCacheForKey:[url absoluteString]];
            if(receivedimage){
                [imageview setImage:receivedimage];
            }else{
                if (async) {
                    [imageview sd_setImageWithURL:url placeholderImage:placeholderimage];
                }else{
                    UIImage *receivedimage=[[UIImage alloc] initWithData:[NSData dataWithContentsOfURL:url]];
                    if (receivedimage) {
                        [imageview setImage:receivedimage];
                        [[SDImageCache sharedImageCache] storeImage:receivedimage forKey:[url absoluteString] completion:nil];
                    }else{
                        [imageview setImage:placeholderimage];
                    }
                }
            }
        }else{
            [imageview setImage:placeholderimage];
        }
    }else{
        [imageview setImage:placeholderimage];
    }
}


+(NSURL *) returndownloadImageURLwithType:(NSString *)type typekey:(NSString *)typekey
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSURL *url;
    NSString *strURL;
    
    if ([type isEqualToString:@"student"]) {
        Student *studentobject=[MyClass returnstudentwithstudentkey:typekey];
        strURL = [NSString stringWithFormat:@"%@studentimages/%@/%@",globalvariables.mediaDomain,globalvariables.centerrecord.centerdb,studentobject.avatar];
        if([studentobject.avatar isEqualToString:@""]){
            return nil;
        }
    }else if ([type isEqualToString:@"lead"]){
        Lead *leadobject=[MyClass returnleadwithleadkey:typekey];
        strURL = [NSString stringWithFormat:@"%@leadimages/%@/%@",globalvariables.mediaDomain,globalvariables.centerrecord.centerdb,leadobject.avatar];
        if([leadobject.avatar isEqualToString:@""]){
            return nil;
        }
    }else if ([type isEqualToString:@"staff"]){
        Staff *staffobject=[MyClass returnstaffrecordwithusername:typekey];
        strURL = [NSString stringWithFormat:@"%@staffimages/%@/%@",globalvariables.mediaDomain,globalvariables.centerrecord.centerdb, staffobject.avatar];
        if([staffobject.avatar isEqualToString:@""]){
            return nil;
        }
    }else if ([type isEqualToString:@"centerimage"] || [type isEqualToString:@"launchimage"] || [type isEqualToString:@"tierimage"]){
        strURL = [NSString stringWithFormat:@"%@centerimages/%@",globalvariables.mediaDomain,typekey];
    }else if ([type isEqualToString:@"studentappimage"]){
        strURL = [NSString stringWithFormat:@"%@centerimages/%@.png",globalvariables.mediaDomain,typekey];
    }else if ([type isEqualToString:@"staffappimage"]){
        strURL = [NSString stringWithFormat:@"%@centerimages/%@.png",globalvariables.mediaDomain,typekey];
    }else if ([type isEqualToString:@"class"]){
        strURL = [NSString stringWithFormat:@"%@classimages/%@/%@",globalvariables.mediaDomain,globalvariables.centerrecord.centerdb,typekey];
    }else if ([type isEqualToString:@"message"]){
        strURL = [NSString stringWithFormat:@"%@messageimages/%@/%@",globalvariables.mediaDomain,globalvariables.centerrecord.centerdb,typekey];
    }else if ([type isEqualToString:@"flag"]){
        strURL=[NSString stringWithFormat:@"%@.png",typekey];
        //strURL=@"/Users/jasmondluk/Google Drive/DreamWare/iSchool/Beta Development/iCenter 39100B0633/ischoolicenter/flagimages/AD.png";
    }else if ([type isEqualToString:@"whatsnew"]){
        strURL=[NSString stringWithFormat:@"%@whatsnewimages/%@",globalvariables.mediaDomain,typekey];
    }else if ([type isEqualToString:@"videomanual"]){
        strURL=[NSString stringWithFormat:@"%@videomanuals/%@",globalvariables.mediaDomain,typekey];
    }else if ([type isEqualToString:@"product"]){
        ProductRecord *productobject=[MyClass returnProductInformationWithCode:typekey centerkey:globalvariables.centerrecord.centerkey];
        strURL = [NSString stringWithFormat:@"%@productimages/%@/%@",globalvariables.mediaDomain,globalvariables.centerrecord.centerdb, productobject.avatar];
        if([productobject.avatar isEqualToString:@""]){
            return nil;
        }
    }else if ([type isEqualToString:@"subject"]){
        SubjectRecord *subjectobject=[MyClass returnsubjectinformationwithsubject_shortname:typekey centerkey:globalvariables.centerrecord.centerkey];
        strURL = [NSString stringWithFormat:@"%@subjectimages/%@/%@",globalvariables.mediaDomain,globalvariables.centerrecord.centerdb, subjectobject.subject_image];
        if([subjectobject.subject_image isEqualToString:@""]){
            return nil;
        }
    }
    
    url = [NSURL URLWithString:[strURL stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLQueryAllowedCharacterSet]]];
    
    ///Users/jasmondluk/Google Drive/DreamWare/iSchool/Beta Development/iCenter 39100B0633/ischoolicenter/flagimages/AD.png

    return url;
        
    
}

