            placeholderimage=[UIImage imageNamed:@"missingcenterimageicon_white.png"];
        }
    }
    
    if ([image isEqualToString:@"Yes"] && ![typekey isEqualToString:@""]) {
        NSURL *url=[self returndownloadImageURLwithType:type typekey:typekey];
        
        if ([type isEqualToString:@"centerimage"] || [type isEqualToString:@"class"]){
            imageview.backgroundColor=[UIColor colorWithRed:211.0/255.0 green:211.0/255.0 blue:211.0/255.0 alpha:1];
