                    }else{
                        [imageview setImage:placeholderimage];
                    }
                }
            }
        }else{
            [imageview setImage:placeholderimage];
        }
    }else{
        [imageview setImage:placeholderimage];
    }
}

+(NSString *) returnattendanceimagewithclasstype:(NSString *)classtype attendance:(NSString *)attendance makeupattendance:(NSString *)makeupattendance
{
    if ([attendance isEqualToString:@"Absent"]) {
        return @"absent_icon.png";
    }else if ([attendance isEqualToString:@"Makeup"]) {
        if ([classtype isEqualToString:@"Class"]) {
            return @"makeup_icon.png";
        }else{
            //makeup class
            if ([makeupattendance isEqualToString:@"Present"]) {
                return @"present_icon.png";
            }else if ([makeupattendance isEqualToString:@"Absent"]) {
                return @"absent_icon.png";
            }else{
                return @"unknown_icon.png";
            }
        }
    }else if ([attendance isEqualToString:@""]) {
        return @"unknown_icon.png";
    }else if ([attendance isEqualToString:@"Present"]){
        return @"present_icon.png";
    }else if ([attendance isEqualToString:@"Extend"]){
        return @"extend_icon.png";
    }
    return nil;
}

+(NSString *) returnmakeupattendanceimagewithmakeupattendance:(NSString *)makeupattendance
{
    if ([makeupattendance isEqualToString:@"Absent"]) {
        return @"absent_icon.png";
    }else if ([makeupattendance isEqualToString:@""]) {
        return @"unknown_icon.png";
    }else if ([makeupattendance isEqualToString:@"Present"]){
        return @"present_icon.png";
    }
    return nil;
}

+(BOOL) isattendingwithclasstype:(NSString *)classtype attendance:(NSString *)attendance makeupattendance:(NSString *)makeupattendance
{
    if ([attendance isEqualToString:@"Absent"]) {
        return NO;
    }else if ([attendance isEqualToString:@"Makeup"]) {
        if ([classtype isEqualToString:@"Class"]) {
            return NO;
        }else{
            //makeup class
            if ([makeupattendance isEqualToString:@"Present"]) {
                return YES;
            }else if ([makeupattendance isEqualToString:@"Absent"]) {
                return NO;
            }else{
                return YES;
            }
        }
    }else if ([attendance isEqualToString:@""]) {
        return YES;
    }else if ([attendance isEqualToString:@"Present"]){
        return YES;
    }else if ([attendance isEqualToString:@"Extend"]){
        return NO;
    }
    return NO;
}

