+(void) updatedevicelastupdatetimewithparameter:(NSString *)parameter centerkeyarray:(NSArray *)centerkeyarray systemcurrenttime:(NSString *)systemcurrenttime
{
    GlobalVariables *globalvariables = [GlobalVariables singleObj];
    char *err;
    
    SEL setterSelector = NSSelectorFromString(parameter);
    if (centerkeyarray && centerkeyarray.count > 0) {
        // Update only the specified center keys in the dictionary
        for (NSString *centerkey in centerkeyarray) {
            LastUpdateRecord *lastupdaterecord = globalvariables.lastupdatedict[centerkey];
            if (lastupdaterecord && [lastupdaterecord respondsToSelector:setterSelector]) {
                [lastupdaterecord setValue:systemcurrenttime forKey:parameter];
            }
        }
    } else {
        // Update all records in the dictionary if no array is provided
        for (LastUpdateRecord *lastupdaterecord in globalvariables.lastupdatedict.allValues) {
            if ([lastupdaterecord respondsToSelector:setterSelector]) {
                [lastupdaterecord setValue:systemcurrenttime forKey:parameter];
            }
        }
    }
    
    // Construct and execute the SQL update statement
    NSString *sql;
    if (centerkeyarray && centerkeyarray.count > 0) {
        NSString *formattedKeys = [NSString stringWithFormat:@"'%@'", [centerkeyarray componentsJoinedByString:@"','"]];
        sql = [NSString stringWithFormat:@"UPDATE lastupdate SET %@='%@' WHERE centerkey IN (%@)", parameter, systemcurrenttime, formattedKeys];
    } else {
        sql = [NSString stringWithFormat:@"UPDATE lastupdate SET %@='%@'", parameter, systemcurrenttime];
    }
    
    sqlite3_exec(globalvariables.isdb, [sql UTF8String], NULL, NULL, &err);
}


