+ (void)updatedevicelastupdatetimewithparameterarray:(NSArray *)parameterarray centerkeyarray:(NSArray *)centerkeyarray systemcurrenttime:(NSString *)systemcurrenttime {
    GlobalVariables *globalvariables = [GlobalVariables singleObj];
    char *err;
    
    if (!parameterarray || parameterarray.count == 0) {
        return;
    }
    
    // 1. Update the dictionary records for the specified center keys with existence check
    if (centerkeyarray && centerkeyarray.count > 0) {
        for (NSString *centerkey in centerkeyarray) {
            LastUpdateRecord *lastupdaterecord = globalvariables.lastupdatedict[centerkey];
            if (lastupdaterecord) {
                for (NSString *parameter in parameterarray) {
                    if (parameter.length > 0 && [lastupdaterecord respondsToSelector:NSSelectorFromString(parameter)]) {
                        [lastupdaterecord setValue:systemcurrenttime forKey:parameter];
                    }
                }
            }
        }
    } else {
        // Update all records in the dictionary if no array is provided
        for (LastUpdateRecord *lastupdaterecord in globalvariables.lastupdatedict.allValues) {
            for (NSString *parameter in parameterarray) {
                if (parameter.length > 0 && [lastupdaterecord respondsToSelector:NSSelectorFromString(parameter)]) {
                    [lastupdaterecord setValue:systemcurrenttime forKey:parameter];
                }
            }
        }
    }
    
    // 2. Build the SQL SET clause dynamically from the parameter array
    NSMutableString *setstring = [NSMutableString stringWithString:@"SET "];
    for (int i = 0; i < parameterarray.count; i++) {
        [setstring appendFormat:@"%@='%@'", parameterarray[i], systemcurrenttime];
        if (i < parameterarray.count - 1) {
            [setstring appendString:@", "];
        }
    }
    
    // 3. Construct and execute the SQL update statement
    NSString *sql;
    if (centerkeyarray && centerkeyarray.count > 0) {
        NSString *formattedKeys = [NSString stringWithFormat:@"'%@'", [centerkeyarray componentsJoinedByString:@"','"]];
        sql = [NSString stringWithFormat:@"UPDATE lastupdate %@ WHERE centerkey IN (%@)", setstring, formattedKeys];
    } else {
        sql = [NSString stringWithFormat:@"UPDATE lastupdate %@", setstring];
    }
    
    sqlite3_exec(globalvariables.isdb, [sql UTF8String], NULL, NULL, &err);
}


+(void) insertViewHistoryWithType:(NSString *)type Typekey:(NSString *)typekey Name:(NSString *)name IDNumber:(NSString *)ID Gender:(NSString *)gender
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    NSString *sql;
    //sqlite3 *isdb;
    char *err;
    
    /*
    if (sqlite3_open([[[NSSearchPathForDirectoriesInDomains(NSDocumentDirectory, NSUserDomainMask, YES) objectAtIndex:0] stringByAppendingPathComponent:@"isdb.sql"] UTF8String], &isdb)!=SQLITE_OK){
        sqlite3_close(isdb);
    }*/
    
    //delete old records
    sql=[NSString stringWithFormat:@"delete from viewhistory where centerkey='%@' and type='%@' and typekey='%@'",globalvariables.centerrecord.centerkey,type,typekey];
    sqlite3_exec(globalvariables.isdb,[sql UTF8String],NULL,NULL,&err);

    //add new records
    sql=[NSString stringWithFormat:@"INSERT INTO viewhistory ('centerkey','type','typekey','name','id','gender') VALUES ('%@','%@','%@','%@','%@','%@')",globalvariables.centerrecord.centerkey,type,typekey,name,ID,gender];
    sqlite3_exec(globalvariables.isdb,[sql UTF8String],NULL,NULL,&err);
    
    //limit total records to 10
    sql=[NSString stringWithFormat:@"DELETE FROM viewhistory  WHERE centerkey ='%@' and type='type' and viewhistorykey < (SELECT min(viewhistorykey) FROM (SELECT viewhistorykey FROM viewhistory where centerkey ='%@' and type='type' ORDER BY viewhistorykey DESC LIMIT 14)t)",globalvariables.centerrecord.centerkey,globalvariables.centerrecord.centerkey];
    sqlite3_exec(globalvariables.isdb,[sql UTF8String],NULL,NULL,&err);
    
}

