+(NSMutableArray *) returnViewHistoryWithType:(NSString *)type
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    NSMutableArray *resultarray=[[NSMutableArray alloc]init];
    
    NSString *sql;
    //sqlite3 *isdb;
    sqlite3_stmt *statement;
    
    /*
    if (sqlite3_open([[[NSSearchPathForDirectoriesInDomains(NSDocumentDirectory, NSUserDomainMask, YES) objectAtIndex:0] stringByAppendingPathComponent:@"isdb.sql"] UTF8String], &isdb)!=SQLITE_OK){
        sqlite3_close(isdb);
    }*/
    
    sql =[NSString stringWithFormat:@"SELECT typekey,name,id,gender FROM viewhistory where centerkey='%@' and type='%@' order by viewhistorykey desc",globalvariables.centerrecord.centerkey,type];
    
    if(sqlite3_prepare_v2(globalvariables.isdb, [sql UTF8String], -1, &statement, nil)==SQLITE_OK){
        while (sqlite3_step(statement)==SQLITE_ROW) {
            
            NSString *typekey=[[NSString alloc]initWithUTF8String:(char *)sqlite3_column_text(statement, 0)];
            NSString *name=[[NSString alloc]initWithUTF8String:(char *)sqlite3_column_text(statement, 1)];
            NSString *ID=[[NSString alloc]initWithUTF8String:(char *)sqlite3_column_text(statement, 2)];
            NSString *gender=[[NSString alloc]initWithUTF8String:(char *)sqlite3_column_text(statement, 3)];
            
            [resultarray addObject:[[ViewHistoryRecord alloc]initViewHistoryRecordwithTypekey:typekey Name:name ID:ID Gender:gender]];

        }
    }
    return resultarray;
}


