+(NSString *) returndateformatMMMM_yyyywithdate:(NSString *)MMMM_yyyydate
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    
    if ([globalvariables.language isEqualToString:@"English"]) {
        return MMMM_yyyydate;
    }else{
        df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];[df setDateFormat:@"MMMM yyyy"];
        NSDate *date=[df dateFromString:MMMM_yyyydate];
        
        if (date) {
            df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];[df setDateFormat:@"yyyy年M月"];
            return [df stringFromDate:date];
        }else{
            return [MyClass returntitlewithtitle:MMMM_yyyydate];
        }
    }
}

