+(void) removeImageFromCacheWithType:(NSString *)type TypeKey:(NSString *)typekey
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSString *cacheKeyToDelete;
    if ([type isEqualToString:@"student"]) {
        cacheKeyToDelete = [NSString stringWithFormat:@"%@studentimages/%@/student_%@_%@.jpg",globalvariables.serverpath,globalvariables.centerrecord.centerdb,globalvariables.centerrecord.centerkey, typekey];
    }else if ([type isEqualToString:@"lead"]){
        cacheKeyToDelete = [NSString stringWithFormat:@"%@leadimages/%@/lead_%@_%@.jpg",globalvariables.serverpath,globalvariables.centerrecord.centerdb,globalvariables.centerrecord.centerkey, typekey];
    }else if ([type isEqualToString:@"staff"]){
        cacheKeyToDelete = [NSString stringWithFormat:@"%@staffimages/%@/staff_%@_%@.jpg",globalvariables.serverpath,globalvariables.centerrecord.centerdb,globalvariables.centerrecord.centerkey, typekey];
    }else if ([type isEqualToString:@"centerimage"] || [type isEqualToString:@"launchimage"]){
        cacheKeyToDelete = [NSString stringWithFormat:@"%@centerimages/%@",globalvariables.serverpath,typekey];
    }else if ([type isEqualToString:@"class"]){
        cacheKeyToDelete = [NSString stringWithFormat:@"%@classimages/%@/%@",globalvariables.serverpath,globalvariables.centerrecord.centerdb,typekey];
    }else if ([type isEqualToString:@"message"]){
        cacheKeyToDelete = [NSString stringWithFormat:@"%@messageimages/%@/%@",globalvariables.serverpath,globalvariables.centerrecord.centerdb,typekey];
    }
    
    [[SDImageCache sharedImageCache] removeImageForKey:cacheKeyToDelete fromDisk:YES withCompletion:nil];
}


+(void) gotologinscreenwithpasswordresetted:(BOOL)passwordresetted
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    if (passwordresetted) {
        
        UIViewController *topController = [MyClass activeWindow].rootViewController;
        
        while (topController.presentedViewController) {
            topController = topController.presentedViewController;
        }
        
        if (![topController isKindOfClass:[UIAlertController class]]) {
            
            
            UIAlertController *alert = [UIAlertController alertControllerWithTitle:[MyClass returnlogintitlewithtitle:@"Center List"] message:[MyClass returnlogintitlewithtitle:@"No Center is available"] preferredStyle:UIAlertControllerStyleAlert];
            UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returnlogintitlewithtitle:@"OK"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                
                
                NSString *sql;
                
                
                [MyClass updatelocaldbwithparameter:@"password" value:@""];
                [MyClass updatelocaldbwithparameter:@"centerkey" value:@""];
                
                sql=[NSString stringWithFormat:@"DROP TABLE IF EXISTS lastupdate;"];
                sqlite3_exec(globalvariables.isdb, [sql UTF8String],NULL,NULL,NULL);
                
                sql=[NSString stringWithFormat:@"DROP TABLE IF EXISTS schoolcalendar;"];
                sqlite3_exec(globalvariables.isdb, [sql UTF8String],NULL,NULL,NULL);
                [globalvariables.centerdaydictionary removeAllObjects];
                
                sql=[NSString stringWithFormat:@"DROP TABLE IF EXISTS languagetitle;"];
                sqlite3_exec(globalvariables.isdb, [sql UTF8String],NULL,NULL,NULL);
                [globalvariables.languagetitledictionary removeAllObjects];
                
                sql=[NSString stringWithFormat:@"DROP TABLE IF EXISTS student;"];
                sqlite3_exec(globalvariables.isdb, [sql UTF8String],NULL,NULL,NULL);
                
                sql=[NSString stringWithFormat:@"DROP TABLE IF EXISTS contact;"];
                sqlite3_exec(globalvariables.isdb, [sql UTF8String],NULL,NULL,NULL);
                
                sql=[NSString stringWithFormat:@"DROP TABLE IF EXISTS sibling;"];
                sqlite3_exec(globalvariables.isdb, [sql UTF8String],NULL,NULL,NULL);
                
                sql=[NSString stringWithFormat:@"DROP TABLE IF EXISTS lead;"];
