+(BOOL) checkiflatestversion
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    int currentVersion = [[[[NSBundle mainBundle] infoDictionary] objectForKey:@"CFBundleVersion"] intValue];
    int latestVersion =[globalvariables.globalsettings.latestappversion intValue];
    if (currentVersion < latestVersion) {
        globalvariables.username=@"";
        globalvariables.password=@"";
        return FALSE;
    } else {
        // Version is equal
        return TRUE;
    }
}

