    }
    
    return tmpsortingarray;
}

+(NSMutableArray *) sortstudentlistwithstudentarray:(NSMutableArray *)student_array sortingarray:(NSMutableArray *)sorting_array
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    if (!sorting_array) {
        sorting_array=[self returnsortingarraywithtype:@"studentlistsortingorder"];
    }
    
    NSSortDescriptor *sortdescriptor=[[NSSortDescriptor alloc]init];
    NSMutableArray *sortDescriptorsArray=[[NSMutableArray alloc]init];
    SortingRecord *sortingobject;
    
    NSString *sortitem;
    NSString *sortenable;
    for (int i=0; i<sorting_array.count; i++) {
        sortingobject=[sorting_array objectAtIndex:i];
        if ([sortingobject.item isEqualToString:@"sorting_name"]) {
            for (int i=0; i<globalvariables.centerrecord.studentnamedisplayorder.count; i++) {
                
                sortitem=[[globalvariables.centerrecord.studentnamedisplayorder objectAtIndex:i] substringFromIndex:2];
                sortenable=[[globalvariables.centerrecord.studentnamedisplayorder objectAtIndex:i] substringToIndex:1];
                
                if ([sortenable isEqualToString:@"e"]) {
                    sortdescriptor=[[NSSortDescriptor alloc]initWithKey:sortitem ascending:[sortingobject.order isEqualToString:@"a"]?YES:NO selector:@selector(localizedCaseInsensitiveCompare:)];
                    [sortDescriptorsArray addObject:sortdescriptor];
                }
            }
        }else{
//            sortdescriptor=[[NSSortDescriptor alloc]initWithKey:@"studentid" ascending:[sortingobject.order isEqualToString:@"a"]?YES:NO selector:@selector(localizedCaseInsensitiveCompare:)];
            
            sortdescriptor = [NSSortDescriptor sortDescriptorWithKey:@"studentid" ascending:[sortingobject.order isEqualToString:@"a"]?YES:NO comparator:^NSComparisonResult(id obj1, id obj2) {
                return [[(NSString *)obj1 lowercaseString] compare:[(NSString *)obj2 lowercaseString] options:NSNumericSearch];
            }];
            
            
            [sortDescriptorsArray addObject:sortdescriptor];
        }
    }
    
    return [NSMutableArray arrayWithArray:[student_array sortedArrayUsingDescriptors:sortDescriptorsArray]];
}

