+(NSString *) convertDDMMMYYYYtoDDMMMwithdate:(NSString *)datestring
{
    if ([datestring isEqualToString:@""] || !datestring) {
        return @"";
    }else{
        NSDateFormatter *df=[[NSDateFormatter alloc]init]; df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
        [df setDateFormat:@"dd-MMM-yyyy"];
        NSDate *date=[df dateFromString:datestring];
        [df setDateFormat:@"dd MMM"];
        return [df stringFromDate:date]?[df stringFromDate:date]:datestring;
    }
}

+(NSString *) returndateformatwiththisyearfromDDMMMYYYY:(NSString *)ddmmmyyyy
{
    if ([ddmmmyyyy length]!=11) {
        return [self returntitlewithtitle:ddmmmyyyy];
    }else{
        GlobalVariables *globalvariables=[GlobalVariables singleObj];
        NSDateFormatter *df=[[NSDateFormatter alloc]init];
        df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
        NSDate *date=[self convertToNSDateWithDate:ddmmmyyyy DateFormat:@"dd-MMM-yyyy"];
        if (![self isDateFallsThisYear:date]) {
            if ([globalvariables.language isEqualToString:@"English"]) {
                [df setDateFormat:@"dd-MMM-yy"];
                return [df stringFromDate:date];
            }else{
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
                [df setDateFormat:@"yy年M月d日"];
                return [df stringFromDate:date];
            }
        }else{
            if ([globalvariables.language isEqualToString:@"English"]) {
                [df setDateFormat:@"dd-MMM"];
                return [df stringFromDate:date];
            }else{
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
                [df setDateFormat:@"M月d日"];
                return [df stringFromDate:date];
            }
        }
    }
}

+(BOOL) isMessageSentWithMessageSentTime:(NSString *)messagestarttime
{
    NSDateFormatter *df=[[NSDateFormatter alloc]init]; df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    [df setDateFormat:@"yyyy-MM-dd HH:mm:ss"];
    if ([[df dateFromString:messagestarttime] compare:[NSDate date]]==NSOrderedAscending) {
        return TRUE;
    }else{
        return FALSE;
    }
}

