+(void) loadingindicatorwithoption:(NSString *)option color:(NSString *)color
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    dispatch_async(dispatch_get_main_queue(), ^{
    UIActivityIndicatorView *aiLoadingIndicator=(UIActivityIndicatorView *)[globalvariables.loadingindicatorview viewWithTag:1024];
    UIImageView *activityImageView=(UIImageView *)[globalvariables.loadingindicatorview viewWithTag:808];
    
    

    if ([option isEqualToString:@"start"]) {
//        UIWindow *mainWindow= [[[UIApplication sharedApplication] delegate] window];
        
        SceneDelegate *sceneDelegate = (SceneDelegate *)[UIApplication sharedApplication].connectedScenes.anyObject.delegate;
        UIWindow *mainWindow = sceneDelegate.window;
        UIView *overlay = globalvariables.loadingindicatorview;
        overlay.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleHeight;
        if (overlay.superview != mainWindow) {
            [mainWindow addSubview:overlay];
        }
        overlay.frame = mainWindow.bounds;
        UIView *centerview = [overlay viewWithTag:809];
        if (centerview) {
            centerview.autoresizingMask = UIViewAutoresizingFlexibleLeftMargin | UIViewAutoresizingFlexibleRightMargin | UIViewAutoresizingFlexibleTopMargin | UIViewAutoresizingFlexibleBottomMargin;
            centerview.center = CGPointMake(CGRectGetMidX(overlay.bounds), CGRectGetMidY(overlay.bounds));
        }
        [mainWindow bringSubviewToFront:overlay];
        activityImageView.animationImages=[MyClass returnLoadingIndicatorAnimatedImageWithBaseColor:color];
        activityImageView.animationDuration=2;
        [activityImageView startAnimating];
        
//        [mainWindow.rootViewController.view layoutIfNeeded];
        
//
//        CGFloat width = [UIScreen mainScreen].bounds.size.width;
//        CGFloat height = [UIScreen mainScreen].bounds.size.height;
//        [globalvariables.loadingindicatorview setFrame:CGRectMake(0, 0, width, height)];
        
        
        globalvariables.loadingindicatorview.hidden=NO;
        [aiLoadingIndicator startAnimating];
    }else{
        globalvariables.loadingindicatorview.hidden=YES;
        [activityImageView stopAnimating];
        [aiLoadingIndicator stopAnimating];
    }
    });
}

+(BOOL)isDateFallsThisYear:(NSDate *)calendardate
{
    if (calendardate) {
        NSCalendar *gregorian = [[NSCalendar alloc] initWithCalendarIdentifier:NSCalendarIdentifierGregorian];
        NSDateComponents *dateComponents = [gregorian components:NSCalendarUnitYear fromDate:calendardate];
        NSDateComponents *todayComponents = [gregorian components:NSCalendarUnitYear fromDate:[NSDate date]];
        if(dateComponents.year == todayComponents.year){
            return YES;
        }
    }else{
        return YES;
    }
    
    return NO;
    
}

