+ (NSInteger)daysBetweenFromDate:(NSDate*)fromDateTime toDate:(NSDate*)toDateTime
{
    NSDate *fromDate;
    NSDate *toDate;
    
    //initialize the calendar
    NSCalendar *calendar = [NSCalendar currentCalendar];
    
    //Returns by reference the starting time and duration of a given calendar unit that contains a given date.
    [calendar rangeOfUnit:NSCalendarUnitDay startDate:&fromDate interval:NULL forDate:fromDateTime];
    [calendar rangeOfUnit:NSCalendarUnitDay startDate:&toDate interval:NULL forDate:toDateTime];
    
    //Returns, as an NSDateComponents object using specified components, the difference between two supplied dates.
    NSDateComponents *difference = [calendar components:NSCalendarUnitDay fromDate:fromDate toDate:toDate options:0];
    
    return [difference day];
}

+(NSMutableArray *) retrieveschoollist
{
    
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSMutableArray *schoolarray=[[NSMutableArray alloc] init];
    
    NSString *sql =[NSString stringWithFormat:@"select distinct school from (select school, centerkey from student union select school, centerkey from lead)a where school <>'' and centerkey='%@' order by school",globalvariables.centerrecord.centerkey];
    sqlite3_stmt *statement;
    
    //fill in date picker menu
    if(sqlite3_prepare_v2(globalvariables.isdb, [sql UTF8String], -1, &statement, nil)==SQLITE_OK){
        while (sqlite3_step(statement)==SQLITE_ROW) {
            
            char *field1 =(char *)sqlite3_column_text(statement, 0);
            NSString *field1str=[[NSString alloc]initWithUTF8String:field1];
            [schoolarray addObject:field1str];
            
        }
    }
    
    return schoolarray;
}

+ (NSString *) findNextWorkDay2:(NSDate *)currentdate includereserveddate:(BOOL)includereserveddate
{
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    [df setDateFormat:@"dd-MMM-yyyy"];
    
    NSDateComponents *dayComponent = [[NSDateComponents alloc] init];
    NSDate *nextworkday;
    
    for (int i=1; i<10000; i++) {
        dayComponent.day = i;
        
        NSCalendar *theCalendar = [NSCalendar currentCalendar];
        
        nextworkday=[theCalendar dateByAddingComponents:dayComponent toDate:currentdate options:0];
        
        if ([MyClass isWorkingDate:nextworkday includereserveddate:includereserveddate]) {
            break;
        }
    }
    
    return [df stringFromDate:nextworkday];
    
}

+ (NSString *) findNextWorkDay:(NSDate *)currentdate dayofWeek:(NSString *)dayofweek includereserveddate:(BOOL)includereserveddate
{
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    [df setDateFormat:@"dd-MMM-yyyy"];
    
    NSDateComponents *dayComponent = [[NSDateComponents alloc] init];
    NSDate *nextworkday;
    
    for (int i=0; i<10000; i++) {
        dayComponent.day = i;
        
        NSCalendar *theCalendar = [NSCalendar currentCalendar];
        
        nextworkday=[theCalendar dateByAddingComponents:dayComponent toDate:currentdate options:0];
        
        if ([MyClass isWorkingDate:nextworkday includereserveddate:includereserveddate]) {
            if([[MyClass convertToNSStringWithNSDate:nextworkday DateFormat:@"EEE"] isEqualToString:dayofweek]){
                break;
            }
        }
    }
    
    return [df stringFromDate:nextworkday];
    
}

+(NSDate *) addDaysWithDate:(NSDate *)date days:(NSInteger)days
{
    NSDateComponents *dayComponent = [[NSDateComponents alloc] init];
    dayComponent.day = days;
    NSCalendar *theCalendar = [NSCalendar currentCalendar];
    return [theCalendar dateByAddingComponents:dayComponent toDate:date options:0];
}

+(BOOL) isWorkingDate:(NSDate *)date includereserveddate:(BOOL)includereservedate
{
    if (date) {
        GlobalVariables *globalvariables=[GlobalVariables singleObj];
        NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
        [df setDateFormat:@"yyyy-MM-dd"];
        NSString *datestring=[df stringFromDate:date];
        
        NSString *centerday=[globalvariables.centerdaydictionary objectForKey:[NSString stringWithFormat:@"%@#%@",datestring,globalvariables.centerrecord.centerkey]];
        if (!centerday || ([centerday isEqualToString:@"R"] && (includereservedate || globalvariables.centerrecord.usereserveddayduringenrollment))) {
            return YES;
        }
    }
    return NO;
    
}

+(NSString *) returnDateFromBaseDateWithOffset:(long)offset
{
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    NSDateComponents *dayComponent = [[NSDateComponents alloc] init];
    dayComponent.day = offset;
    
    [df setDateFormat:@"dd-MMM-yyyy"];
    NSCalendar *theCalendar = [NSCalendar currentCalendar];
    return [df stringFromDate:[theCalendar dateByAddingComponents:dayComponent toDate:[df dateFromString:[self returnNewBaseDate]] options:0]];
}

