+(NSInteger) returnDateOffsetWithDate:(NSDate *)toDate
{
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    [df setDateFormat:@"dd-MMM-yyyy"];
    NSDate *fromDate;
    
    NSCalendar *calendar = [NSCalendar currentCalendar];
    
    [calendar rangeOfUnit:NSCalendarUnitDay startDate:&fromDate interval:NULL forDate:[df dateFromString:[self returnNewBaseDate]]];
    
    NSDateComponents *difference = [calendar components:NSCalendarUnitDay fromDate:fromDate toDate:toDate options:0];
    
    return [difference day];
}

+(NSInteger) returnMonthOffsetWithDate:(NSDate *)toDate
{
    if (toDate) {
        NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
        [df setDateFormat:@"dd-MMM-yyyy"];
        NSDate *fromDate;
        
        NSCalendar *calendar = [NSCalendar currentCalendar];
        
        [calendar rangeOfUnit:NSCalendarUnitDay startDate:&fromDate interval:NULL forDate:[df dateFromString:[self returnNewBaseDate]]];
        
        NSDateComponents *difference = [calendar components:NSCalendarUnitMonth fromDate:fromDate toDate:toDate options:0];
        
        return [difference month];
    }
    return 0;

}

+(NSDate *) convertToNSDateWithDate:(NSString *)date DateFormat:(NSString *)dateformat
{
    if(![date isEqual:[NSNull null]]){
        NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
        [df setDateFormat:dateformat];
        return [df dateFromString:date];
    }else{
        return nil;
    }

}

+(NSString *) convertToNSStringWithNSDate:(NSDate *)date DateFormat:(NSString *)dateformat
{
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    [df setDateFormat:dateformat];
    return [df stringFromDate:date];
}

+(NSString *) convertDateFormatWithDate:(NSString *)date FromDateFormat:(NSString *)fromdateformat ToDateFormat:(NSString *)todateformat
{
    if ([date isEqualToString:@""] || !date) {
        return @"";
    }else{
        NSDateFormatter *df=[[NSDateFormatter alloc]init];
        df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
        [df setDateFormat:fromdateformat];
        NSDate *nsdate=[df dateFromString:date];
        if (nsdate) {
            [df setDateFormat:todateformat];
            return [df stringFromDate:nsdate];
        }else{
            return date;
        }
    }
}

+(NSString *) convertDateFormatWithDate:(NSString *)date FromDateFormat:(NSString *)fromdateformat ToDateFormat:(NSString *)todateformat Translate:(BOOL)translate
{
    if (!date || [date isEqualToString:@""]) {
        return @"";
    }else{
        GlobalVariables *globalvariables=[GlobalVariables singleObj];
        NSDateFormatter *df=[[NSDateFormatter alloc]init];
        df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
        [df setDateFormat:fromdateformat];
        NSDate *nsdate=[df dateFromString:date];
        
        if (nsdate) {
            if (!translate || [globalvariables.language isEqualToString:@"English"]) {
                [df setDateFormat:todateformat];
                return [df stringFromDate:nsdate];
            }else{
                df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];
                
                if ([todateformat isEqualToString:@"EEE"]) {
                    [df setDateFormat:@"EE"];
                }else if ([todateformat isEqualToString:@"dd-MMM-yyyy"]){
                    [df setDateFormat:@"yyyy年M月d日"];
                }else if ([todateformat isEqualToString:@"dd MMM"]){
                    [df setDateFormat:@"M月d日"];
                }else if ([todateformat isEqualToString:@"dd-MMM"]){
                    [df setDateFormat:@"M月d日"];
                }else if ([todateformat isEqualToString:@"dd-MMMM"]){
                    [df setDateFormat:@"M月d日"];
                }else if ([todateformat isEqualToString:@"MMMM yyyy"]){
                    [df setDateFormat:@"yyyy年M月"];
                }else if ([todateformat isEqualToString:@"dd-MMM-yyyy HH:mm"]){
                    [df setDateFormat:@"yyyy年M月d日 HH:mm"];
                }else if ([todateformat isEqualToString:@"dd-MMM-yyyy HH:mm:ss"]){
                    [df setDateFormat:@"yyyy年M月d日 HH:mm:ss"];
                }else if ([todateformat isEqualToString:@"EEEE, d MMMM yyyy"]){
                    [df setDateFormat:@"yyyy年M月d日, EEEE"];
                }else if ([todateformat isEqualToString:@"dd MMM HH:mm"]){
                    [df setDateFormat:@"M月d日 HH:mm"];
                }else if ([todateformat isEqualToString:@"d MMM HH:mm"]){
                    [df setDateFormat:@"M月d日 HH:mm"];
                }else if ([todateformat isEqualToString:@"MMMM"]){
                    [df setDateFormat:@"M月"];
                }else if ([todateformat isEqualToString:@"EEE"]){
                    [df setDateFormat:@"EE"];
                }else if ([todateformat isEqualToString:@"dd-MMM HH:mm (EEE)"]){
                    [df setDateFormat:@"M月d日 HH:mm (EE)"];
                }else if ([todateformat isEqualToString:@"EEE2"]) {
                    [df setDateFormat:@"EEE"];
                    return [[df stringFromDate:nsdate] substringFromIndex:1];
                }else if ([todateformat isEqualToString:@"EEE dd-MMM-yyyy"]){
                    [df setDateFormat:@"yyyy年M月d日 EE"];
                }else if ([todateformat isEqualToString:@"dd-MMM-yyyy (EEE)"]){
                    [df setDateFormat:@"yyyy年M月d日 (EE)"];
                }else if ([todateformat isEqualToString:@"dd"]){
                    [df setDateFormat:@"d日"];
                }
                return [df stringFromDate:nsdate];
            }
        }else{
            return date;
        }
    }
}

+(NSString *) convertToNSStringWithNSDate:(NSDate *)date ToDateFormat:(NSString *)todateformat Language:(NSString *)language
{
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    
    if ([language isEqualToString:@"English"]) {
        [df setDateFormat:todateformat];
        return [df stringFromDate:date];
    }else{
        df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];
        
        if ([todateformat isEqualToString:@"EEE"]) {
            [df setDateFormat:@"EE"];
        }else if ([todateformat isEqualToString:@"dd-MMM-yyyy"]){
            [df setDateFormat:@"yyyy年M月d日"];
        }else if ([todateformat isEqualToString:@"dd MMM"]){
            [df setDateFormat:@"M月d日"];
        }else if ([todateformat isEqualToString:@"dd-MMM"]){
            [df setDateFormat:@"M月d日"];
        }else if ([todateformat isEqualToString:@"MMMM yyyy"]){
            [df setDateFormat:@"yyyy年M月"];
        }else if ([todateformat isEqualToString:@"dd-MMM-yyyy HH:mm"]){
            [df setDateFormat:@"yyyy年M月d日 HH:mm"];
        }else if ([todateformat isEqualToString:@"dd-MMM-yyyy HH:mm:ss"]){
            [df setDateFormat:@"yyyy年M月d日 HH:mm:ss"];
        }else if ([todateformat isEqualToString:@"EEEE, d MMMM yyyy"]){
            [df setDateFormat:@"yyyy年M月d日, EEEE"];
        }else if ([todateformat isEqualToString:@"dd MMM HH:mm"]){
            [df setDateFormat:@"M月d日 HH:mm"];
        }else if ([todateformat isEqualToString:@"MMMM"]){
            [df setDateFormat:@"M月"];
        }else if ([todateformat isEqualToString:@"dd-MMM HH:mm (EEE)"]){
            [df setDateFormat:@"M月d日 HH:mm (EE)"];
        }else if ([todateformat isEqualToString:@"EEE2"]) {
            [df setDateFormat:@"EEE"];
            return [[df stringFromDate:date] substringFromIndex:1];
        }
        return [df stringFromDate:date];
    }
    
    
}

+(BOOL) schedulecontainscelldatetimewithdate:(NSDate *)date time:(NSString *)time schedulerecord:(ScheduleRecord *)schedulerecord
{
    NSArray *allweekarray=[MyClass returnschedulearraywithschedulerecord:schedulerecord];
    NSDateFormatter *df=[[NSDateFormatter alloc]init];df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    
    [df setDateFormat:@"dd-MMM-yyyy"];
    
    long weeknumber=[MyClass returndayofweeknumber:[MyClass returndayofweek:[df stringFromDate:date]]]-1;
    
    if ([time isEqualToString:@"Any"]) {
        if (((NSMutableArray *)[allweekarray objectAtIndex:weeknumber]).count>0) {
            return YES;
        }
    }else{
        for (int j=0; j<((NSMutableArray *)[allweekarray objectAtIndex:weeknumber]).count; j++) {
            if ([[((NSMutableArray *)[allweekarray objectAtIndex:weeknumber]) objectAtIndex:j] isEqualToString:time]) {
                return YES;
            }
        }
    }
    
    return NO;
}

