+(void) reloadTableWithTableview:(UITableView *)tableview ExceptIndexPath:(NSIndexPath *)indexpath
{
    NSIndexPath *indexpathobject;
    NSMutableArray *visibleIndexPaths = [[NSMutableArray alloc]initWithArray:[tableview indexPathsForVisibleRows]];
    for (int i=0; i<visibleIndexPaths.count; i++) {
        indexpathobject=[visibleIndexPaths objectAtIndex:i];
        if (indexpathobject.row==indexpath.row && indexpathobject.section==indexpath.section) {
            [visibleIndexPaths removeObjectAtIndex:i];
            break;
        }
    }
    
    [tableview reloadRowsAtIndexPaths:visibleIndexPaths withRowAnimation:UITableViewRowAnimationNone];
    
}

+(NSMutableArray *) returnStaffGroupArrayIncludeAll:(BOOL)includeall
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    NSMutableArray *staffgrouparray=[[NSMutableArray alloc]init];
    
    NSString *strURL=[NSString stringWithFormat:@"%@?centerdb=%@&centerkey=%@&action=retrievegrouplist",globalvariables.generalphpfullpath,globalvariables.centerrecord.centerdb,globalvariables.centerrecord.centerkey];
    
//    __block BOOL result=FALSE;
    [MyClass callGETwithURL:strURL completionBlock:^(BOOL succeeded, NSData *data) {
        if (succeeded) {
            NSDictionary *jsonreturned=[NSJSONSerialization JSONObjectWithData:data options:(kNilOptions) error:nil];
            NSMutableArray *JSONArray = jsonreturned[@"content"];
            //loop through our jsonArray
            for (int i=0; i<JSONArray.count; i++) {
                //Create our ClassRecord object
                NSString * groupkey=[[JSONArray objectAtIndex:i] objectForKey:@"groupkey"];
                NSString * groupname=[[JSONArray objectAtIndex:i] objectForKey:@"groupname"];
                NSString * description=[[JSONArray objectAtIndex:i] objectForKey:@"description"];
                BOOL makeuparrangementnotification=[[[JSONArray objectAtIndex:i] objectForKey:@"makeuparrangementnotification"] isEqualToString:@"Yes"];
                BOOL autorenewalfailurenotification=[[[JSONArray objectAtIndex:i] objectForKey:@"autorenewalfailurenotification"] isEqualToString:@"Yes"];
                BOOL onlineenrollmentnotification=[[[JSONArray objectAtIndex:i] objectForKey:@"onlineenrollmentnotification"] isEqualToString:@"Yes"];
                BOOL onlinepaymentnotification=[[[JSONArray objectAtIndex:i] objectForKey:@"onlinepaymentnotification"] isEqualToString:@"Yes"];
                
                if ([groupname isEqualToString:@"All"]) {
                    if (includeall) {
                        [staffgrouparray addObject:[[GroupRecord alloc]initGroupRecordwithgroupkey:groupkey groupname:groupname description:description makeuparrangementnotification:makeuparrangementnotification autorenewalfailurenotification:autorenewalfailurenotification onlineenrollmentnotification:onlineenrollmentnotification onlinepaymentnotification:onlinepaymentnotification]];
                    }
                }else{
                    [staffgrouparray addObject:[[GroupRecord alloc]initGroupRecordwithgroupkey:groupkey groupname:groupname description:description makeuparrangementnotification:makeuparrangementnotification autorenewalfailurenotification:autorenewalfailurenotification onlineenrollmentnotification:onlineenrollmentnotification onlinepaymentnotification:onlinepaymentnotification]];
                }
            }
        }
    }];
    
    return staffgrouparray;
}

