+(void) playsoundwithoption:(NSString *)option
{
    if ([[MyClass getlocaldbwithparameter:@"sound"] isEqualToString:@"Yes"]) {
        GlobalVariables *globalvariables=[GlobalVariables singleObj];
        if ([option isEqualToString:@"open"]) {
            NSString *path=[[NSBundle mainBundle] pathForResource:@"open" ofType:@"mp3"];
            globalvariables.audioplayer=[[AVAudioPlayer alloc]initWithContentsOfURL:[NSURL fileURLWithPath:path] error:NULL];
        }else{
            NSString *path=[[NSBundle mainBundle] pathForResource:@"close" ofType:@"mp3"];
            globalvariables.audioplayer=[[AVAudioPlayer alloc]initWithContentsOfURL:[NSURL fileURLWithPath:path] error:NULL];
        }
        globalvariables.audioplayer.volume=0.2;
        [globalvariables.audioplayer play];
    }
}

