+(NSMutableArray *) returnsortedstaffusernamewithstaffusernamearray:(NSMutableArray *)staffusernamearray
{
    NSMutableArray *staffarray=[[NSMutableArray alloc]init];
    BOOL addTBD=FALSE;
    for (int i=0; i<staffusernamearray.count; i++) {
        if ([[staffusernamearray objectAtIndex:i] isEqualToString:@"TBD"]) {
            addTBD=TRUE;
        }else{
            //[staffarray addObject:[MyClass returnstaffrecordwithusername:[staffusernamearray objectAtIndex:i]]];
            Staff *record=[MyClass returnstaffrecordwithusername:[staffusernamearray objectAtIndex:i]];
            if (record) {
                [staffarray addObject:[MyClass returnstaffrecordwithusername:[staffusernamearray objectAtIndex:i]]];
            }
        }
    }
    
    //sort name
    NSSortDescriptor *sortByFirstname = [NSSortDescriptor sortDescriptorWithKey:@"firstname" ascending:YES selector:@selector(localizedStandardCompare:)];
    NSSortDescriptor *sortByLastname = [NSSortDescriptor sortDescriptorWithKey:@"lastname" ascending:YES selector:@selector(localizedStandardCompare:)];
    NSArray *sortDescriptors = @[sortByFirstname,sortByLastname];
    staffarray = [NSMutableArray arrayWithArray:[staffarray sortedArrayUsingDescriptors:sortDescriptors]];
    
    staffusernamearray=[[NSMutableArray alloc]init];
    for (int i=0; i<staffarray.count; i++) {
        [staffusernamearray addObject:((Staff *)[staffarray objectAtIndex:i]).username];
    }
    
    if (addTBD) {
        [staffusernamearray addObject:@"TBD"];
    }
    
    return staffusernamearray;
    
}

