+(NSMutableArray *) returnsortedsubjectorcategorylistwithsubjectorcategoryarray:(NSMutableArray *)subjectorcategoryarray
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSMutableArray *sortedarray=[[NSMutableArray alloc]init];
    NSMutableArray *tmparray=[[NSMutableArray alloc]init];
    NSMutableDictionary *tmpdict;
    NSMutableDictionary *subjectdict;
    for (int i=0; i<subjectorcategoryarray.count; i++) {
        subjectdict=[subjectorcategoryarray objectAtIndex:i];
        tmpdict=[[NSMutableDictionary alloc]init];
        [tmpdict setValue:[subjectdict valueForKey:@"subjecttype"] forKey:@"subjecttype"];
        [tmpdict setValue:[subjectdict valueForKey:@"subject"] forKey:@"subject"];
        
        
        if ([[subjectdict valueForKey:@"subjecttype"] isEqualToString:@"subject"]){
            SubjectRecord *object=[MyClass returnsubjectinformationwithsubject_shortname:[subjectdict valueForKey:@"subject"] centerkey:globalvariables.centerrecord.centerkey];
            [tmpdict setValue:[globalvariables.language isEqualToString:@"English"]?object.subject_englishname:object.subject_chinesename forKey:@"name"];
        }else{
            SubjectCategoryRecord *object=[MyClass returnsubjectcategorywithscategorykey:[subjectdict valueForKey:@"subject"]];
            [tmpdict setValue:[globalvariables.language isEqualToString:@"English"]?object.englishname:object.chinesename forKey:@"name"];
        }
        [tmparray addObject:tmpdict];
    }
    
    //sort name
    NSSortDescriptor *sortByName = [NSSortDescriptor sortDescriptorWithKey:@"name" ascending:YES selector:@selector(localizedStandardCompare:)];
    NSArray *sortdescriptors = @[sortByName];
    tmparray = [NSMutableArray arrayWithArray:[tmparray sortedArrayUsingDescriptors:sortdescriptors]];
    
    
    for (int i=0; i<tmparray.count; i++) {
        tmpdict=[tmparray objectAtIndex:i];
        [tmpdict removeObjectForKey:@"name"];
        [sortedarray addObject:tmpdict];
    }
    
    return sortedarray;
    
}

+(NSMutableArray *) returnsortedsubjectorcategorylistwithsubjectorcategorycodearray:(NSMutableArray *)subjectcodearray
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSMutableArray *subjectarray=[[NSMutableArray alloc]init];
    NSMutableDictionary *dict;
    for (int i=0; i<subjectcodearray.count; i++) {
        SubjectRecord *object=[MyClass returnsubjectinformationwithsubject_shortname:[subjectcodearray objectAtIndex:i] centerkey:globalvariables.centerrecord.centerkey];
        if(object){
            dict=[[NSMutableDictionary alloc]init];
            [dict setValue:[subjectcodearray objectAtIndex:i] forKey:@"code"];
            [dict setValue:[MyClass returnsubjectnamewithsubject_shortname:[subjectcodearray objectAtIndex:i] centerkey:globalvariables.centerrecord.centerkey] forKey:@"name"];
            [subjectarray addObject:dict];
        }else{
            SubjectCategoryRecord *object=[MyClass returnsubjectcategorywithscategorykey:[subjectcodearray objectAtIndex:i]];
            if(object){
                dict=[[NSMutableDictionary alloc]init];
                [dict setValue:[subjectcodearray objectAtIndex:i] forKey:@"code"];
                [dict setValue:[MyClass returnsubjectcategorynamewithscategorykey:[subjectcodearray objectAtIndex:i]] forKey:@"name"];
                [subjectarray addObject:dict];
            }else{
                dict=[[NSMutableDictionary alloc]init];
                [dict setValue:[subjectcodearray objectAtIndex:i] forKey:@"code"];
                [dict setValue:[subjectcodearray objectAtIndex:i] forKey:@"name"];
                [subjectarray addObject:dict];
            }
        }
    }
    
    //sort name
    NSSortDescriptor *sortBySubjectname = [NSSortDescriptor sortDescriptorWithKey:@"name" ascending:YES selector:@selector(localizedStandardCompare:)];
    
    NSArray *sortdescriptors = @[sortBySubjectname];
    subjectarray = [NSMutableArray arrayWithArray:[subjectarray sortedArrayUsingDescriptors:sortdescriptors]];
    
    
    subjectcodearray=[[NSMutableArray alloc]init];
    for (int i=0; i<subjectarray.count; i++) {
        [subjectcodearray addObject:[[subjectarray objectAtIndex:i] valueForKey:@"code"]];
    }
    
    return subjectcodearray;
    
}

+(void) removeallsidewindowsexceptsidewindow:(UIView *)window sidewindowbutton:(UIButton *)button
{
    UIWindow *mainWindow= [[[UIApplication sharedApplication] delegate] window];
    
    for (id object in [mainWindow subviews]) {
        if (((UIView *)object).tag ==-200 || ((UIButton *)object).tag==-200) {
            if (object!=window && object!=button) {
                [object removeFromSuperview];
            }
        }
    }
}

+(NSString *) returndateformatwithdate:(NSString *)datestring dateformat:(NSString *)dateformat
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    NSDateFormatter *df=[[NSDateFormatter alloc]init];
    df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];
    
    
    if ([globalvariables.language isEqualToString:@"English"]) {
        return datestring;
    }else{
        [df setDateFormat:dateformat];
        NSDate *date=[df dateFromString:datestring];
        df.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];
        if (date) {
            if ([dateformat isEqualToString:@"EEE"]) {
                [df setDateFormat:@"EE"];
            }else if ([dateformat isEqualToString:@"dd-MMM-yyyy"]){
                [df setDateFormat:@"yyyy年M月d日"];
            }else if ([dateformat isEqualToString:@"dd MMM"]){
                [df setDateFormat:@"M月d日"];
            }else if ([dateformat isEqualToString:@"dd-MMM"]){
                [df setDateFormat:@"M月d日"];
            }else if ([dateformat isEqualToString:@"End MMMM yyyy"]){
                [df setDateFormat:@"yyyy年M月底"];
            }else if ([dateformat isEqualToString:@"dd-MMM-yyyy HH:mm"]){
                [df setDateFormat:@"yyyy年M月d日 HH:mm"];
            }else if ([dateformat isEqualToString:@"dd-MMM-yyyy HH:mm:ss"]){
                [df setDateFormat:@"yyyy年M月d日 HH:mm:ss"];
            }else if ([dateformat isEqualToString:@"EEEE, d MMMM yyyy"]){
                [df setDateFormat:@"yyyy年M月d日, EEEE"];
            }else if ([dateformat isEqualToString:@"dd MMM HH:mm"]){
                [df setDateFormat:@"M月d日 HH:mm"];
            }else if ([dateformat isEqualToString:@"MMMM"]){
                [df setDateFormat:@"M月"];
            }else if ([dateformat isEqualToString:@"EEE"]){
                [df setDateFormat:@"EE"];
            }else if ([dateformat isEqualToString:@"dd-MMM HH:mm (EEE)"]){
                [df setDateFormat:@"M月d日 HH:mm (EE)"];
            }else if ([dateformat isEqualToString:@"EEE2"]) {
                [df setDateFormat:@"EEE"];
                return [[df stringFromDate:date] substringFromIndex:1];
            }
            return [df stringFromDate:date];
        }
    }
    return [MyClass returntitlewithtitle:datestring];
}

