+(BOOL) isImageInCacheWithType:(NSString *)type TypeKey:(NSString *)typekey
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSString *cacheKeyToCheck;
    if ([type isEqualToString:@"student"]) {
        Student *studentobject=[MyClass returnstudentwithstudentkey:typekey];
        cacheKeyToCheck = [NSString stringWithFormat:@"%@studentimages/%@/%@",globalvariables.serverpath,globalvariables.centerrecord.centerdb,studentobject.avatar];
    }else if ([type isEqualToString:@"lead"]){
        Lead *leadobject=[MyClass returnleadwithleadkey:typekey];
        cacheKeyToCheck = [NSString stringWithFormat:@"%@leadimages/%@/%@",globalvariables.serverpath,globalvariables.centerrecord.centerdb,leadobject.avatar];
    }else if ([type isEqualToString:@"staff"]){
        Staff *staffobject=[MyClass returnstaffrecordwithusername:typekey];
        cacheKeyToCheck = [NSString stringWithFormat:@"%@staffimages/%@/%@",globalvariables.serverpath,globalvariables.centerrecord.centerdb, staffobject.avatar];
    }else if ([type isEqualToString:@"centerimage"] || [type isEqualToString:@"launchimage"]){
        cacheKeyToCheck = [NSString stringWithFormat:@"%@centerimages/%@",globalvariables.serverpath,typekey];
    }else if ([type isEqualToString:@"class"]){
        cacheKeyToCheck = [NSString stringWithFormat:@"%@classimages/%@/%@",globalvariables.serverpath,globalvariables.centerrecord.centerdb,typekey];
    }else if ([type isEqualToString:@"message"]){
        cacheKeyToCheck = [NSString stringWithFormat:@"%@messageimages/%@/%@",globalvariables.serverpath,globalvariables.centerrecord.centerdb,typekey];
    }
    
    if([[SDImageCache sharedImageCache] imageFromCacheForKey:cacheKeyToCheck]){
        return TRUE;
    }
    return FALSE;
}

