+(NSMutableArray *) retrieveLeaveNatureArrayWithFlushCacheData:(BOOL)flushcachedata
{
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    
    if (flushcachedata) {
        [MyClass getLatestDataSetv2withParameters:@"leavenature" Centerkeys:globalvariables.centerrecord.centerkey completionBlock:nil];
    }
    
    NSMutableArray *tmpattendancenaturearray=[[NSMutableArray alloc]initWithArray:[globalvariables.leavenaturearray allValues]];
    
    NSPredicate *predicate = [NSPredicate predicateWithFormat:@"self.centerkey=%@",globalvariables.centerrecord.centerkey];
    /*NSPredicate *newpredicate = [NSPredicate predicateWithFormat:@"self.is_student_request==1"];
     predicate=[NSCompoundPredicate andPredicateWithSubpredicates:@[predicate,newpredicate]];*/
    
    tmpattendancenaturearray=[[NSMutableArray alloc]initWithArray:[tmpattendancenaturearray filteredArrayUsingPredicate:predicate]];
    NSSortDescriptor *sortByListOrder = [NSSortDescriptor sortDescriptorWithKey:@"listorder" ascending:YES selector:@selector(localizedStandardCompare:)];
    NSArray *sortDescriptors = @[sortByListOrder];
    tmpattendancenaturearray = [NSMutableArray arrayWithArray:[tmpattendancenaturearray sortedArrayUsingDescriptors:sortDescriptors]];
    
    return tmpattendancenaturearray;
}

+(BOOL) lastLeaveNatureStudentRequest
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    NSMutableArray *leavenaturearray=[[NSMutableArray alloc]initWithArray:[globalvariables.leavenaturearray allValues]];
    
    NSPredicate *predicate = [NSPredicate predicateWithFormat:@"self.centerkey=%@",globalvariables.centerrecord.centerkey];
    NSPredicate *newpredicate = [NSPredicate predicateWithFormat:@"self.is_student_request==1"];
    predicate=[NSCompoundPredicate andPredicateWithSubpredicates:@[predicate,newpredicate]];
    
    leavenaturearray=[[NSMutableArray alloc]initWithArray:[leavenaturearray filteredArrayUsingPredicate:predicate]];
    
    return leavenaturearray.count==1;
}

+(NSString *) returnDefaultLeaveNatureListKeyWithAttendance:(NSString *)attendance
{
    NSArray *leavenaturearray=[self retrieveLeaveNatureArrayWithFlushCacheData:NO];
    LeaveNatureRecord *record;
    LeaveNatureConfig *config;
    
    for (int i=0; i<leavenaturearray.count; i++) {
        record=[leavenaturearray objectAtIndex:i];
        config=[record.configdict valueForKey:attendance];
        
        if(config.default_nature_for_staff){
            return record.leavenaturelistkey;
        }
    }
    return @"0";
}

