+(ClassValidateMessage *) returnValidateMessageWithJSONArray:(NSMutableArray *)JSONArray
{
    NSDictionary *classvalidatearray=[self returnValidateClassArrayWithJSONArray:JSONArray Combined:YES];
    
    if(classvalidatearray.count==0){
        return [[ClassValidateMessage alloc]initClassValidateMessagewithoverenrollmentmessage:@"" sameinstructormulticlassmessage:@"" alreadyenrolledmessage:@"" sameclassroommulticlassmessage:@"" hasextendedchildclassmessage:@"" classroomexceedcapacitymessage:@"" makeupquotaexceedmessage:@""];
    }else{
        NSMutableArray *classarray=[[NSMutableArray alloc]initWithArray:[classvalidatearray allValues]];
        ClassValidateRecord *obj=[classarray firstObject];
        return obj.classvalidatemessage;
    }
    

}

+(NSMutableDictionary *) returnValidateClassArrayWithJSONArray:(NSMutableArray *)JSONArray Combined:(BOOL)combined
{
    NSMutableDictionary *validateclassarray=[[NSMutableDictionary alloc]init];
    ClassValidateMessage *classvalidatemessage;
    
    if (JSONArray) {
        NSString *warningtype;
        NSString *studentcount;
        NSString *classdate;
