        NSString *classroomexceedcapacitymessage=@"";
        NSString *makeupquotaexceedmessage=@"";
        NSString *hasextendedchildclassmessage=@"";
        NSString *lastclasskey=@"none";
        
        if (combined) {
            for (int i=0; i<JSONArray.count; i++) {
                
                classkey=[[JSONArray objectAtIndex:i] objectForKey:@"classkey"];
                warningtype=[[JSONArray objectAtIndex:i] objectForKey:@"warningtype"];
                studentcount=[[JSONArray objectAtIndex:i] objectForKey:@"studentcount"];
