                    hasextendedchildclassmessage=[MyClass returnhasextendedchildclassmessagewithmessage:hasextendedchildclassmessage classroom:classroom classdate:classdate classtime:classtime studentcount:studentcount];
                }
                
                if (i==JSONArray.count-1) {
                    classvalidatemessage=[[ClassValidateMessage alloc]initClassValidateMessagewithoverenrollmentmessage:overenrollmentmessage sameinstructormulticlassmessage:sameinstructormulticlassmessage alreadyenrolledmessage:alreadyenrolledmessage sameclassroommulticlassmessage:sameclassroommulticlassmessage hasextendedchildclassmessage:hasextendedchildclassmessage classroomexceedcapacitymessage:classroomexceedcapacitymessage makeupquotaexceedmessage:makeupquotaexceedmessage];
                    
                    [validateclassarray setObject:[[ClassValidateRecord alloc]initClassValidateRecordwithstatus:@"failed" classvalidatestatus:[[ClassValidateStatus alloc]initClassValidateStatuswithoverenrollmentstatus:@"" sameinstructormulticlassstatus:@"" alreadyenrolledstatus:@"" sameclassroommulticlassstatus:@"" hasextendedchildclassstatus:@"" classroomexceedcapacitystatus:@"" makeupquotaexceedstatus:@""] classvalidmessage:classvalidatemessage classkey:lastclasskey] forKey:lastclasskey];
                    //[validateclassarray addObject:[[ClassValidateRecord alloc]initClassValidateRecordwithstatus:@"failed" classvalidatestatus:[[ClassValidateStatus alloc]initClassValidateStatuswithoverenrollmentstatus:@"" sameinstructormulticlassstatus:@"" alreadyenrolledstatus:@"" sameclassroommulticlassstatus:@"" hasextendedchildclassstatus:@"" classroomexceedcapacitystatus:@"" makeupquotaexceedstatus:@""] classvalidmessage:classvalidatemessage classkey:lastclasskey]];
                }
            }
        }
        
        
        
    }
    
    return validateclassarray;
}

+(void) checkValidateMessageWithClassValidateMessage:(ClassValidateMessage *)classvalidatemessage ClassValidateStatus:(ClassValidateStatus *)classvalidatestatus View:(MakeupPopoverViewController *)view
{
    
    if(![classvalidatemessage.hasextendedchildclassmessage isEqualToString:@""] && ![classvalidatestatus.hasextendedchildclassstatus isEqualToString:@"Override"]) {
        
