+(NSString *) returnQuotaSringWithUnit:(NSString *)unit Value:(NSString *)value
{
    if ([value isEqualToString:@"-1"]) {
        return [MyClass returntitlewithtitle:@"Unlimited"];
    }else if ([unit isEqualToString:@"P"]){
        return [NSString stringWithFormat:@"%@%@",value,@"%"];
    }else{
        return value;
    }
}



