+(NSString *) returndefaultarckey
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    if(globalvariables.centerrecord.enableaccountreceivablecodes){
        NSArray *defaultarckeyarray=[[NSArray alloc]init];
        if (![((Staff *)[MyClass returnstaffrecordwithusername:globalvariables.username]).defaultarckey isEqualToString:@""]) {
            defaultarckeyarray=[((Staff *)[MyClass returnstaffrecordwithusername:globalvariables.username]).defaultarckey componentsSeparatedByString:@","];
        }

        for (int i=0; i<defaultarckeyarray.count; i++) {
            NSString *centerkeyarckey=[defaultarckeyarray objectAtIndex:i];
            NSRange range=[centerkeyarckey rangeOfString:@"#"];
            if (range.location!=NSNotFound) {
                NSString *centerkey=[centerkeyarckey substringToIndex:range.location];
                if ([globalvariables.centerrecord.centerkey isEqualToString:centerkey]) {
                    return [centerkeyarckey substringFromIndex:range.location+1];
                }
            }
        }
    }
    return @"";
}

+(void) savedefaultarckey:(NSString *)arckey
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSMutableArray *defaultarckeyarray=[[NSMutableArray alloc]init];
    if (![((Staff *)[MyClass returnstaffrecordwithusername:globalvariables.username]).defaultarckey isEqualToString:@""]) {
        defaultarckeyarray=[[NSMutableArray alloc]initWithArray:[((Staff *)[MyClass returnstaffrecordwithusername:globalvariables.username]).defaultarckey componentsSeparatedByString:@","]];
    }
    for (int i=0; i<defaultarckeyarray.count; i++) {
        NSString *centerkeyarckey=[defaultarckeyarray objectAtIndex:i];
        NSRange range=[centerkeyarckey rangeOfString:@"#"];
        if (range.location!=NSNotFound) {
            NSString *centerkey=[centerkeyarckey substringToIndex:range.location];
            if ([globalvariables.centerrecord.centerkey isEqualToString:centerkey]) {
                if ([arckey isEqualToString:@""]) {
                    [defaultarckeyarray removeObjectAtIndex:i];
                }else{
                    [defaultarckeyarray replaceObjectAtIndex:i withObject:[NSString stringWithFormat:@"%@#%@",centerkey,arckey]];
                }
                
                [MyClass updateUserAccountSettingsWithField:@"defaultarckey" Value:arckey];
                ((Staff *)[MyClass returnstaffrecordwithusername:globalvariables.username]).defaultarckey=[defaultarckeyarray componentsJoinedByString:@","];
                return;
            }
        }
    }
    
    [defaultarckeyarray addObject:[NSString stringWithFormat:@"%@#%@",globalvariables.centerrecord.centerkey,arckey]];
    //[MyClass updatelocaldbwithparameter:@"defaultarckey" value:[defaultarckeyarray componentsJoinedByString:@","]];
    [MyClass updateUserAccountSettingsWithField:@"defaultarckey" Value:arckey];
    ((Staff *)[MyClass returnstaffrecordwithusername:globalvariables.username]).defaultarckey=[defaultarckeyarray componentsJoinedByString:@","];
    
}

+(NSInteger) returntimevaluewithtime:(NSString *)time
{
    return [[time substringToIndex:2] integerValue]*60+[[time substringFromIndex:3] integerValue];
}

+(void) drawAvailabilityChartWithView:(UIImageView *)imageview AvailabilityRecords:(NSMutableArray *)availabilityrecords ClassRecords:(NSMutableArray *)classrecords Small:(BOOL)small
{
    UIView *view=[[UIView alloc]initWithFrame:imageview.bounds];
    
    AvailabilityRecord *record;
    
    float outercircleradius=imageview.frame.size.width/2;
    float middlecircleradius=imageview.frame.size.width/2*0.7f;
    
    CAShapeLayer *drawobject = [CAShapeLayer layer];
    CGMutablePathRef path;
    
    //add availability circle
    drawobject = [CAShapeLayer layer];
    path = CGPathCreateMutable();
    
    CGPathAddArc(path, NULL, outercircleradius, outercircleradius, outercircleradius, 0,360*M_PI/180, 0);
    CGPathAddLineToPoint(path, NULL, outercircleradius+middlecircleradius*cosf(360*M_PI/180), outercircleradius+middlecircleradius*sinf(360*M_PI/180));
    CGPathAddArc(path, NULL, outercircleradius, outercircleradius, middlecircleradius, 360*M_PI/180, 0, 1);
    CGPathAddLineToPoint(path, NULL, outercircleradius+outercircleradius, outercircleradius);
    
    [drawobject setPath:path];
    [drawobject setStrokeColor:[[UIColor clearColor] CGColor]];
    [drawobject setFillColor:[[UIColor orangeColor] CGColor]];
    [drawobject setOpacity:0.15f];
    [[view layer] addSublayer:drawobject];
    
    for (int i=0;i<availabilityrecords.count;i++) {
        record=[availabilityrecords objectAtIndex:i];
        
        float startingangle=360*[self returntimevaluewithtime:record.starttime]/1440.0-90;
        float endingangle=360*[self returntimevaluewithtime:record.endtime]/1440.0-90;
        
        drawobject = [CAShapeLayer layer];
        path = CGPathCreateMutable();

        
        CGPathAddArc(path, NULL, outercircleradius, outercircleradius, outercircleradius, startingangle*M_PI/180,endingangle*M_PI/180, 0);
        CGPathAddLineToPoint(path, NULL, outercircleradius+middlecircleradius*cosf(endingangle*M_PI/180), outercircleradius+middlecircleradius*sinf(endingangle*M_PI/180));
        CGPathAddArc(path, NULL, outercircleradius, outercircleradius, middlecircleradius, endingangle*M_PI/180, startingangle*M_PI/180, 1);
        CGPathAddLineToPoint(path, NULL, outercircleradius+outercircleradius*cosf(startingangle*M_PI/180), outercircleradius+outercircleradius*sinf(startingangle*M_PI/180));
        

        [drawobject setPath:path];
        [drawobject setStrokeColor:[[UIColor orangeColor] CGColor]];
        [drawobject setFillColor:[UIColor orangeColor].CGColor];
        
        [drawobject setOpacity:1.0f];

        [[view layer] addSublayer:drawobject];
        CGPathRelease(path);
    }
    

    
    float innercircleradius=imageview.frame.size.width/2*0.4f;
    
    //add class records circle
    drawobject = [CAShapeLayer layer];
    path = CGPathCreateMutable();
    
    CGPathAddArc(path, NULL, outercircleradius, outercircleradius, middlecircleradius, 0,360*M_PI/180, 0);
    CGPathAddLineToPoint(path, NULL, middlecircleradius+middlecircleradius*cosf(360*M_PI/180), middlecircleradius+middlecircleradius*sinf(360*M_PI/180));
    CGPathAddArc(path, NULL, outercircleradius, outercircleradius, innercircleradius, 360*M_PI/180, 0, 1);
    CGPathAddLineToPoint(path, NULL, middlecircleradius+middlecircleradius, middlecircleradius);
    
    [drawobject setPath:path];
    [drawobject setStrokeColor:[[UIColor clearColor] CGColor]];
    [drawobject setFillColor:[[UIColor colorWithRed:228.0/255.0 green:183.0/255.0 blue:248.0/255.0 alpha:0.35] CGColor]];
    [[view layer] addSublayer:drawobject];
    
    for (int i=0;i<classrecords.count;i++) {
        record=[classrecords objectAtIndex:i];
        
        float startingangle=360*[self returntimevaluewithtime:record.starttime]/1440.0-90;
        float endingangle=360*[self returntimevaluewithtime:record.endtime]/1440.0-90;
        
        drawobject = [CAShapeLayer layer];
        path = CGPathCreateMutable();
        
        
        CGPathAddArc(path, NULL, outercircleradius, outercircleradius, middlecircleradius, startingangle*M_PI/180,endingangle*M_PI/180, 0);
        CGPathAddLineToPoint(path, NULL, outercircleradius+innercircleradius*cosf(endingangle*M_PI/180), outercircleradius+innercircleradius*sinf(endingangle*M_PI/180));
        CGPathAddArc(path, NULL, outercircleradius, outercircleradius, innercircleradius, endingangle*M_PI/180, startingangle*M_PI/180, 1);
        CGPathAddLineToPoint(path, NULL, outercircleradius+middlecircleradius*cosf(startingangle*M_PI/180), outercircleradius+middlecircleradius*sinf(startingangle*M_PI/180));
        
        
        [drawobject setPath:path];
        [drawobject setStrokeColor:[[UIColor colorWithRed:133.0/255.0 green:80.0/255.0 blue:149.0/255.0 alpha:1.0] CGColor]];
        [drawobject setFillColor:[UIColor colorWithRed:133.0/255.0 green:80.0/255.0 blue:149.0/255.0 alpha:1.0].CGColor];
        
        [drawobject setOpacity:1.0f];
        
        [[view layer] addSublayer:drawobject];
        CGPathRelease(path);
    }
    

    
    //add center circle
    if(!small){
        drawobject = [CAShapeLayer layer];
        path = CGPathCreateMutable();
        CGPathAddArc(path, NULL, outercircleradius, outercircleradius, innercircleradius, 0, 360*M_PI/180, 1);
        [drawobject setPath:path];
        [drawobject setFillColor:[[UIColor darkGrayColor] CGColor]];
        [drawobject setOpacity:0.9f];
        [[view layer] addSublayer:drawobject];
    }

    UIGraphicsBeginImageContext(view.bounds.size);
    [view.layer renderInContext:UIGraphicsGetCurrentContext()];
    
    UIImage * img = UIGraphicsGetImageFromCurrentImageContext();
    
    UIGraphicsEndImageContext();
    
    [imageview setImage:img];
    
}

+(void) getStaffAvailabilityWithUsername:(NSString *)username InstructorAvailabilityDict:(NSMutableDictionary *)instructoravailabilitydict ClassRecordsDict:(NSMutableDictionary *)classrecordsdict
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    //instructoravailabilitydict=[[NSMutableDictionary alloc]init];
    
    //combine arrays
    NSDictionary *dictionary = @{@"centerdb" : globalvariables.centerrecord.centerdb,
                                 @"centerkey" : globalvariables.centerrecord.centerkey,
                                 @"username" : username,
                                 @"postaction" : @"getstaffavailabilityv2"};
    
    __block BOOL result=FALSE;
    [MyClass callPOSTwithDict:dictionary completionBlock:^(BOOL succeeded, NSData *data) {
        if (succeeded) {
            NSDictionary *jsonreturned=[NSJSONSerialization JSONObjectWithData:data options:(kNilOptions) error:nil];
            NSDictionary *jsondictionary = jsonreturned[@"content"];
            NSArray *jsonschedulerecords=jsondictionary[@"schedulerecords"];
            NSArray *jsonclassrecords=jsondictionary[@"classrecords"];
            
            for (int i=0; i<jsonschedulerecords.count; i++) {
                NSString *date=[[jsonschedulerecords objectAtIndex:i] objectForKey:@"date"];
                NSArray *availabilityrecords=[[jsonschedulerecords objectAtIndex:i] objectForKey:@"availabilityrecords"];
                
                NSMutableArray *availabilityarray=[[NSMutableArray alloc]init];
                for (int j=0; j<availabilityrecords.count; j++) {
                    NSString *starttime=[[availabilityrecords objectAtIndex:j] objectForKey:@"starttime"];
                    NSString *endtime=[[availabilityrecords objectAtIndex:j] objectForKey:@"endtime"];
                    [availabilityarray addObject:[[AvailabilityRecord alloc]initAvailabilityRecordWithDate:date StartTime:starttime EndTime:endtime]];
                }
                [instructoravailabilitydict setObject:availabilityarray forKey:date];
            }
            
            for (int i=0; i<jsonclassrecords.count; i++) {
                NSString *date=[[jsonclassrecords objectAtIndex:i] objectForKey:@"date"];
                NSArray *classtimerecords=[[jsonclassrecords objectAtIndex:i] objectForKey:@"classtimerecords"];
                
                NSMutableArray *classtimearray=[[NSMutableArray alloc]init];
                for (int j=0; j<classtimerecords.count; j++) {
                    NSString *starttime=[[classtimerecords objectAtIndex:j] objectForKey:@"starttime"];
                    NSString *endtime=[[classtimerecords objectAtIndex:j] objectForKey:@"endtime"];
                    [classtimearray addObject:[[AvailabilityRecord alloc]initAvailabilityRecordWithDate:date StartTime:starttime EndTime:endtime]];
                }
                [classrecordsdict setObject:classtimearray forKey:date];
            }
        }
    }];
    /*
