+(void) showDuePaymentReminderWithViewController:(UIViewController *)view
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    if ([globalvariables.centerrecord.duepayment isEqualToString:@"R"]) {
        UIAlertController *alert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"iSchool Payment"] message:[MyClass returntitlewithtitle:@"Please kindly settle the next term service fee"] preferredStyle:UIAlertControllerStyleAlert];
        
        UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
        }];
        
        
        [alert addAction:OKAction];
        
        [view presentViewController:alert animated:YES completion:nil];
        
    }else if ([globalvariables.centerrecord.duepayment isEqualToString:@"O"]) {
        UIAlertController *alert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"iSchool Payment"] message:[MyClass returntitlewithtitle:@"Please kindly settle the overdue service fee"] preferredStyle:UIAlertControllerStyleAlert];
        
        UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
        }];
        
        
        [alert addAction:OKAction];
        
        [view presentViewController:alert animated:YES completion:nil];
    }else if ([globalvariables.centerrecord.duepayment integerValue]>0) {
        NSString *message;
        if ([globalvariables.centerrecord.duepayment integerValue]==1) {
            message=[MyClass returnreplacedtitlewithtitle:@"Your service will be suspended in %@1 day. Please kindly settle the outstanding service fee" replacementarray:@[globalvariables.centerrecord.duepayment]];
        }else{
            message=[MyClass returnreplacedtitlewithtitle:@"Your service will be suspended in %@1 days. Please kindly settle the outstanding service fee" replacementarray:@[globalvariables.centerrecord.duepayment]];
        }

        UIAlertController *alert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"iSchool Payment"] message:message preferredStyle:UIAlertControllerStyleAlert];
        
        UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
        }];
        
        
        [alert addAction:OKAction];
        
        [view presentViewController:alert animated:YES completion:nil];
    }

}

+(void) showResetPasswordReminder:(UIViewController *)view
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    if (![globalvariables.passwordexpirydate isEqualToString:@""]&& ![globalvariables.passwordexpirydate isEqualToString:@"expired"]) {
        if (![globalvariables.passwordexpirylastshowndate isEqualToString:[MyClass convertToNSStringWithNSDate:[NSDate date] DateFormat:@"yyyy-MM-dd"]]) {
            globalvariables.passwordexpirylastshowndate=[MyClass convertToNSStringWithNSDate:[NSDate date] DateFormat:@"yyyy-MM-dd"];

        UIAlertController *alert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"User Account"] message:[MyClass returnreplacedtitlewithtitle:@"Your password is going to expire on %@1. Do you want to reset your password?" replacementarray:@[globalvariables.passwordexpirydate]] preferredStyle:UIAlertControllerStyleAlert];
        
        UIAlertAction *ResetNowAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"Reset Now"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
            //remove token and device from user_token and user_device
            if ([self removeUserTokenDeviceWithUserDeviceKey:globalvariables.userdevicekey]) {
                [self resetPassword];
            }
            
        }];
            
        UIAlertAction *LaterAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"Cancel"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
        }];
        
        [alert addAction:LaterAction];
        [alert addAction:ResetNowAction];
        
        [view presentViewController:alert animated:YES completion:nil];
        
        }
    }
}

+(NSMutableDictionary *) retrieveDiscountDetailsWithDocType:(NSInteger)doctype ClassDocumentArray:(NSMutableArray *)classdocumentarray SalesDocumentArray:(NSMutableArray *)salesdocumentarray Centerrecord:(CenterRecord *)centerrecord
{
    //GlobalVariables *globalvariables=[GlobalVariables singleObj];
    //NSMutableArray *typekeyarray=[[NSMutableArray alloc]init];
    NSMutableDictionary *discountdict=[[NSMutableDictionary alloc] init];
    
    if (doctype==0 && !centerrecord.showdiscountdetailsininvoice) {
        return discountdict;
    }else if (doctype==1 && !centerrecord.showdiscountdetailsinreceipt) {
        return discountdict;
    }
    
    for (int i=0; i<classdocumentarray.count; i++) {
        EnrollmentRecord *enrollmentrecord=[[classdocumentarray objectAtIndex:i] valueForKey:@"enrollmentrecord"];
        
        [discountdict setObject:[MyClass returnDiscountArrayWithEnrollmentRecord:enrollmentrecord] forKey:[[classdocumentarray objectAtIndex:i] valueForKey:@"enrollmentkey"]];
        
        //[typekeyarray addObject:[[classdocumentarray objectAtIndex:i] valueForKey:@"enrollmentkey"]];
    }
    
    for (int i=0; i<salesdocumentarray.count; i++) {
        SalesRecord *salesrecord=[[salesdocumentarray objectAtIndex:i] valueForKey:@"salesrecord"];
        
        [discountdict setObject:[MyClass returnDiscountArrayWithSalesRecord:salesrecord] forKey:[[salesdocumentarray objectAtIndex:i] valueForKey:@"saleskey"]];
        
        //[typekeyarray addObject:[[salesdocumentarray objectAtIndex:i] valueForKey:@"saleskey"]];
    }

    
    return discountdict;
}

+(NSString *) returnclassremarkswithclassrecord:(ClassRecord2 *)classrecord
{
    NSMutableArray *remarksarray=[[NSMutableArray alloc]init];
    
    if([classrecord.attendance isEqualToString:@"Makeup"]){
        [remarksarray addObject:[MyClass returnreplacedtitlewithtitle:@"(Original class on %@1)" replacementarray:@[[MyClass returndateformatDDMMMYYYYHHMMwithdate:[NSString stringWithFormat:@"%@ %@",classrecord.startdate,classrecord.classtime]]]]];
    }
    
    
    if(![classrecord.remarks isEqualToString:@""]){
        [remarksarray addObject:classrecord.remarks];
    }
    
    if(![classrecord.allclassremarks isEqualToString:@""]){
        [remarksarray addObject:classrecord.allclassremarks];
    }
    
    if(![classrecord.parentnote isEqualToString:@""]){
        [remarksarray addObject:classrecord.parentnote];
    }
    
    return [remarksarray componentsJoinedByString:@" / "];
}


