+(NSString *) returnagewithtype:(NSString *)type typekey:(NSString *)typekey
{
    NSString *age;
    NSString *dateofbirth;
    if ([type isEqualToString:@"student"]) {
        Student *obj=[MyClass returnstudentwithstudentkey:typekey];
        age=obj.age;
        dateofbirth=obj.dateofbirth;
    }else{
        Lead *obj=[MyClass returnleadwithleadkey:typekey];
        age=obj.age;
        dateofbirth=obj.dateofbirth;
    }
    
    if (![dateofbirth isEqualToString:@""]){
        double time =[[NSDate date] timeIntervalSinceDate:[self convertToNSDateWithDate:dateofbirth DateFormat:@"dd-MMM-yyyy"]];
        int allDays = (((time/60)/60/24));
        int days=allDays%365;
        int years=(allDays-days)/365;
        return [@(years) stringValue];
    }else{
        return age;
    }
}

+(ContactRecord *) returnprimarycontactwithtype:(NSString *)type typekey:(NSString *)typekey
{
    
    if ([type isEqualToString:@"lead"]) {
        ContactRecord *object=[[ContactRecord alloc]init];
        Lead *lead=[MyClass returnleadwithleadkey:typekey];
        object.contact=lead.parentcontact;
        object.iso_code=lead.iso_code;
        return object;
    }else{
        Student *student=[MyClass returnstudentwithstudentkey:typekey];
        for (int i=0; i<student.phonearray.count; i++) {
            ContactRecord *contact=[student.phonearray objectAtIndex:i];
            if (contact.primarycontact) {
                return contact;
            }
        }
    }
    
    return nil;
}

+(NSInteger) returnChannelIndexWithRecipientType:(NSString *)recipienttype Channel:(NSString *)channel
{
    if ([recipienttype isEqualToString:@"Student"]) {
        if ([channel isEqualToString:@"AS"]) {
            return 0;
        }else if ([channel isEqualToString:@"A"]) {
            return 1;
        }else if ([channel isEqualToString:@"S"]) {
            return 2;
        }else if ([channel isEqualToString:@"E"]){
            return 3;
        }
    }else if ([recipienttype isEqualToString:@"Lead"]) {
        if ([channel isEqualToString:@"S"]) {
            return 0;
        }else if ([channel isEqualToString:@"E"]) {
            return 1;
        }
    }else{
        if ([channel isEqualToString:@"A"]) {
            return 0;
        }else if ([channel isEqualToString:@"S"]) {
            return 1;
        }else if ([channel isEqualToString:@"E"]){
            return 2;
        }
    }
    return 0;
}

+(NSString *) returnChannelCodeWithRecipientType:(NSString *)recipienttype Index:(NSString *)index
{
    if ([recipienttype isEqualToString:@"Student"]) {
        if([index isEqualToString:@"0"]){
            return @"AS";
        }else if([index isEqualToString:@"1"]){
            return @"A";
        }else if([index isEqualToString:@"2"]){
            return @"S";
        }else if([index isEqualToString:@"3"]){
            return @"E";
        }
    }else if ([recipienttype isEqualToString:@"Lead"]) {
        if([index isEqualToString:@"0"]){
            return @"S";
        }else if([index isEqualToString:@"1"]){
            return @"E";
        }
    }
    return @"";
}

+(NSInteger) noOfDayBetweenStartDate:(NSDate *)startdate EndDate:(NSDate *)enddate
{
    NSDateComponents *dateComponent = [[NSCalendar currentCalendar] components:NSCalendarUnitDay fromDate:startdate toDate:enddate options:0];
    //NSLog(@"%ld",(long)dateComponent.day);
    return dateComponent.day;
}

+ (UIImage *)imageRotatedOnDegrees:(CGFloat)degrees Image:(UIImage *)image
{
    // Follow ing code can only rotate images on 90, 180, 270.. degrees.
    CGFloat roundedDegrees = (CGFloat)(round(degrees / 90.0) * 90.0);
    BOOL sameOrientationType = ((NSInteger)roundedDegrees) % 180 == 0;
    CGFloat radians = M_PI * roundedDegrees / 180.0;
    CGSize newSize = sameOrientationType ? image.size : CGSizeMake(image.size.height, image.size.width);
    
    UIGraphicsBeginImageContext(newSize);
    CGContextRef ctx = UIGraphicsGetCurrentContext();
    CGImageRef cgImage = image.CGImage;
    if (ctx == NULL || cgImage == NULL) {
        UIGraphicsEndImageContext();
        return image;
    }
    
    CGContextTranslateCTM(ctx, newSize.width / 2.0, newSize.height / 2.0);
    CGContextRotateCTM(ctx, radians);
    CGContextScaleCTM(ctx, 1, -1);
    CGPoint origin = CGPointMake(-(image.size.width / 2.0), -(image.size.height / 2.0));
    CGRect rect = CGRectZero;
    rect.origin = origin;
    rect.size = image.size;
    CGContextDrawImage(ctx, rect, cgImage);
    UIImage *rotatedimage = UIGraphicsGetImageFromCurrentImageContext();
    UIGraphicsEndImageContext();
    return rotatedimage ?: image;
}

