+(NSMutableArray *) returnCountryCodeArray
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSMutableArray *countrycodearray=[[NSMutableArray alloc]initWithArray:[globalvariables.countrycodearray allValues]];
    
    NSSortDescriptor *sortbyisocode = [NSSortDescriptor sortDescriptorWithKey:@"country_name" ascending:YES selector:@selector(localizedStandardCompare:)];
