+(ContactRecord *) returncontactrecordwithstudentkey:(NSString *)studentkey contact:(NSString *)contact
{
    ContactRecord *obj;
    
    //parent
    Student *student=[MyClass returnstudentwithstudentkey:studentkey];
    if (student) {
        for (int i=0; i<student.phonearray.count; i++) {
            obj=[student.phonearray objectAtIndex:i];
            if ([obj.contact isEqualToString:contact]) {
                return obj;
            }
        }
    }
    
    return nil;
}

