+(NSInteger) returnFreeColorCodewithType:(NSString *)type
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    NSMutableArray *resultarray=[[NSMutableArray alloc]init];
    
    NSString *sql;
    sqlite3_stmt *statement;
    
    
    if ([type isEqualToString:@"subject"]) {
        sql =[NSString stringWithFormat:@"SELECT distinct colorcode from subject_information where centerkey='%@'",globalvariables.centerrecord.centerkey];
        
        if(sqlite3_prepare_v2(globalvariables.isdb, [sql UTF8String], -1, &statement, nil)==SQLITE_OK){
            while (sqlite3_step(statement)==SQLITE_ROW) {
                NSString *colorcode=[[NSString alloc]initWithUTF8String:(char *)sqlite3_column_text(statement, 0)];
                [resultarray addObject:colorcode];
            }
        }
    }else if ([type isEqualToString:@"classroom"]){
        NSMutableArray *classroomarray=[MyClass retrieveClassroomListwithstatus:@"All" withTBD:NO flushcachedata:NO];
        for (int i=0; i<classroomarray.count; i++) {
            [resultarray addObject:[@(((ClassroomRecord *)[classroomarray objectAtIndex:i]).colorcode) stringValue]];
        }
    }else if ([type isEqualToString:@"staff"]){
        NSMutableArray *staffroomarray=[MyClass retrieveStaffListwithvalid:@"All" role:@"All" flushcachedata:NO];
        for (int i=0; i<staffroomarray.count; i++) {
            [resultarray addObject:[@(((Staff *)[staffroomarray objectAtIndex:i]).colorcode) stringValue]];
        }
    }
    
    for (int i=0; i<globalvariables.colorcodearray.count; i++) {
        if (![resultarray containsObject:[@(i) stringValue]]) {
            return i;
        }
    }
    return globalvariables.colorcodearray.count-1;
    
}

