+(BOOL) classendtimebeyondcenterendtimewithclassstarttime:(NSString *)classstarttime duration:(NSInteger)duration
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
 
    if(globalvariables.centerrecord.fullday){
        return FALSE;
    }else{
        NSInteger classstarttimeinteger=[[classstarttime substringToIndex:2] integerValue]*60+[[classstarttime substringFromIndex:2] integerValue]+duration;
        NSInteger centerendtimeinteger=[[globalvariables.centerrecord.classendtime substringToIndex:2] integerValue]*60+[[globalvariables.centerrecord.classendtime substringFromIndex:2] integerValue];
        
        return classstarttimeinteger>centerendtimeinteger;
    }
}

+(void) loadHourPickerViewMenu:(NSMutableArray *)hourPickerViewMenu
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    if(globalvariables.centerrecord.fullday){
        for (int i=0;i<24;i++){
            [hourPickerViewMenu addObject:[NSString stringWithFormat:@"%02i",i]];
        }
    }else{
        for (int i=[[globalvariables.centerrecord.classstarttime substringToIndex:2] intValue]; i<=[[[NSString stringWithFormat:@"%i",[globalvariables.centerrecord.classendtime intValue]-1] substringToIndex:2] intValue]; i++) {
            [hourPickerViewMenu addObject:[NSString stringWithFormat:@"%02i",i]];
        }
    }
}

+(float) returnTimeTableNoOfTimeSlotWithCellDuration:(float)cellduration
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    if(globalvariables.centerrecord.fullday){
        return (24*60/cellduration);
    }else{
        return ([[globalvariables.centerrecord.classendtime substringToIndex:2] intValue]*60 + [[globalvariables.centerrecord.classendtime substringFromIndex:2] intValue] - ([[globalvariables.centerrecord.classstarttime substringToIndex:2] intValue]*60 + [[globalvariables.centerrecord.classstarttime substringFromIndex:2] intValue]))/cellduration;
    }
}

+(UIWindow *)activeWindow
{
    UIWindow *activeWindow = nil;
    for (UIScene *scene in [UIApplication sharedApplication].connectedScenes) {
        if (![scene isKindOfClass:[UIWindowScene class]]) {
            continue;
        }
        UIWindowScene *windowScene = (UIWindowScene *)scene;
        for (UIWindow *window in windowScene.windows) {
            if (window.isKeyWindow) {
                return window;
            }
        }
        if (!activeWindow && windowScene.windows.count > 0) {
            activeWindow = windowScene.windows.firstObject;
        }
    }
    return activeWindow;
}

