+(NSString *) returnMessageTimeWithMessageStartTime:(NSString *)messagestarttime
{
    if ([[messagestarttime substringToIndex:10] isEqualToString:[MyClass convertToNSStringWithNSDate:[NSDate date] DateFormat:@"yyyy-MM-dd"]]) {
        return [[messagestarttime substringFromIndex:11] substringToIndex:5];
    }else{
        if ([[messagestarttime substringToIndex:4] isEqualToString:[MyClass convertToNSStringWithNSDate:[NSDate date] DateFormat:@"yyyy"]]) {
            return [MyClass convertDateFormatWithDate:messagestarttime FromDateFormat:@"yyyy-MM-dd HH:mm:ss" ToDateFormat:@"d/M HH:mm" Translate:NO];
        }else{
            return [MyClass convertDateFormatWithDate:messagestarttime FromDateFormat:@"yyyy-MM-dd HH:mm:ss" ToDateFormat:@"d/M/yyyy HH:mm" Translate:NO];
        }
    }
}

