+(void) playBeepSoundWithType:(NSString *)type
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSString *beepFilePath;
    if([type isEqualToString:@"passed"]){
        beepFilePath = [[NSBundle mainBundle] pathForResource:@"beep" ofType:@"mp3"];
    }else if ([type isEqualToString:@"failed"]){
        beepFilePath = [[NSBundle mainBundle] pathForResource:@"failedbeep" ofType:@"mp3"];
    }else if ([type isEqualToString:@"newmessage"]){
        beepFilePath = [[NSBundle mainBundle] pathForResource:@"newmessage" ofType:@"mp3"];
    }else if ([type isEqualToString:@"audiostart"]){
        beepFilePath = [[NSBundle mainBundle] pathForResource:@"audiostart" ofType:@"mp3"];
    }else if ([type isEqualToString:@"audiocancel"]){
        beepFilePath = [[NSBundle mainBundle] pathForResource:@"audiocancel" ofType:@"mp3"];
    }else if ([type isEqualToString:@"audiostop"]){
        beepFilePath = [[NSBundle mainBundle] pathForResource:@"audiostop" ofType:@"mp3"];
    }else if ([type isEqualToString:@"duepayment"]){
        beepFilePath = [[NSBundle mainBundle] pathForResource:@"duepayment" ofType:@"mp3"];
    }else{
        beepFilePath = [[NSBundle mainBundle] pathForResource:@"success" ofType:@"mp3"];
    }
    
    
    NSURL *beepURL = [NSURL URLWithString:beepFilePath];
    NSError *error;
    
    globalvariables.audioplayer = [[AVAudioPlayer alloc] initWithContentsOfURL:beepURL error:&error];
    if (error)
    {
        NSLog(@"Could not play beep file.");
        NSLog(@"%@", [error localizedDescription]);
    }
    else
    {
        [globalvariables.audioplayer play];
    }
    
}

