    if (secondsBetween>3 ||!globalvariables.lastgetunreadmessagecountdatetime) {
        NSString *strURL=[NSString stringWithFormat:@"%@?centerdb=%@&action=retrieveunreadmessagecount&username=%@&apptype=center&centerkey=%@",globalvariables.generalphpfullpath,globalvariables.centerrecord.centerdb,globalvariables.username,globalvariables.centerrecord.centerkey];
            
        __block BOOL result=FALSE;
        __block NSMutableArray *JSONArray;
        
        [MyClass callGETwithURL:strURL completionBlock:^(BOOL succeeded, NSData *data) {
            if (succeeded) {
                result=TRUE;
                NSDictionary *jsonreturned=[NSJSONSerialization JSONObjectWithData:data options:(kNilOptions) error:nil];
                JSONArray = jsonreturned[@"content"];
            }
        }];
        
        if (result) {
            globalvariables.unreadmessagecount=[[[JSONArray objectAtIndex:0] objectForKey:@"unreadmessagecount"] intValue];
            globalvariables.pendingrequestcount=[[[JSONArray objectAtIndex:0] objectForKey:@"pendingrequestcount"] intValue];
            
