//                globalvariables.pendingrequestcountview.hidden=NO;
//            }else{
//                globalvariables.pendingrequestcountview.hidden=YES;
//            }
            
            globalvariables.lastgetunreadmessagecountdatetime=[NSDate date];
        }
    }
}

+(NSString *) returnreplacedtitlewithtitle2:(NSString *)title replacementarray:(NSArray *)replacementarray
{
    
    GlobalVariables *globalvariables;
    globalvariables=[GlobalVariables singleObj];
    NSString *replacedchar=@"%@";
    
    LanguageTitleRecord *titlerecord=[globalvariables.languagepackdictionary objectForKey:[NSString stringWithFormat:@"%@#%@",/*globalvariables.centerrecord.centerkey*/@"",title]];
    if (titlerecord) {
        NSString *titleresult=[titlerecord valueForKey:[globalvariables.language lowercaseString]];
        for (int i=0; i<replacementarray.count; i++) {
            NSString *replacedstring=[NSString stringWithFormat:@"%@%d",replacedchar,i+1];
            titleresult=[titleresult stringByReplacingOccurrencesOfString:replacedstring withString:[replacementarray objectAtIndex:i]];
        }
        return titleresult;
    }else{
        LanguageTitleRecord *titlerecord=[globalvariables.languagepackdictionary objectForKey:[NSString stringWithFormat:@"%@#%@",@"",title]];
        if (titlerecord) {
            NSString *titleresult=[titlerecord valueForKey:[globalvariables.language lowercaseString]];
            for (int i=0; i<replacementarray.count; i++) {
                NSString *replacedstring=[NSString stringWithFormat:@"%@%d",replacedchar,i+1];
                titleresult=[titleresult stringByReplacingOccurrencesOfString:replacedstring withString:[replacementarray objectAtIndex:i]];
            }
            return titleresult;
        }else{
            NSString *titleresult=title;
            for (int i=0; i<replacementarray.count; i++) {
                NSString *replacedstring=[NSString stringWithFormat:@"%@%d",replacedchar,i+1];
                titleresult=[titleresult stringByReplacingOccurrencesOfString:replacedstring withString:[replacementarray objectAtIndex:i]];
            }
            return titleresult;
        }
    }
}

+(NSMutableArray *) copyPhotoArrayWithPhotoArray:(NSMutableArray *)photoarray LoadInternalURL:(BOOL)loadinternalurl
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSMutableArray *tmpphotoarray=[[NSMutableArray alloc]init];
    MessagePhotoRecord *msgphotoobject;
    
    for (int i=0; i<photoarray.count; i++) {
        MessagePhotoRecord *messagephotoobject=[photoarray objectAtIndex:i];
        
        if (loadinternalurl) {
            NSString *strURL=[NSString stringWithFormat:@"%@messageimages/%@/%@",globalvariables.serverpath,globalvariables.centerrecord.centerdb,messagephotoobject.messagephotourl];
            NSURL *url =[NSURL URLWithString:[strURL stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLQueryAllowedCharacterSet]]];
            
            NSData *data=[[NSData alloc]initWithContentsOfURL:url];
            
            NSString *filename=messagephotoobject.messagephotourl;
            NSURL *fileUrl=[MyClass returnInternalURLforNSData:data Filename:filename];
            
            UIImageView *imageview=[[UIImageView alloc]init];
            if ([messagephotoobject.filetype isEqualToString:@"video"]) {
                imageview.image=[MyClass getThumbnailImageFromVideo:fileUrl];
            }else if ([messagephotoobject.filetype isEqualToString:@"pdf"]){
                imageview.image=[MyClass returnPDFFirstPageImageWithPDFData:data];
            }else if ([messagephotoobject.filetype isEqualToString:@"image"]){
                imageview.image=[[UIImage alloc]initWithData:data];
            }
            
            msgphotoobject=[[MessagePhotoRecord alloc]initMessagePhotoRecordwithMessagePhotoKey:messagephotoobject.messagephotokey MessagePhotoURL:messagephotoobject.messagephotourl ImageView:imageview Width:messagephotoobject.width Height:messagephotoobject.height FileType:messagephotoobject.filetype InternalURL:fileUrl FileName:messagephotoobject.filename ThumbnailURL:messagephotoobject.thumbnailurl];
        }else{
            NSString *strURL=[NSString stringWithFormat:@"%@messageimages/%@/%@",globalvariables.serverpath,globalvariables.centerrecord.centerdb,messagephotoobject.thumbnailurl];
            NSURL *url =[NSURL URLWithString:[strURL stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLQueryAllowedCharacterSet]]];
            
            NSData *data=[[NSData alloc]initWithContentsOfURL:url];
            UIImageView *imageview=[[UIImageView alloc]init];
            imageview.image=[[UIImage alloc] initWithData:data];
            
            msgphotoobject=[[MessagePhotoRecord alloc]initMessagePhotoRecordwithMessagePhotoKey:messagephotoobject.messagephotokey MessagePhotoURL:messagephotoobject.messagephotourl ImageView:imageview Width:messagephotoobject.width Height:messagephotoobject.height FileType:messagephotoobject.filetype InternalURL:[[NSURL alloc]init] FileName:messagephotoobject.filename ThumbnailURL:messagephotoobject.thumbnailurl];
            
        }

        [tmpphotoarray addObject:msgphotoobject];
    }
    return tmpphotoarray;
}

