+(NSString *) returnautorenewlabelwithautorenewstring:(NSString *)validitystring
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSString *result=@"";
    
    if ([validitystring isEqualToString:@""]) {
        result=[MyClass returntitlewithtitle:@"None"];
    }else{
        if ([globalvariables.language isEqualToString:@"English"]) {
            if ([[validitystring substringFromIndex:1] isEqualToString:@"00"]) {
                if ([[validitystring substringToIndex:1] isEqualToString:@"Y"]) {
                    result=[NSString stringWithFormat:@"0 %@",[MyClass returntitlewithtitle:@"Year"]];
                }else if ([[validitystring substringToIndex:1] isEqualToString:@"M"]) {
                    result=[NSString stringWithFormat:@"0 %@",[MyClass returntitlewithtitle:@"Month"]];
                }else if ([[validitystring substringToIndex:1] isEqualToString:@"W"]) {
                    result=[NSString stringWithFormat:@"0 %@",[MyClass returntitlewithtitle:@"Week"]];
                }else if ([[validitystring substringToIndex:1] isEqualToString:@"D"]) {
                    result=[NSString stringWithFormat:@"0 %@",[MyClass returntitlewithtitle:@"Day"]];
                }
            }else{
                int count=[[validitystring substringFromIndex:1] intValue];
                if ([[validitystring substringToIndex:1] isEqualToString:@"Y"]) {
                    result=[NSString stringWithFormat:@"%i %@",count,count==1?[MyClass returntitlewithtitle:@"Year"]:[MyClass returntitlewithtitle:@"Years"]];
                }else if ([[validitystring substringToIndex:1] isEqualToString:@"M"]) {
                    result=[NSString stringWithFormat:@"%i %@",count,count==1?[MyClass returntitlewithtitle:@"Month"]:[MyClass returntitlewithtitle:@"Months"]];
                }else if ([[validitystring substringToIndex:1] isEqualToString:@"W"]) {
                    result=[NSString stringWithFormat:@"%i %@",count,count==1?[MyClass returntitlewithtitle:@"Week"]:[MyClass returntitlewithtitle:@"Weeks"]];
                }else if ([[validitystring substringToIndex:1] isEqualToString:@"D"]) {
                    result=[NSString stringWithFormat:@"%i %@",count,count==1?[MyClass returntitlewithtitle:@"Day"]:[MyClass returntitlewithtitle:@"Days"]];
                }
            }
        }else{
            if ([[validitystring substringFromIndex:1] isEqualToString:@"00"]) {
                if ([[validitystring substringToIndex:1] isEqualToString:@"Y"]) {
                    result=[NSString stringWithFormat:@"0%@",[MyClass returntitlewithtitle:@"Year"]];
                }else if ([[validitystring substringToIndex:1] isEqualToString:@"M"]) {
                    result=[NSString stringWithFormat:@"0%@",[MyClass returntitlewithtitle:@"Month"]];
                }else if ([[validitystring substringToIndex:1] isEqualToString:@"W"]) {
                    result=[NSString stringWithFormat:@"0%@",[MyClass returntitlewithtitle:@"Week"]];
                }else if ([[validitystring substringToIndex:1] isEqualToString:@"D"]) {
                    result=[NSString stringWithFormat:@"0%@",[MyClass returntitlewithtitle:@"Day"]];
                }
            }else{
                int count=[[validitystring substringFromIndex:1] intValue];
                if ([[validitystring substringToIndex:1] isEqualToString:@"Y"]) {
                    result=[NSString stringWithFormat:@"%i%@",count,count==1?[MyClass returntitlewithtitle:@"Year"]:[MyClass returntitlewithtitle:@"Years"]];
                }else if ([[validitystring substringToIndex:1] isEqualToString:@"M"]) {
                    result=[NSString stringWithFormat:@"%i%@",count,count==1?[MyClass returntitlewithtitle:@"Month"]:[MyClass returntitlewithtitle:@"Months"]];
                }else if ([[validitystring substringToIndex:1] isEqualToString:@"W"]) {
                    result=[NSString stringWithFormat:@"%i%@",count,count==1?[MyClass returntitlewithtitle:@"Week"]:[MyClass returntitlewithtitle:@"Weeks"]];
                }else if ([[validitystring substringToIndex:1] isEqualToString:@"D"]) {
                    result=[NSString stringWithFormat:@"%i%@",count,count==1?[MyClass returntitlewithtitle:@"Day"]:[MyClass returntitlewithtitle:@"Days"]];
                }
            }
        }
    }
    
    return result;
}

