+(NSString *) returnfiletypewithfilename:(NSString *)filename
{
    if ([filename rangeOfString:@".png"].location != NSNotFound && [self isMatchingLastCharactersWithString:filename LastCharacters:@".png"]) {
        return @"png";
    }else if ([filename rangeOfString:@".jpg"].location != NSNotFound && [self isMatchingLastCharactersWithString:filename LastCharacters:@".jpg"]) {
        return @"jpg";
    }else if ([filename rangeOfString:@".jpeg"].location != NSNotFound && [self isMatchingLastCharactersWithString:filename LastCharacters:@".jpeg"]) {
        return @"jpeg";
    }else if ([filename rangeOfString:@".pdf"].location != NSNotFound && [self isMatchingLastCharactersWithString:filename LastCharacters:@".pdf"]) {
        return @"pdf";
    }
    return @"";
}

+(BOOL) isMatchingLastCharactersWithString:(NSString *)String LastCharacters:(NSString *)lastcharacters
{
    if ([lastcharacters length]<[String length]) {
        NSString *lastchar= [String substringFromIndex:[String length]-[lastcharacters length]];
        if ([lastchar isEqualToString:lastcharacters]) {
            return TRUE;
        }
    }
    
    return FALSE;
}

+(NSString *) returnMessagePhotoRecordTypeWithURL:(NSString *)url
{
    if ([[self returnfiletypewithfilename:url] isEqualToString:@"pdf"]) {
        return @"pdf";
    }
    return @"image";
}

+(UIImage *) returnPDFFirstPageImageWithPDFData:(NSData *)pdfData
{
    CFDataRef myPDFData = (__bridge CFDataRef)pdfData;
    CGDataProviderRef provider = CGDataProviderCreateWithCFData(myPDFData);
    CGPDFDocumentRef SourcePDFDocument = CGPDFDocumentCreateWithProvider(provider);
    //size_t numberOfPages = CGPDFDocumentGetNumberOfPages(SourcePDFDocument);
    
    float scaleFactor=1.0;
    //for(int currentPage = 1; currentPage <= numberOfPages; currentPage ++ )
    //{
        CGPDFPageRef SourcePDFPage = CGPDFDocumentGetPage(SourcePDFDocument, 1);
        CGPDFPageRetain(SourcePDFPage);
        CGRect sourceRect = CGPDFPageGetBoxRect(SourcePDFPage, kCGPDFMediaBox);
        UIGraphicsBeginImageContext(CGSizeMake(sourceRect.size.width*scaleFactor,sourceRect.size.height*scaleFactor));
        CGContextRef currentContext = UIGraphicsGetCurrentContext();
        CGContextSetInterpolationQuality(currentContext, kCGInterpolationHigh);
        CGContextTranslateCTM(currentContext, 0.0, sourceRect.size.height*scaleFactor); //596,842 //640×960,
        CGContextScaleCTM(currentContext, scaleFactor, -scaleFactor);
        
        CGContextDrawPDFPage (currentContext, SourcePDFPage); // draws the page in the graphics context
        
        UIImage *image = UIGraphicsGetImageFromCurrentImageContext();
        UIGraphicsEndImageContext();
    
    return image;
}

+(BOOL) isValidPDFWithData:(NSData *)data
{
    CGDataProviderRef provider = CGDataProviderCreateWithCFData((__bridge CFDataRef)data);
    CGPDFDocumentRef document = CGPDFDocumentCreateWithProvider(provider);

    if (document == nil) {
        return NO;
    }
    return YES;
}

