+(NSString *) returnLevelGradeLessonwithClassScheduleRecord:(ClassScheduleRecord *)classschedulerecord
{
//    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    //GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSMutableArray *levelarray=[[NSMutableArray alloc]init];
    
    //CenterSettings *centersettingsobject=[MyClass returnCenterSettingswithCenterkey:globalvariables.centerrecord.centerkey];
    if ([MyClass isEyeLevelMathWithSubject:classschedulerecord.subject]) {
        //if ([MyClass stringcontainscharacterwithstring:classschedulerecord.subject character:@"Math"]) {
            if ([classschedulerecord.levelctm isEqualToString:@""] && ![classschedulerecord.levelmain isEqualToString:@""]) {
                [levelarray addObject:[NSString stringWithFormat:@"B%@",classschedulerecord.levelmain]];
            }else if (![classschedulerecord.levelctm isEqualToString:@""] && ![classschedulerecord.levelmain isEqualToString:@""]) {
                [levelarray addObject:[NSString stringWithFormat:@"B%@C%@",classschedulerecord.levelmain,classschedulerecord.levelctm]];
            }
            
            if ([classschedulerecord.type isEqualToString:@"student"]) {
                Student *obj=[MyClass returnstudentwithstudentkey:classschedulerecord.studentkey];
                if (obj.grade && ![obj.grade isEqualToString:@""]) {
                    [levelarray addObject:obj.grade];
                }
            }else{
                Lead *obj=[MyClass returnleadwithleadkey:classschedulerecord.studentkey];
                if (obj.grade && ![obj.grade isEqualToString:@""]) {
                    [levelarray addObject:obj.grade];
                }
            }
        //}
    }else{
        if (![classschedulerecord.levelmain isEqualToString:@""]) {
            [levelarray addObject:classschedulerecord.levelmain];
        }
        
        if ([classschedulerecord.type isEqualToString:@"student"]) {
            Student *obj=[MyClass returnstudentwithstudentkey:classschedulerecord.studentkey];
            if (obj.grade && ![obj.grade isEqualToString:@""] && ![obj.grade isEqualToString:@"NA"]) {
                [levelarray addObject:obj.grade];
            }
        }else{
            Lead *obj=[MyClass returnleadwithleadkey:classschedulerecord.studentkey];
            if (obj.grade && ![obj.grade isEqualToString:@""] && ![obj.grade isEqualToString:@"NA"]) {
                [levelarray addObject:obj.grade];
            }
        }
    }
    
    NSString *lessondescription=[self getLessonDescriptionWithLessonNumber:classschedulerecord.lesson subject:classschedulerecord.subject];
    
    if(![lessondescription isEqualToString:[self returntitlewithtitle:@"NA"]] && ![classschedulerecord.lesson isEqualToString:@""]){
        [levelarray addObject:[NSString stringWithFormat:@"#%@",lessondescription]];
    }
    
    return [levelarray componentsJoinedByString:@"/"];
}

+(NSString *) getLessonDescriptionWithLessonNumber:(NSString *)lesson subject:(NSString *)subject
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
 
    if(!globalvariables.centerrecord.enablelessonnumber){
        return [self returntitlewithtitle:@"NA"];
    }
    
    NSMutableDictionary *lessonnumberdict=((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:subject centerkey:globalvariables.centerrecord.centerkey]).lessonnumberDict;
    
    if (lessonnumberdict.count==0) {
        return [self returntitlewithtitle:@"NA"];
    }
    
    
    if(globalvariables.centerrecord.lessonnumbermode==2){
        return lesson;
    }else{
        if ([lesson isEqualToString:@""]){
            return [self returntitlewithtitle:@"None"];
        }else if ([lesson isEqualToString:@"TBD"]){
            return [self returntitlewithtitle:@"TBD"];
        }
        
        NSMutableDictionary *lessonnumberdict=((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:subject centerkey:globalvariables.centerrecord.centerkey]).lessonnumberDict;
        NSMutableArray *itemsArray=lessonnumberdict[@"noteset1"];
        NSInteger index = [lesson integerValue];
        if(index<=0){
            return lesson;
        }
        
        NSString *lessondesc=itemsArray[index-1];
        if ([lessondesc isEqualToString:@""]) {
            return lesson;
        }else{
            return [NSString stringWithFormat:@"%@-%@",lesson,lessondesc];
        }
        
    }
}

+(NSString *)createSHA512:(NSString *)string
{
    const char *cstr = [string cStringUsingEncoding:NSUTF8StringEncoding];
    NSData *data = [NSData dataWithBytes:cstr length:string.length];
    uint8_t digest[CC_SHA512_DIGEST_LENGTH];
    CC_SHA512(data.bytes, (unsigned int)data.length, digest);
    NSMutableString* output = [NSMutableString  stringWithCapacity:CC_SHA512_DIGEST_LENGTH * 2];
    for(int i = 0; i < CC_SHA512_DIGEST_LENGTH; i++)
        [output appendFormat:@"%02x", digest[i]];
    return output;
}

+(NSString *) generatechecksumwithunixtimestamp:(NSString *)unixtimestamp
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    NSString *password=[self createSHA512:globalvariables.password];
    return [self createSHA512:[NSString stringWithFormat:@"%@%@%@",globalvariables.username,password,unixtimestamp]];
}

+(NSString *) getunixtimestamp
{
//    return [NSString stringWithFormat:@"%lld",(long long)([[NSDate date] timeIntervalSince1970] * 1000.0)];
    
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    NSString *unixtimestamp=@"";
    NSTimeInterval timeDiff = [[NSDate date] timeIntervalSinceDate:globalvariables.lastunixtimestampreceivedtime];
    if (!globalvariables.lastunixtimestampreceivedtime || timeDiff > 600.0) {
        NSString *strURL=[NSString stringWithFormat:@"%@?action=getunixtimestamp",globalvariables.generalphpfullpath];
        strURL=[MyClass addgetparameterswithurl:strURL includeUnixtimestamp:NO];
        
        __block BOOL result=FALSE;
        __block NSDictionary *jsonreturned;
        
        dispatch_semaphore_t semaphore = dispatch_semaphore_create(0);
        NSURLSession *session = [NSURLSession sharedSession];
        [[session dataTaskWithURL:[NSURL URLWithString:[MyClass dcurlstring:[strURL stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLQueryAllowedCharacterSet]]]] completionHandler:^(NSData *data, NSURLResponse *response, NSError *error) {
            if (!error) {
                result=TRUE;
                jsonreturned=[NSJSONSerialization JSONObjectWithData:data options:(kNilOptions) error:nil];
            }
            dispatch_semaphore_signal(semaphore);
        }] resume];
        dispatch_semaphore_wait(semaphore, DISPATCH_TIME_FOREVER);
            
        if(result){
            unixtimestamp= jsonreturned[@"content"];
            globalvariables.lastunixtimestampreceived=[unixtimestamp longLongValue];
            globalvariables.lastunixtimestampreceivedtime=[NSDate date];
        }
//        NSLog(@"unixtimestamp-r %@ %f",unixtimestamp,[t1 timeIntervalSinceNow]);
    } else {
        long long offset=[globalvariables.lastunixtimestampreceivedtime timeIntervalSinceNow]*1000.0;
        unixtimestamp=[NSString stringWithFormat:@"%lld",(globalvariables.lastunixtimestampreceived-offset)];
//        NSLog(@"unixtimestamp-c %@ %f",unixtimestamp,[t1 timeIntervalSinceNow]);
    }
    
    return unixtimestamp;
}

