+(NSString *) addgetparameterswithurl:(NSString *)url includeUnixtimestamp:(BOOL)includeunixtimestamp
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    NSString *unixtimestamp=includeunixtimestamp?[self getunixtimestamp]:@"";
    NSString *resulturl=url;
    
    NSRange range=[url rangeOfString:@"loginname="];
    if (range.location == NSNotFound) {
        resulturl=[NSString stringWithFormat:@"%@&loginname=%@",resulturl,globalvariables.username];
    }
    
    range=[url rangeOfString:@"app="];
    if (range.location == NSNotFound) {
        resulturl=[NSString stringWithFormat:@"%@&app=%@",resulturl,@"icenter"];
    }
    
    range=[url rangeOfString:@"&os="];
    if (range.location == NSNotFound) {
        resulturl=[NSString stringWithFormat:@"%@&os=%@",resulturl,@"ios"];
    }
    
    range=[url rangeOfString:@"build="];
    if (range.location == NSNotFound) {
        resulturl=[NSString stringWithFormat:@"%@&build=%@",resulturl,[[[NSBundle mainBundle] infoDictionary] objectForKey:@"CFBundleVersion"]];
    }
    
    range=[url rangeOfString:@"appid="];
    if (range.location == NSNotFound) {
        resulturl=[NSString stringWithFormat:@"%@&appid=%@",resulturl,[[NSBundle mainBundle] bundleIdentifier]];
    }
    
    range=[url rangeOfString:@"lang="];
    if (range.location == NSNotFound) {
        resulturl=[NSString stringWithFormat:@"%@&lang=%@",resulturl,[MyClass returnlanguagecode]];
    }
    
    range=[url rangeOfString:@"centerkey="];
    if (range.location == NSNotFound) {
        resulturl=[NSString stringWithFormat:@"%@&centerkey=%@",resulturl,globalvariables.centerrecord.centerkey];
    }
    
    resulturl=[NSString stringWithFormat:@"%@&unixtimestamp=%@&checksum=%@",resulturl,unixtimestamp,[MyClass generatechecksumwithunixtimestamp:unixtimestamp]];
    
    return resulturl;
}

+(NSMutableDictionary *) addchecksumparameterwithdictionary:(NSMutableDictionary *)dict
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    NSString *unixtimestamp=[self getunixtimestamp];

    if (![dict valueForKey:@"loginname"]) {
        [dict setValue:globalvariables.username forKey:@"loginname"];
    }
    
    if (![dict valueForKey:@"app"]) {
        [dict setValue:@"icenter" forKey:@"app"];
    }
    
    if (![dict valueForKey:@"os"]) {
        [dict setValue:@"ios" forKey:@"os"];
    }
    
    if (![dict valueForKey:@"build"]) {
        [dict setValue:[[[NSBundle mainBundle] infoDictionary] objectForKey:@"CFBundleVersion"] forKey:@"build"];
    }
    
    if (![dict valueForKey:@"appid"]) {
        [dict setValue:[[NSBundle mainBundle] bundleIdentifier] forKey:@"appid"];
    }
    
    if (![dict valueForKey:@"lang"]) {
        [dict setValue:[MyClass returnlanguagecode] forKey:@"lang"];
    }
    
    if (![dict valueForKey:@"centerkey"]) {
        [dict setValue:globalvariables.centerrecord.centerkey forKey:@"centerkey"];
    }
    
    [dict setValue:unixtimestamp forKey:@"unixtimestamp"];
    [dict setValue:[MyClass generatechecksumwithunixtimestamp:unixtimestamp] forKey:@"checksum"];

    return dict;
}

+(void) callMultipartPOSTwithDict:(NSDictionary *)dict photoArray:(NSMutableArray *)photoarray completionBlock:(void (^)(id responseObject, NSError *error))completionBlock{
    
//    NSLog(@"callMultipart - %@",dict);
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSMutableDictionary *newdict=[[NSMutableDictionary alloc]init];
    for (NSString* key in dict) {
        [newdict setValue:dict[key] forKey:key];
    }
    newdict=[self addchecksumparameterwithdictionary:newdict];

    NSString *urlString=[NSString stringWithFormat:@"%@",globalvariables.generalphpfullpath];

    NSMutableURLRequest *request = [[NSMutableURLRequest alloc] init] ;
    [request setURL:[NSURL URLWithString:urlString]];
    [request setHTTPMethod:@"POST"];

    NSMutableData *body = [NSMutableData data];

    NSString *boundary = @"---------------------------14737809831466499882746641449";
    NSString *contentType = [NSString stringWithFormat:@"multipart/form-data; boundary=%@", boundary];
    [request addValue:contentType forHTTPHeaderField:@"Content-Type"];
    [body appendData:[@"\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
    
    //parameters
    for (NSString* key in newdict) {
        if ([newdict[key] isKindOfClass:[NSArray class]]) {
            NSArray *rgarray=newdict[key];
            for (int i=0; i<rgarray.count; i++) {
                NSDictionary *d=[rgarray objectAtIndex:i];
                for (NSString *dkey in d) {
                    if([d[dkey] isKindOfClass:[NSArray class]]){
                        NSArray *rgarray2=d[dkey];
                        for (int j=0; j<rgarray2.count; j++){
                            NSDictionary *d2=[rgarray2 objectAtIndex:j];
                            for(NSString *dkey2 in d2){
                                [body appendData:[[NSString stringWithFormat:@"--%@\r\n", boundary] dataUsingEncoding:NSUTF8StringEncoding]];
                                [body appendData:[[NSString stringWithFormat:@"Content-Disposition: form-data; name=\"%@[%d][%@][%d][%@]\"\r\n\r\n",key,i,dkey,j,dkey2] dataUsingEncoding:NSUTF8StringEncoding]];
                                [body appendData:[d2[dkey2] dataUsingEncoding:NSUTF8StringEncoding]];
                                [body appendData:[@"\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
                                
                            }
                        }
                        
                    }else{
                        [body appendData:[[NSString stringWithFormat:@"--%@\r\n", boundary] dataUsingEncoding:NSUTF8StringEncoding]];
                        [body appendData:[[NSString stringWithFormat:@"Content-Disposition: form-data; name=\"%@[%d][%@]\"\r\n\r\n",key,i,dkey] dataUsingEncoding:NSUTF8StringEncoding]];
                        [body appendData:[d[dkey] dataUsingEncoding:NSUTF8StringEncoding]];
                        [body appendData:[@"\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
                    }
                }
            }
        }else{
            [body appendData:[[NSString stringWithFormat:@"--%@\r\n", boundary] dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[[NSString stringWithFormat:@"Content-Disposition: form-data; name=\"%@\"\r\n\r\n",key] dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[newdict[key] dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[@"\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
        }
    }
    
    //files
    for(int i=0; i<[photoarray count];i++)
    {
        MessagePhotoRecord *object=[photoarray objectAtIndex:i];
        if ([object.filetype isEqualToString:@"image"]) {
            //NSData *imageData = [[NSData alloc]initWithContentsOfURL:object.internalurl];
            NSData *imageData = [MyClass returnWXCompressDataWithURL:object.internalurl];
            [body appendData:[[NSString stringWithFormat:@"--%@\r\n", boundary] dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[[NSString stringWithFormat:@"Content-Disposition: form-data; name=\"image%d\"; filename=\"abc%d.png\"\r\n",i,i] dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[@"Content-Type: application/octet-stream\r\n\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[NSData dataWithData:imageData]];
            [body appendData:[@"\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
        }else if ([object.filetype isEqualToString:@"pdf"]){
            NSData *pdfData=[[NSData alloc]initWithContentsOfURL:object.internalurl];
            [body appendData:[[NSString stringWithFormat:@"--%@\r\n", boundary] dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[[NSString stringWithFormat:@"Content-Disposition: form-data; name=\"pdf%d\"; filename=\"%@\"\r\n",i,object.filename] dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[@"Content-Type: application/octet-stream\r\n\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[NSData dataWithData:pdfData]];
            [body appendData:[@"\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
        }else if ([object.filetype isEqualToString:@"video"]){
//            NSData *videoData = [[NSData alloc]initWithContentsOfURL:object.internalurl];
            NSData *videoData = [MyClass compressVideoSynchronouslyWithURL:object.internalurl error:nil];
            NSString *fileextension= [[object.internalurl lastPathComponent] substringFromIndex: [[object.internalurl lastPathComponent] length] - 3];
            [body appendData:[[NSString stringWithFormat:@"--%@\r\n", boundary] dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[[NSString stringWithFormat:@"Content-Disposition: form-data; name=\"video%d\"; filename=\"video%d.%@\"\r\n",i,i,fileextension] dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[@"Content-Type: application/octet-stream\r\n\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[NSData dataWithData:videoData]];
            [body appendData:[@"\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
        }else if ([object.filetype isEqualToString:@"audio"]){
            NSData *audioData = [[NSData alloc]initWithContentsOfURL:object.internalurl];
            NSString *fileextension= [[object.internalurl lastPathComponent] substringFromIndex: [[object.internalurl lastPathComponent] length] - 3];
            [body appendData:[[NSString stringWithFormat:@"--%@\r\n", boundary] dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[[NSString stringWithFormat:@"Content-Disposition: form-data; name=\"audio%d\"; filename=\"audio%d.%@\"\r\n",i,i,fileextension] dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[@"Content-Type: application/octet-stream\r\n\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
            [body appendData:[NSData dataWithData:audioData]];
            [body appendData:[@"\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
        }
    }

    // close form
    [body appendData:[[NSString stringWithFormat:@"--%@--\r\n", boundary] dataUsingEncoding:NSUTF8StringEncoding]];
    // set request body
    [request setHTTPBody:body];
    
    __block NSData *returndata;
    __block NSError *returnerror;
    dispatch_semaphore_t semaphore = dispatch_semaphore_create(0);
    [[[NSURLSession sharedSession] dataTaskWithRequest:request completionHandler:^(NSData *data, NSURLResponse *response, NSError *error) {
//        NSString *resString = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
        returndata=data;
        returnerror=error;
        dispatch_semaphore_signal(semaphore);
    }] resume];
    dispatch_semaphore_wait(semaphore, DISPATCH_TIME_FOREVER);
    
    if (completionBlock) {
        completionBlock(returndata,returnerror);
    }
}

