+(NSDate *) returnfirstdayofweekwithdate:(NSDate *)date
{
    NSCalendar *cal = [[NSCalendar alloc] initWithCalendarIdentifier:NSCalendarIdentifierGregorian];

    cal.firstWeekday = 1;// set first week day to Monday
    // 1: Sunday, 2: Monday, ..., 7:Saturday

    NSDate *startOfTheWeek;
    NSTimeInterval interval;
    [cal rangeOfUnit:NSCalendarUnitWeekOfYear
           startDate:&startOfTheWeek
            interval:&interval
             forDate:date];
    
    return startOfTheWeek;
}
+(NSDate *) returnlastdayofweekwithdate:(NSDate *)date
{
    NSCalendar *cal = [[NSCalendar alloc] initWithCalendarIdentifier:NSCalendarIdentifierGregorian];

    cal.firstWeekday = 1;// set first week day to Monday
    // 1: Sunday, 2: Monday, ..., 7:Saturday

    NSDate *startOfTheWeek;
    NSDate *endOfWeek;
    NSTimeInterval interval;
    [cal rangeOfUnit:NSCalendarUnitWeekOfYear
           startDate:&startOfTheWeek
            interval:&interval
             forDate:date];
    //startOfTheWeek holds the beginning of the week

    endOfWeek = [startOfTheWeek dateByAddingTimeInterval:interval - 1];
    // endOfWeek now holds the last second of the last week day

    [cal rangeOfUnit:NSCalendarUnitDay
           startDate:&endOfWeek
            interval:NULL
             forDate:endOfWeek];
    // endOfWeek now holds the beginning of the last week day
    
    return endOfWeek;
}

+(NSDate *) returnfirstdayofmonthwithdate:(NSDate *)date
{
    NSString *datestring=[MyClass convertToNSStringWithNSDate:date ToDateFormat:@"yyyy-MM" Translate:NO];
    datestring=[NSString stringWithFormat:@"%@-01",datestring];
    return [MyClass convertToNSDateWithDate:datestring DateFormat:@"yyyy-MM-dd"];
}

+(NSDate *) returnlastdayofmonthwithdate:(NSDate *)date
{
    NSCalendar* calendar = [NSCalendar currentCalendar];
    NSDateComponents* comps = [calendar components:NSCalendarUnitYear|NSCalendarUnitMonth|NSCalendarUnitWeekOfYear|NSCalendarUnitWeekday fromDate:date]; // Get necessary date components

    // set last of month
    [comps setMonth:[comps month]+1];
    [comps setDay:0];
    NSDate *tDateMonth = [calendar dateFromComponents:comps];
    return tDateMonth;
}

