+(NSMutableArray *) returnDiscountArrayWithEnrollmentRecord2:(EnrollmentRecord *)enrollmentrecord
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSNumberFormatter *formatter = [[NSNumberFormatter alloc]init];
    [formatter setMaximumFractionDigits:globalvariables.centerrecord.noofroundoffdigit];
    [formatter setMinimumFractionDigits:0];
    [formatter setRoundingMode:NSNumberFormatterRoundHalfUp];
    //formatter.numberStyle = NSNumberFormatterCurrencyStyle;
    [formatter setCurrencySymbol:@""];
    
    float balance=[enrollmentrecord.tuitionfee floatValue];
    float totalpaid=[enrollmentrecord.paid floatValue];
    float discount;
    float totaldiscount=[enrollmentrecord.tuitionfee floatValue]+[enrollmentrecord.enrollmentfee floatValue]+[enrollmentrecord.latefee floatValue]-[enrollmentrecord.totalfee floatValue];
    float remainingdiscount=totaldiscount;
    NSMutableArray *discountarray=[[NSMutableArray alloc]init];
    for (int i=0; i<enrollmentrecord.promotiondiscountrecords.count; i++) {
        MarketingRecord *object=[enrollmentrecord.promotiondiscountrecords objectAtIndex:i];
        
        if (![object.promotionfixeddiscount isEqualToString:@""]) {
            discount=[object.promotionfixeddiscount floatValue]*(!object.perclassorquantity?1:[enrollmentrecord.noofclass integerValue]);
            
            float formatteddiscount=[[formatter stringFromNumber:[NSNumber numberWithFloat:discount]] floatValue];
            if (remainingdiscount-formatteddiscount<0) {
                discount=remainingdiscount;
            }
            remainingdiscount-=formatteddiscount;
            [discountarray addObject:[[DiscountRecord alloc]initDiscountRecordRecordWithDiscount:[formatter stringFromNumber:[NSNumber numberWithFloat:discount*-1]] Description:[NSString stringWithFormat:@"%@ ($%@)",object.description,object.promotionfixeddiscount] Description_Chinese:[NSString stringWithFormat:@"%@($%@)",object.description_chinese,object.promotionfixeddiscount]]];
        }else{
            discount=balance*[object.promotionpercentagediscount floatValue]/100;
            float formatteddiscount=[[formatter stringFromNumber:[NSNumber numberWithFloat:discount]] floatValue];
            if (remainingdiscount-formatteddiscount<0) {
                discount=remainingdiscount;
            }
            remainingdiscount-=formatteddiscount;
            [discountarray addObject:[[DiscountRecord alloc]initDiscountRecordRecordWithDiscount:[formatter stringFromNumber:[NSNumber numberWithFloat:discount*-1]] Description:[NSString stringWithFormat:@"%@ (%@%@)",object.description,object.promotionpercentagediscount,@"%"] Description_Chinese:[NSString stringWithFormat:@"%@(%@%@)",object.description_chinese,object.promotionpercentagediscount,@"%"]]];
        }
        
        balance-=discount;
    }
    
    
    float regulardiscount=0;
    if ([enrollmentrecord.oneoffpercentagediscount floatValue]!=0) {
        discount=balance*[enrollmentrecord.oneoffpercentagediscount floatValue]/100;
        float formatteddiscount=[[formatter stringFromNumber:[NSNumber numberWithFloat:discount]] floatValue];
        if (remainingdiscount-formatteddiscount<0) {
            discount=remainingdiscount;
        }
        remainingdiscount-=formatteddiscount;
        balance-=discount;
        regulardiscount+=discount;
    }
    
