+(BOOL) updateUserAccountSettingsWithField:(NSString *)field Value:(NSString *)value
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    //combine arrays
    NSDictionary *dictionary = @{field : value,
                                 @"centerdb" : globalvariables.centerrecord.centerdb,
                                 @"centerkey" : globalvariables.centerrecord.centerkey,
                                 @"postaction" : @"updateuseraccountsettings",
                                 @"updatedby" : globalvariables.username
                                 };
    
    __block BOOL result=FALSE;
    [MyClass callPOSTwithDict:dictionary completionBlock:^(BOOL succeeded, NSData *data) {
        if (succeeded) {
            result= TRUE;
        }
    }];
    
    return result;
}

+ (UIImage *) getThumbnailImageFromVideo:(NSURL *)videoURL
{
    //NSURL *url = [NSURL URLWithString:videoURL];
    AVAsset *asset = [AVAsset assetWithURL:videoURL];
    AVAssetImageGenerator *imageGenerator = [[AVAssetImageGenerator alloc] initWithAsset:asset];
    imageGenerator.appliesPreferredTrackTransform = YES;
    CMTime time = [asset duration];
    time.value = 0;
    CGImageRef imageRef = [imageGenerator copyCGImageAtTime:time actualTime:NULL error:NULL];
    UIImage *thumbnail = [UIImage imageWithCGImage:imageRef];
    CGImageRelease(imageRef);
    return thumbnail;

}

+ (NSURL *) returnInternalURLforNSData:(NSData *)data Filename:(NSString *)filename
{
    NSString* documentsPath = [NSSearchPathForDirectoriesInDomains(NSDocumentDirectory, NSUserDomainMask, YES) objectAtIndex:0];
    NSString *pathfilename=[NSString stringWithFormat:@"%u-%u-%@",arc4random_uniform(9000) + 1000,arc4random_uniform(9000) + 1000,filename];
    NSString* filePath = [documentsPath stringByAppendingPathComponent:@"tmpischool"];
    filePath = [filePath stringByAppendingPathComponent:pathfilename];
    [data writeToFile:filePath atomically:YES];
    NSURL *fileUrl = [NSURL fileURLWithPath:filePath];
    
    return fileUrl;
}


+ (void) clearTmpDirectoryContent
{
    NSString *documentsPath = [NSSearchPathForDirectoriesInDomains(NSDocumentDirectory, NSUserDomainMask, YES) objectAtIndex:0];
    NSString* folderPath = [documentsPath stringByAppendingPathComponent:@"tmpischool"];
    
    if (![[NSFileManager defaultManager] fileExistsAtPath:folderPath]){
        [[NSFileManager defaultManager] createDirectoryAtPath:folderPath withIntermediateDirectories:NO attributes:nil error:nil];
    }
    
    NSError *error = nil;
    for (NSString *file in [[NSFileManager defaultManager] contentsOfDirectoryAtPath:folderPath error:&error]) {
        [[NSFileManager defaultManager] removeItemAtPath:[folderPath stringByAppendingPathComponent:file] error:&error];
    }
}

+(CGFloat) returnMaximumValueWithAValue:(CGFloat)aValue BValue:(CGFloat)bValue
{
    if (aValue>bValue) {
        return aValue;
    }
    return bValue;
}

+(CGFloat) returnMinimumValueWithAValue:(CGFloat)aValue BValue:(CGFloat)bValue
{
    if (aValue<bValue) {
        return aValue;
    }
    return bValue;
}

+(CGSize) wxImageSizeWithImage:(UIImage *)image
{
    CGFloat width=image.size.width;
    CGFloat height=image.size.height;
    
    CGFloat boundary=1280;
    
    if (width < boundary && height < boundary) {
        return  CGSizeMake(width, height);
    }

    // aspect ratio
    CGFloat s = [self returnMaximumValueWithAValue:width BValue:height] / [self returnMinimumValueWithAValue:width BValue:height];
    if (s <= 2) {
        // Set the larger value to the boundary, the smaller the value of the compression
        CGFloat x = [self returnMaximumValueWithAValue:width BValue:height] / boundary;
        if (width > height) {
            width = boundary;
            height = height / x;
        } else {
            height = boundary;
            width = width / x;
        }
    }else{
        // width, height > 1280
        if ([self returnMinimumValueWithAValue:width BValue:height] >= boundary) {
            //boundary = type == .session ? 800 : 1280
            boundary = 1280;
            // Set the smaller value to the boundary, and the larger value is compressed
            CGFloat x = [self returnMinimumValueWithAValue:width BValue:height] / boundary;
            if (width < height) {
                width = boundary;
                height = height / x;
            } else {
                height = boundary;
                width = width / x;
            }
        }
    }
    return  CGSizeMake(width, height);
}

+(NSData *) returnWXCompressDataWithURL:(NSURL *)url
{
    NSData *imageData=[[NSData alloc]initWithContentsOfURL:url];
    if(imageData.length<5000000){
        return imageData;
    }else{
        UIImage *image=[[UIImage alloc]initWithData:imageData];
        CGSize size=[self wxImageSizeWithImage:image];
        UIImage *reImage=[self resizeImageWithImage:image ForSize:size];
        NSData *data=UIImageJPEGRepresentation(reImage, 0.6);
        return data;
    }

}

