+ (NSString *) returnAudioRecordingFileName
{
    // return a formatted string for a file name
    NSDateFormatter *formatter = [[NSDateFormatter alloc] init];
    formatter.dateFormat = @"YYYYMMDD_hhmmssa";
    return [[formatter stringFromDate:[NSDate date]] stringByAppendingString:@".aac"];
}

+ (NSString *) returnDurationWithSecond:(float)durationinsecond
{
    NSInteger minute = durationinsecond/60;
    NSInteger second = (NSInteger)durationinsecond%60;
    return [NSString stringWithFormat:@"%ld:%02ld",(long)minute,(long)second];
}

+ (void) autoSendeReceiptWithClassReceiptArray:(NSMutableArray *)classArray SalesReceiptArray:(NSMutableArray *)salesArray
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    //combine same student items
    NSMutableDictionary *allDict=[[NSMutableDictionary alloc]init];
    NSArray *arrayobject;
    for (int i=0; i<classArray.count; i++) {
        arrayobject=[allDict valueForKey:((ClassReceiptRecord *)[classArray objectAtIndex:i]).studentkey];
        if(arrayobject){
            [[arrayobject objectAtIndex:0] addObject:[classArray objectAtIndex:i]];
        }else{
            [allDict setValue:[[NSArray alloc]initWithObjects:[[NSMutableArray alloc]initWithObjects:[classArray objectAtIndex:i], nil],[[NSMutableArray alloc]init], nil] forKey:((ClassReceiptRecord *)[classArray objectAtIndex:i]).studentkey];
        }
    }
    
    for (int i=0; i<salesArray.count; i++) {
        arrayobject=[allDict valueForKey:((SalesReceiptRecord *)[salesArray objectAtIndex:i]).studentkey];
        if(arrayobject){
            [[arrayobject objectAtIndex:1] addObject:[salesArray objectAtIndex:i]];
        }else{
            [allDict setValue:[[NSArray alloc]initWithObjects:[[NSMutableArray alloc]init],[[NSMutableArray alloc]initWithObjects:[salesArray objectAtIndex:i], nil], nil] forKey:((SalesReceiptRecord *)[salesArray objectAtIndex:i]).studentkey];
        }
    }
    
    for(id key in allDict) {
        NSArray *value = [allDict objectForKey:key];

        NSMutableArray *classdocumentarray=[value objectAtIndex:0];
        NSMutableArray *salesdocumentarray=[value objectAtIndex:1];
        
        NSData *pdfData=[MyClass generateReceiptWithClassReceiptArray:classdocumentarray SalesReceiptArray:salesdocumentarray papersizeoverride:YES combinedocument:YES centerkey:globalvariables.centerrecord.centerkey];
        NSString *filename=[MyClass returnreceiptnumberwithclassreceiptarray:classdocumentarray salesreceiptarray:salesdocumentarray];
        
        OutboxMessageRecord *object=[[OutboxMessageRecord alloc]init];
        object.photoarray=[[NSMutableArray alloc]init];
        object.messageenglish=[NSString stringWithFormat:@"%@ %@",[MyClass returntitlewithtitle:@"Receipt" language:@"English"],filename];
        object.messagechinese=[NSString stringWithFormat:@"%@%@",[MyClass returntitlewithtitle:@"Receipt" language:@"Chinese"],filename];
        object.recipienttype=@"Student";
        object.recipientgroup=[[RecipientGroupRecord alloc]init];
        object.recipientgroup.individualarray=[[NSMutableArray alloc]initWithObjects:key,nil];
        object.messagetype=[NSString stringWithFormat:@"e%@",@"Receipt"];
        
        NSURL *interalurl=[MyClass returnInternalURLforNSData:pdfData Filename:[NSString stringWithFormat:@"%@.pdf", object.messageenglish]];
        [object.photoarray addObject:[[MessagePhotoRecord alloc]initMessagePhotoRecordwithMessagePhotoKey:nil MessagePhotoURL:nil ImageView:nil Width:0 Height:0 FileType:@"pdf" InternalURL:interalurl FileName:[NSString stringWithFormat:@"%@.pdf", object.messageenglish] ThumbnailURL:@""]];
        MessagePopoverViewController *viewController = [[MessagePopoverViewController alloc]init];
        [viewController sendMessageWithOutBoxMessage:object];
    }
}

+(BOOL) isEyeLevelMathWithSubject:(NSString *)subjectcode
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    if ([MyClass isfcbrandwithfcbrandsettings:((CenterSettings *)[MyClass returnCenterSettingswithCenterkey:globalvariables.centerrecord.centerkey]).fcbrand fcbrand:@"eyelevel"]) {
        SubjectRecord *record=[self returnsubjectinformationwithsubject_shortname:subjectcode centerkey:globalvariables.centerrecord.centerkey];
        if (record) {
            return [self stringcontainscharacterwithstring:record.fcsubject character:@"EL Math"];
        }
    }
