+(NSString *) returnLevelWithSubject:(NSString *)subject Levelmain:(NSString *)levelmain Levelctm:(NSString *)levelctm
{
    NSMutableArray *levelarray=[[NSMutableArray alloc]init];
 
    if ([self isEyeLevelMathWithSubject:subject]) {
        if ([levelctm isEqualToString:@""] && ![levelmain isEqualToString:@""]) {
            [levelarray addObject:[NSString stringWithFormat:@"B%@", levelmain]];
        }else if (![levelctm isEqualToString:@""] && ![levelmain isEqualToString:@""]) {
            [levelarray addObject:[NSString stringWithFormat:@"B%@C%@",levelmain,levelctm]];
        }
    }else{
        [levelarray addObject:[levelmain isEqualToString:@"TBD"]?[MyClass returntitlewithtitle:@"TBD"]:levelmain];
    }
    
    
    return [levelarray componentsJoinedByString:@"/"];
}

+(NSMutableArray *) returnLevelOnlyArrayWithSubject:(NSString *)subject
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSMutableArray *levelarray=[[NSMutableArray alloc]init];
    NSMutableArray *subjectlevelarray=((SubjectRecord *)[self returnsubjectinformationwithsubject_shortname:subject centerkey:globalvariables.centerrecord.centerkey]).levelArray;
    
    for (int i=0; i<subjectlevelarray.count; i++) {
        LevelRecord *obj=[subjectlevelarray objectAtIndex:i];
        [levelarray addObject:obj.level];
    }
    return levelarray;
}

+(NSString *) returnLevelLessonWithClassRecord:(ClassRecord *)classrecord
{
    NSMutableArray *levelarray=[[NSMutableArray alloc]init];
 
    if ([self isEyeLevelMathWithSubject:classrecord.subject]) {
        if ([classrecord.levelctm isEqualToString:@""] && ![classrecord.levelmain isEqualToString:@""]) {
            [levelarray addObject:[NSString stringWithFormat:@"B%@", classrecord.levelmain]];
        }else if (![classrecord.levelctm isEqualToString:@""] && ![classrecord.levelmain isEqualToString:@""]) {
            [levelarray addObject:[NSString stringWithFormat:@"B%@C%@",classrecord.levelmain,classrecord.levelctm]];
        }
    }else{
        [levelarray addObject:[classrecord.levelmain isEqualToString:@"TBD"]?[MyClass returntitlewithtitle:@"TBD"]:classrecord.levelmain];
    }
    
    NSString *lessondescription=[self getLessonDescriptionWithLessonNumber:classrecord.lesson subject:classrecord.subject];
    
    if(![lessondescription isEqualToString:[self returntitlewithtitle:@"NA"]] && ![classrecord.lesson isEqualToString:@""]){
        [levelarray addObject:lessondescription];
    }
    
    
    return [levelarray componentsJoinedByString:@"/"];
}

+(void) submitDocumentSendingRequestWithType:(NSString *)type documentArray:(NSArray *)documentarray
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    //combine arrays
    NSDictionary *dictionary = @{@"centerdb" : globalvariables.centerrecord.centerdb,
                                 @"centerkey" : globalvariables.centerrecord.centerkey,
                                 @"type" : type,
                                 @"postaction" : @"submitdocumentsendrequest",
                                 @"documentarray" : documentarray
    };
    
    [self callPOSTwithDict:dictionary completionBlock:^(BOOL succeeded, NSData *data) {
        if (succeeded) {
            NSString *resString = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
            NSLog(@"%@",resString);
        }
    }];
}

+(NSString *) returnLessonWithSubject:(NSString *)subject StartingLesson:(NSString *)startinglesson Offset:(NSInteger)offset
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    
    if ([startinglesson isEqualToString:@""]) {
        return @"";
    }
    
    if(globalvariables.centerrecord.lessonnumbermode==2){
        NSArray *startinglessonarray=[startinglesson componentsSeparatedByString:@"/"];
        
        NSString *ln0String;
        NSString *ln1String;
        NSString *ln2String;
        NSString *ln3String;
        NSMutableDictionary *lessonnumberdict=((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:subject centerkey:globalvariables.centerrecord.centerkey]).lessonnumberDict;
        NSMutableArray *ln2Array=lessonnumberdict[@"noteset1"];
        NSMutableArray *ln3Array=lessonnumberdict[@"noteset2"]?lessonnumberdict[@"noteset2"]:[[NSMutableArray alloc]init];
        
        ln0String=startinglessonarray[0];
        ln1String=startinglessonarray[1];
        ln2String=startinglessonarray[2];
        ln3String=startinglessonarray[3];
        
        if(![ln2String isEqualToString:@"TBD"]){
            NSInteger ln2Index=[ln2String integerValue]-1;
            if(ln2Index+offset<ln2Array.count){
                ln2String=[@(ln2Index+offset+1) stringValue];
            }else{
                ln2String=@"TBD";
            }
        }
        
        if(![ln3String isEqualToString:@"TBD"]){
            NSInteger ln3Index=[ln3String integerValue]-1;
            if(ln3Index+offset<ln3Array.count){
                ln3String=[@(ln3Index+offset+1) stringValue];
            }else{
                ln3String=@"TBD";
            }
        }
        
        return [NSString stringWithFormat:@"%@/%@/%@/%@",ln0String,ln1String,ln2String,ln3String];
    }else{
        NSMutableDictionary *lessonnumberdict=((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:subject centerkey:globalvariables.centerrecord.centerkey]).lessonnumberDict;
        NSMutableArray *ln2Array=lessonnumberdict[@"noteset1"];
        NSString *ln2String=startinglesson;
        if(![ln2String isEqualToString:@"TBD"]){
            NSInteger ln2Index=[ln2String integerValue]-1;
            if(ln2Index+offset<ln2Array.count){
                ln2String=[@(ln2Index+offset+1) stringValue];
            }else{
                ln2String=@"TBD";
            }
        }
        return ln2String;
    }

}

+(NSArray *) returnLessonNumberArrayWithSubject:(NSString *)subject
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    if (!globalvariables.centerrecord.enablelessonnumber) {
        return nil;
    }
    
    NSMutableDictionary *lessonnumberdict=((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:subject centerkey:globalvariables.centerrecord.centerkey]).lessonnumberDict;
    if (lessonnumberdict.count==0) {
        return nil;
    }
    
    if(globalvariables.centerrecord.lessonnumbermode==2){
        NSMutableArray *ln0Array=[[NSMutableArray alloc]initWithObjects:@"A",@"B",@"NA", nil];
        NSMutableArray *ln1Array=[NSMutableArray arrayWithArray:[((CenterSettings *)[MyClass returnCenterSettingswithCenterkey:globalvariables.centerrecord.centerkey]).grade componentsSeparatedByString:@","]];
        
        NSMutableArray *ln2Array=lessonnumberdict[@"noteset1"];
        NSMutableArray *ln3Array=lessonnumberdict[@"noteset2"]?lessonnumberdict[@"noteset2"]:[[NSMutableArray alloc]init];;
        
        return [[NSArray alloc]initWithObjects:ln0Array,ln1Array,ln2Array,ln3Array, nil];
    }else{
        NSMutableArray *ln2Array=lessonnumberdict[@"noteset1"];
        return ln2Array;
    }
}

+(NSString *) returnClassPeriodWithStartTime:(NSString *)starttime subject:(NSString *)subject type:(NSString *)type
{
    NSRange range=[starttime rangeOfString:@":"];
    if (range.location==NSNotFound) {
        return [MyClass returntitlewithtitle:starttime];
    }
    
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    SubjectRecord *subjectrecord=[MyClass returnsubjectinformationwithsubject_shortname:subject centerkey:globalvariables.centerrecord.centerkey];
    NSString *duration=@"";
    if ([type isEqualToString:@"class"]) {
        duration=subjectrecord.classduration;
    }else if ([type isEqualToString:@"trial"]){
        duration=subjectrecord.classduration_trial;
    }else if ([type isEqualToString:@"assessment"]){
        duration=subjectrecord.classduration_assessment;
    }
    NSString *endtime=[MyClass convertToNSStringWithNSDate:[[MyClass convertToNSDateWithDate:starttime DateFormat:@"HH:mm"] dateByAddingTimeInterval:[subjectrecord.classduration integerValue]*60] DateFormat:@"HH:mm"];
    
    return [NSString stringWithFormat:@"%@-%@",starttime,endtime];
}

+(NSString *) returnClassPeriodWithStartTime:(NSString *)starttime duration:(NSString *)duration
{
    NSRange range=[starttime rangeOfString:@":"];
    if (range.location==NSNotFound) {
        return [MyClass returntitlewithtitle:starttime];
    }
    
    NSString *endtime=[MyClass convertToNSStringWithNSDate:[[MyClass convertToNSDateWithDate:starttime DateFormat:@"HH:mm"] dateByAddingTimeInterval:[duration integerValue]*60] DateFormat:@"HH:mm"];
    
    return [NSString stringWithFormat:@"%@-%@",starttime,endtime];
}

+(BOOL) showLessonParameterWithSubject:(NSString *)subject
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    if(!globalvariables.centerrecord.enablelessonnumber){
        return NO;
    }
    
    if([subject isEqualToString:@"Multiple"]){
        return NO;
    }
    
    NSMutableDictionary *lessonnumberdict=((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:subject centerkey:globalvariables.centerrecord.centerkey]).lessonnumberDict;
    
    if (lessonnumberdict.count==0) {
        return NO;
    }
    return YES;
}


+(NSString *) returnLessonDescriptionWithClassScheduleRecords:(NSMutableArray *)classschedulerecords
{
    NSMutableArray *lessons=[[NSMutableArray alloc]init];
    ClassScheduleRecord *obj;
    for(int i=0;i<classschedulerecords.count;i++){
        obj=[classschedulerecords objectAtIndex:i];
        if (![lessons containsObject:obj.lesson]) {
            [lessons addObject:obj.lesson];
        }
        if(lessons.count>1){
            break;
        }
    }
    
    if (lessons.count>1){
        return [MyClass returntitlewithtitle:@"Multiple"];
    }else if ([[lessons firstObject] isEqualToString:@""]){
        return [MyClass returntitlewithtitle:@"None"];
    }else{
        return [MyClass getLessonDescriptionWithLessonNumber:[lessons firstObject] subject:obj.subject];
    }
}

+(NSString *) returnLessonNumberWithClassScheduleRecords:(NSMutableArray *)classschedulerecords
{
    NSMutableArray *lessons=[[NSMutableArray alloc]init];
    ClassScheduleRecord *obj;
    for(int i=0;i<classschedulerecords.count;i++){
        obj=[classschedulerecords objectAtIndex:i];
        if (![lessons containsObject:obj.lesson]) {
            [lessons addObject:obj.lesson];
        }
        if(lessons.count>1){
            break;
        }
    }
    
    if (lessons.count>1){
        return @"Multiple";
    }else{
        return [lessons firstObject];
    }
}

