+(NSString *) returnCouponeffectivefromSetting:(NSString *)effectivefrom
{
    if([effectivefrom rangeOfString:@"-"].location!=NSNotFound){
        return [MyClass convertDateFormatWithDate:effectivefrom FromDateFormat:@"yyyy-MM-dd" ToDateFormat:@"dd-MMM-yyyy" Translate:YES];
    }else if ([effectivefrom isEqualToString:@"0"]){
        return [MyClass returntitlewithtitle:@"Immediate"];
    }else if ([effectivefrom isEqualToString:@"1"]){
        return [MyClass returnreplacedtitlewithtitle:@"%@1 day after issue" replacementarray:@[effectivefrom]];
    }else{
        return [MyClass returnreplacedtitlewithtitle:@"%@1 days after issue" replacementarray:@[effectivefrom]];
    }
}

+(BOOL) isReservedDay:(NSString *)classdate
{
    if (classdate) {
        GlobalVariables *globalvariables=[GlobalVariables singleObj];

        NSString *centerday=[globalvariables.centerdaydictionary objectForKey:[NSString stringWithFormat:@"%@#%@",classdate,globalvariables.centerrecord.centerkey]];
        if (centerday && [centerday isEqualToString:@"R"]) {
            return YES;
        }
    }
    return NO;
    
}

+(NSString *) returnCouponeffectivetoSetting:(NSString *)effectiveto
{
    if ([effectiveto isEqualToString:@""]){
        return [MyClass returntitlewithtitle:@"Never"];
    }else if([effectiveto rangeOfString:@"-"].location!=NSNotFound){
        return [MyClass convertDateFormatWithDate:effectiveto FromDateFormat:@"yyyy-MM-dd" ToDateFormat:@"dd-MMM-yyyy" Translate:YES];
    }else if ([effectiveto isEqualToString:@"1"]){
        return [MyClass returnreplacedtitlewithtitle:@"%@1 day" replacementarray:@[effectiveto]];
    }else{
        return [MyClass returnreplacedtitlewithtitle:@"%@1 days" replacementarray:@[effectiveto]];
    }
}

