+(NSString *) returnconditionnamewitharray:(OutboxMessageRecord *)workingMessage condition:(NSString *)condition
{
    GlobalVariables *globalvariables=[GlobalVariables singleObj];
    NSMutableArray *tmparray=[[NSMutableArray alloc]init];
    
    NSMutableArray *array;//=workingMessage.recipientgroup[@""];
    if([condition isEqualToString:@"Individual"]){
        array=workingMessage.recipientgroup.individualarray;
    }else if([condition isEqualToString:@"Subject"]){
        array=workingMessage.recipientgroup.subjectarray;
    }else if([condition isEqualToString:@"Instructor"]){
        array=workingMessage.recipientgroup.instructorarray;
    }else if([condition isEqualToString:@"ClassDate"]){
        array=workingMessage.recipientgroup.classdatearray;
    }else if([condition isEqualToString:@"Grade"]){
        array=workingMessage.recipientgroup.gradearray;
    }else if([condition isEqualToString:@"StudentStatus"]){
        array=workingMessage.recipientgroup.studentstatusarray;
    }else if([condition isEqualToString:@"LeadStatus"]){
        array=workingMessage.recipientgroup.leadstatusarray;
    }else if([condition isEqualToString:@"Drop"]){
        array=workingMessage.recipientgroup.droparray;
    }else if([condition isEqualToString:@"StaffGroup"]){
        array=workingMessage.recipientgroup.staffgrouparray;
    }else if([condition isEqualToString:@"PaymentStatus"]){
        array=workingMessage.recipientgroup.paymentstatusarray;
    }else if([condition isEqualToString:@"Product"]){
        array=workingMessage.recipientgroup.productarray;
    }
    
    if (array.count==0) {
        return [MyClass returntitlewithtitle:@"Any"];
    }/*else if (array.count>1){
      return [NSString stringWithFormat:@"%@(%lu)",[MyClass returntitlewithtitle:@"Multiple"],(unsigned long)array.count];
      }*/else{
          if ([condition isEqualToString:@"Individual"]) {
              if ([workingMessage.recipienttype isEqualToString:@"Student"]) {
                  for (int i=0; i<array.count; i++) {
                      [tmparray addObject:[MyClass returnStudentnameWithStudentkey:[array objectAtIndex:i] option:@"full"]];
                  }
                  return [tmparray componentsJoinedByString:@" | "];
              }else if ([workingMessage.recipienttype isEqualToString:@"Lead"]){
                  for (int i=0; i<array.count; i++) {
                      [tmparray addObject:[MyClass returnLeadnameWithLeadkey:[array objectAtIndex:i] option:@"full"]];
                  }
                  return [tmparray componentsJoinedByString:@" | "];
              }else{
                  for (int i=0; i<array.count; i++) {
                      [tmparray addObject:[MyClass returnstaffnamewithusername:[array objectAtIndex:i] firstorfullname:@"full"]];
                  }
                  return [tmparray componentsJoinedByString:@" | "];
              }
          }else if ([condition isEqualToString:@"Subject"]) {
              for (int i=0; i<array.count; i++) {
                  [tmparray addObject:[MyClass returnsubjectnamewithsubject_shortname:[array objectAtIndex:i] centerkey:globalvariables.centerrecord.centerkey]];
              }
              return [tmparray componentsJoinedByString:@" | "];
          }else if ([condition isEqualToString:@"Instructor"]) {
              for (int i=0; i<array.count; i++) {
                  [tmparray addObject:[MyClass returnstaffnamewithusername:[array objectAtIndex:i] firstorfullname:@"full"]];
              }
              return [tmparray componentsJoinedByString:@" | "];
          }else if ([condition isEqualToString:@"ClassDate"]) {
              for (int i=0; i<array.count; i++) {
                  [tmparray addObject:[MyClass returndateformatwithdate:[array objectAtIndex:i] dateformat:@"dd-MMM-yyyy"]];
              }
              return [tmparray componentsJoinedByString:@" | "];
          }else if ([condition isEqualToString:@"Grade"]) {
              for (int i=0; i<array.count; i++) {
                  [tmparray addObject:[MyClass returntitlewithtitle:[array objectAtIndex:i]]];
              }
              return [tmparray componentsJoinedByString:@" | "];
          }else if ([condition isEqualToString:@"LeadStatus"]) {
              for (int i=0; i<array.count; i++) {
                  [tmparray addObject:[MyClass returntitlewithtitle:[array objectAtIndex:i]]];
              }
              return [tmparray componentsJoinedByString:@" | "];
          }else if ([condition isEqualToString:@"StudentStatus"]) {
              for (int i=0; i<array.count; i++) {
                  [tmparray addObject:[MyClass returntitlewithtitle:[array objectAtIndex:i]]];
              }
              return [tmparray componentsJoinedByString:@" | "];
          }else if ([condition isEqualToString:@"StaffGroup"]) {
              return [[MyClass returngrouparraylabel:array grouparray:[MyClass returnStaffGroupArrayIncludeAll:NO] option:@"groupkey"] string];
          }else if ([condition isEqualToString:@"Drop"]) {
              for (int i=0; i<array.count; i++) {
                  [tmparray addObject:[MyClass returntitlewithtitle:[array objectAtIndex:i]]];
              }
              return [tmparray componentsJoinedByString:@" | "];
          }else if ([condition isEqualToString:@"PaymentStatus"]) {
              for (int i=0; i<array.count; i++) {
                  [tmparray addObject:[MyClass returntitlewithtitle:[array objectAtIndex:i]]];
              }
              return [tmparray componentsJoinedByString:@" | "];
          }else if ([condition isEqualToString:@"Product"]) {
              for (int i=0; i<array.count; i++) {
                  [tmparray addObject:[MyClass returnproductnamewithproductcode:[array objectAtIndex:i] centerkey:globalvariables.centerrecord.centerkey]];
              }
              return [tmparray componentsJoinedByString:@" | "];
          }
      }
    return nil;
}

