+(NSString *) returnMarketingApplicationDescription:(MarketingRecord *)marketingobj
{
    if([marketingobj.subcategory isEqualToString:@"Class"]){
        if (!marketingobj.subjectarray) {
            return [MyClass returntitlewithtitle:@"Not applicable to any payment"];
        }else{
            if(marketingobj.subjectarray.count==0){
                return [MyClass returntitlewithtitle:@"Any subjects"];
            }else{
                return [MyClass returnsubjectnamewithsubjectkeys:marketingobj.subjectarray];
            }
        }
    }else if ([marketingobj.subcategory isEqualToString:@"Sales"]){
        if (!marketingobj.productarray) {
            return [MyClass returntitlewithtitle:@"Not applicable to any payment"];
        }else{
            if(marketingobj.productarray.count==0){
                return [MyClass returntitlewithtitle:@"Any products"];
            }else{
                return [MyClass returnproductnamewithproductkeys:marketingobj.productarray];
            }
        }
    }else{
        if(marketingobj.subjectarray && marketingobj.subjectarray.count==0 && marketingobj.productarray && marketingobj.productarray.count==0){
            return [MyClass returntitlewithtitle:@"Any subjects or products"];
        }else if(!marketingobj.subjectarray && !marketingobj.productarray){
            return [MyClass returntitlewithtitle:@"Not applicable to any payment"];
        }else if(!marketingobj.subjectarray){
            if (marketingobj.productarray.count==0) {
                return [MyClass returntitlewithtitle:@"Any products"];
            }else{
                return [MyClass returnproductnamewithproductkeys:marketingobj.productarray];
            }
        }else if(!marketingobj.productarray){
            if (marketingobj.subjectarray.count==0) {
                return [MyClass returntitlewithtitle:@"Any subjects"];
            }else{
                return [MyClass returnsubjectnamewithsubjectkeys:marketingobj.subjectarray];
            }
        }else if(marketingobj.subjectarray.count==0){
            return [MyClass returnreplacedtitlewithtitle:@"Applicable to %@1 and any subjects" replacementarray:@[[MyClass returnproductnamewithproductkeys:marketingobj.productarray]]];
        }else if (marketingobj.productarray.count==0){
            return [MyClass returnreplacedtitlewithtitle:@"Applicable to %@1 and any products" replacementarray:@[[MyClass returnsubjectnamewithsubjectkeys:marketingobj.subjectarray]]];
        }else{
            return [NSString stringWithFormat:@"%@ | %@",[MyClass returnsubjectnamewithsubjectkeys:marketingobj.subjectarray],[MyClass returnproductnamewithproductkeys:marketingobj.productarray]];
        }
    }
}

+(int) returnAgeFromDateOfBirth:(NSString *)dateOfBirth
{
    double time =[[NSDate date] timeIntervalSinceDate:[MyClass convertToNSDateWithDate:dateOfBirth DateFormat:@"dd-MMM-yyyy"]];
    int allDays = (((time/60)/60/24));
    int days=allDays%365;
    return (allDays-days)/365;
}

+(NSString *) returnAgeFromStudent:(Student *)student
{
    if(student.dateofbirth && ![student.dateofbirth isEqualToString:@""]){
        return [NSString stringWithFormat:@"%d",[self returnAgeFromDateOfBirth:student.dateofbirth]];
    }else{
        return student.age;
    }
}

