+(NSString *) removeleadingzero:(NSString *)string
{
    NSString *newstring=string;
    while ([newstring length]>0) {
        if ([[newstring substringToIndex:1] isEqualToString:@"0"]) {
            newstring=[newstring substringFromIndex:1];
        }else{
            break;
        }
    }
    return newstring;
}

+(NSString *) returnreceiptreference:(NSString *)paymentkey receiptnumber:(NSString *)receiptnumber
{
    NSString *trimmedreceiptnumber=[MyClass removeleadingzero:receiptnumber];
    if ([trimmedreceiptnumber isEqualToString:paymentkey]) {
        return paymentkey;
    }else{
        return [NSString stringWithFormat:@"%@/%@",trimmedreceiptnumber,paymentkey];
    }
}

