+ (NSData *)compressVideoSynchronouslyWithURL:(NSURL *)inputURL error:(NSError **)error {
    
    NSData *videoData = [[NSData alloc]initWithContentsOfURL:inputURL];
    
    if (![MyClass isPDFSizeNotExceedLimitWithData:videoData]) {
        // Create an AVAsset from the input URL
        AVAsset *asset = [AVAsset assetWithURL:inputURL];
        
        // Create an AVAssetExportSession with the desired preset
        AVAssetExportSession *exportSession = [AVAssetExportSession exportSessionWithAsset:asset presetName:AVAssetExportPresetMediumQuality];
        
        // Set the output file type (e.g., MP4)
        exportSession.outputFileType = AVFileTypeMPEG4;
        
        // Create a temporary file URL for the exported video
        NSString *tempFilePath = [NSTemporaryDirectory() stringByAppendingPathComponent:@"compressed_video.mp4"];
        NSURL *outputURL = [NSURL fileURLWithPath:tempFilePath];
        exportSession.outputURL = outputURL;
        
        // Optional: Optimize for network use
        exportSession.shouldOptimizeForNetworkUse = YES;
        
        // Create a semaphore to make the export synchronous
        dispatch_semaphore_t semaphore = dispatch_semaphore_create(0);
        
        __block NSData *compressedData = nil;
        __block NSError *exportError = nil;
        
        // Export the video
        [exportSession exportAsynchronouslyWithCompletionHandler:^{
            switch (exportSession.status) {
                case AVAssetExportSessionStatusCompleted: {
                    // Read the exported video file into NSData
                    compressedData = [NSData dataWithContentsOfURL:outputURL options:NSDataReadingMappedIfSafe error:&exportError];
                    
                    // Clean up the temporary file
                    [[NSFileManager defaultManager] removeItemAtURL:outputURL error:nil];
                    break;
                }
                case AVAssetExportSessionStatusFailed: {
                    exportError = exportSession.error;
                    break;
                }
                case AVAssetExportSessionStatusCancelled: {
                    exportError = [NSError errorWithDomain:@"VideoCompression" code:-1 userInfo:@{NSLocalizedDescriptionKey: @"Compression was cancelled."}];
                    break;
                }
                default: {
                    exportError = [NSError errorWithDomain:@"VideoCompression" code:-1 userInfo:@{NSLocalizedDescriptionKey: @"Compression failed for an unknown reason."}];
                    break;
                }
            }
            
            // Signal the semaphore to indicate completion
            dispatch_semaphore_signal(semaphore);
        }];
        
        // Wait for the export to complete
        dispatch_semaphore_wait(semaphore, DISPATCH_TIME_FOREVER);
        
        // If there was an error, set the error pointer
        if (exportError && error) {
            *error = exportError;
        }
        
        // Return the compressed data
        return compressedData;
    }else{
        return videoData;
    }
}

